    this.line('gc_mark_ptr((void*)ASC_tray_icon);');
    this.line('gc_mark_ptr((void*)ASC_app_menu);');
    this.line('gc_mark_ptr((void*)ASC_dock_menu);');
    this.line('gc_mark_ptr((void*)ASC_tray_menu);');
    this.line('gc_mark_ptr((void*)ASC_menu_tags);');
