    this.line('                            1,');
    this.line('#else');
    this.line('                            0,');
    this.line('#endif');
    this.line('                            gpu,');
    this.line('                            ASC_window_on_mouse, ASC_window_on_wheel, ASC_window_on_key,');
    this.line('                            ASC_window_on_redraw, ASC_window_on_frame,');
    this.line('                            ASC_window_on_frame_delay, ASC_window_on_resize,');
