    this.line('NativeWindow_ctor(o, options);');
    this.line('return o;');
    this.indent--;
    this.line('}');
    this.line('Stage* NativeWindow_get_stage(void* _this) {');
    this.indent++;
    this.line('ASCWin* w = ASC_w(((NativeWindow*)_this)->_win);');
