    // flash.errors.SQLError: an Error subclass carrying the failed SQL operation, a
    // detail message, a detail id and the substitution arguments. Hand-written for
    // the same reason as the Error family above (the generated ctor cannot store
    // extra values), with the measured AIR string forms (adl 51.4.1,
    // temp/airref/Main.as): a NULL operation/details stringifies to "null" like
    // Error's message, detailArguments is ALWAYS an Array, and toString() omits the
    // detailID segment while it is still the -1 sentinel.
    //
    // The PUBLIC constructor is AIR's own, (message, id) -- measured: `new
    // SQLError()` does not compile under mxmlc because message has no default. The
    // four SQL-specific values keep their "nothing known yet" state here and are
    // filled in by the engine through as_sql_mk_error() (the flash.data block).
    this.line('void SQLError_ctor(SQLError* o, char* message, int id) {');
    this.indent++;
    this.line('Error_ctor((Error*)o, message, id);');
    this.line('o->_operation = (char*)"null";');
    this.line('o->_details = (char*)"null";');
    this.line('o->_detailID = -1;');
    this.line('o->_detailArguments = as_array_new();');
    this.line('gc_write_barrier((void*)o->_detailArguments);');
    this.indent--;
    this.line('}');
    this.line('SQLError* SQLError_new(char* message, int id) {');
    this.indent++;
    this.line('SQLError* o = (SQLError*)gc_alloc(GCT_CLASS, sizeof(SQLError));');
    this.line('o->vtable = &SQLError_vt;');
    this.line('SQLError_ctor(o, message, id);');
    this.line('return o;');
    this.indent--;
    this.line('}');
    this.line('char* SQLError_get_operation(void* _this) { return ((SQLError*)_this)->_operation; }');
    this.line('char* SQLError_get_details(void* _this) { return ((SQLError*)_this)->_details; }');
    this.line('int SQLError_get_detailID(void* _this) { return ((SQLError*)_this)->_detailID; }');
    this.line('as_array* SQLError_get_detailArguments(void* _this) { return ((SQLError*)_this)->_detailArguments; }');
    this.line('char* SQLError_toString(void* _this) {');
    this.indent++;
    this.line('SQLError* e = (SQLError*)_this;');
    this.line('const char* parts[11]; int n = 0;');
    this.line('parts[n++] = "SQLError: \'"; parts[n++] = (e->message != NULL) ? e->message : ""; parts[n++] = "\', details:\'";');
    this.line('parts[n++] = (e->_details != NULL) ? e->_details : ""; parts[n++] = "\', operation:\'";');
    this.line('parts[n++] = (e->_operation != NULL) ? e->_operation : ""; parts[n++] = "\'";');
    this.line('if (e->_detailID >= 0) { parts[n++] = ", detailID:\'"; parts[n++] = as_str_from_int(e->_detailID); parts[n++] = "\'"; }');
    this.line('return as_str_concat_n(n, parts);');
    this.indent--;
    this.line('}');
    this.line('');
    // XML parse wrapper: as_xml_parse returns NULL on malformed input; the AS3
    // `new XML(bytes)` constructor must throw an Error instead of silently
    // degrading. Emitted here (not in RUNTIME_PREAMBLE) because it calls the
    // generated Error_new.
    this.line('static as_xml_node* as_xml_parse_checked(const char* src, int len) {');
    this.indent++;
    this.line('as_xml_node* n = as_xml_parse(src, len);');
    // The reference runtime raises a TypeError here, not a generic Error: #1085 for
    // an unterminated element, #1088 for markup outside the root element and #1090
    // for a malformed tag. The runtime records which one applied, so the message
    // and the id are the ones adl 51.4.1 prints (temp/e4xres/).
    this.line('if (n == NULL) as_throw(TypeError_new(as_xml_error_message(), as_xml_error_id()));');
    this.line('return n;');
    this.indent--;
    this.line('}');
    // Single-evaluation entry points: `new XML(expr)` must evaluate `expr` exactly
    // once (AS3 evaluates the argument once). Passing the value through one helper
    // argument avoids re-emitting a side-effecting expression such as
    // `new XML(bytes.readUTF())` — readUTF advances `position`, so a second read
    // yields the empty tail instead of the payload.
    this.line('static as_xml_node* as_xml_parse_str_checked(const char* src) {');
    this.indent++;
    this.line('return as_xml_parse_checked(src, src == NULL ? 0 : (int)strlen(src));');
    this.indent--;
    this.line('}');
    this.line('static as_xml_node* as_xml_parse_bytes_checked(ByteArray* bytes) {');
    this.indent++;
    this.line('if (bytes == NULL) return as_xml_parse_checked("", 0);');
    this.line('return as_xml_parse_checked(bytes->data == NULL ? "" : (const char*)bytes->data, (int)bytes->length);');
    this.indent--;
    this.line('}');
    // XML(value) where the value's kind is only known at runtime (Cast.xml passes a
    // `*`): E4X parses a String, returns an existing XML unchanged, and turns a
    // Number/Boolean into an element carrying that text. Only the String, XML,
    // XMLList and ByteArray cases are modelled -- the rest fail loudly rather than
    // inventing markup.
    this.line('static as_xml_node* as_xml_from_value(as_value v) {');
    this.indent++;
    this.line('if (v.tag == 3) return as_xml_parse_str_checked((char*)v.ptr);');
    this.line('if (v.tag == 4 && as_is(as_v_obj_val(v), &as_xml_vt)) return (as_xml_node*)as_v_obj_val(v);');
    // XML(xmlList): E4X returns the list\'s first node (XML(xmlList) on a one-item
    // list is the documented idiom, e.g. Config.as\'s XML(xml.ns::initialWindow)).
    // An EMPTY list yields NULL, which every navigation helper in this runtime
    // treats as \'no match\' rather than crashing.
    this.line('if (v.tag == 4 && as_is(as_v_obj_val(v), &as_xml_list_vt)) { as_xml_list* l = (as_xml_list*)as_v_obj_val(v); return l != NULL && l->length > 0 ? l->items[0] : NULL; }');
    // XML(byteArray): a ByteArray's BYTES are the markup, decoded as UTF-8. This is
    // the `[Embed(..., mimeType="application/octet-stream")]` + `XML(new Cls())`
    // idiom (Config/Language.as is the live case): the argument's static type is
    // `Class`, so it reaches this dynamic branch instead of the static
    // as_xml_parse_bytes_checked path. as_is walks the super chain, so every
    // [Embed] ByteArray SUBCLASS matches here too. Measured on adl 51.4.1: XML(ba)
    // over UTF-8 markup yields the parsed tree, and so does XML(new EmbeddedClass())
    // (temp/tkmeet-mac/xmlba).
    this.line('if (v.tag == 4 && as_is(as_v_obj_val(v), &ByteArray_vt)) return as_xml_parse_bytes_checked((ByteArray*)as_v_obj_val(v));');
    this.line('as_throw_unsupported("XML(value) is only supported for String, XML and ByteArray values by this subset");');
    this.line('return NULL;');
    this.indent--;
    this.line('}');
    this.line('');
    // built-in Date: stores milliseconds since the epoch; calendar accessors
    // convert through C's localtime() (AS3 getMonth/getDay are 0-based, matching
    // tm_mon/tm_wday). Constructors: () = now, (ms) = epoch ms, (string) = parsed,
    // (year, month, day, ...) = local calendar components.
    // `time` is a libc symbol (time.h), so the emitted struct field is sanitized
    // to `_time`; these hand-written accessors must use the same mangled name.
    this.line('void Date_ctor(Date* o) { o->_time = as_now_ms(); }');
    this.line('Date* Date_new(void) {');
    this.indent++;
    this.line('Date* o = (Date*)gc_alloc(GCT_CLASS, sizeof(Date));');
    this.line('o->vtable = &Date_vt;');
    this.line('Date_ctor(o);');
    this.line('return o;');
    this.indent--;
    this.line('}');
    this.line('Date* Date_new_ms(double ms) {');
    this.indent++;
    this.line('Date* o = (Date*)gc_alloc(GCT_CLASS, sizeof(Date));');
    this.line('o->vtable = &Date_vt;');
    this.line('o->_time = ms;');
    this.line('return o;');
    this.indent--;
    this.line('}');
    // Build a local-time epoch-ms timestamp from calendar components. AS3 maps
    // year 0..99 onto 1900..1999; mktime interprets the struct tm as local time.
    this.line('static double Date_mkms(int year, int mon, int day, int hour, int min, int sec, int ms) {');
    this.indent++;
    this.line('struct tm t;');
    this.line('memset(&t, 0, sizeof(t));');
    this.line('t.tm_year = (year >= 100) ? (year - 1900) : year;');
    this.line('t.tm_mon = mon;');
    this.line('t.tm_mday = day;');
    this.line('t.tm_hour = hour;');
    this.line('t.tm_min = min;');
    this.line('t.tm_sec = sec;');
    this.line('t.tm_isdst = -1;');
    this.line('time_t tt = mktime(&t);');
    this.line('return (double)tt * 1000.0 + (double)ms;');
    this.indent--;
    this.line('}');
    this.line('Date* Date_new_ymd(int year, int mon, int day, int hour, int min, int sec, int ms) {');
    this.indent++;
    this.line('Date* o = (Date*)gc_alloc(GCT_CLASS, sizeof(Date));');
    this.line('o->vtable = &Date_vt;');
    this.line('o->_time = Date_mkms(year, mon, day, hour, min, sec, ms);');
    this.line('return o;');
    this.indent--;
    this.line('}');
    // Font.enumerateFonts: the demo does not enumerate device fonts, so return
    // an empty array (SystemUtil.isEmbeddedFont consequently always answers false).
    this.line('as_array* Font_enumerateFonts_static(bool enumerateDeviceFonts) { (void)enumerateDeviceFonts; return as_array_new(); }');
    // Date.parse: accept "YYYY/MM/DD" / "YYYY-MM-DD" with an optional time part.
    this.line('double Date_parse_static(char* s) {');
    this.indent++;
    this.line('int year = 0, mon = 0, day = 1, hour = 0, min = 0, sec = 0;');
    this.line('int n = sscanf(s, "%d/%d/%d %d:%d:%d", &year, &mon, &day, &hour, &min, &sec);');
    this.line('if (n < 3) n = sscanf(s, "%d/%d/%d", &year, &mon, &day);');
    this.line('if (n < 3) n = sscanf(s, "%d-%d-%dT%d:%d:%d", &year, &mon, &day, &hour, &min, &sec);');
    this.line('if (n < 3) n = sscanf(s, "%d-%d-%d", &year, &mon, &day);');
    this.line('if (n < 3) return NAN;');
    this.line('return Date_mkms(year, mon - 1, day, hour, min, sec, 0);');
    this.indent--;
    this.line('}');
    this.line('static struct tm* Date_tm(Date* o) { time_t t = (time_t)(o->_time / 1000.0); return localtime(&t); }');
    this.line('double Date_getTime(void* _this) { return ((Date*)_this)->_time; }');
    // AMF3 bridges installed by as_amf_wire() (see emitAmfCodec): the runtime
    // codec stores a Date as a 0x08 marker plus 8 big-endian epoch milliseconds,
    // but cannot name the generated Date struct, so these two wrappers do.
    this.line('int as_amf_date_is(as_value v, double* ms) {');
    this.indent++;
    this.line('if (v.tag != 4 || v.ptr == NULL) return 0;');
    this.line('if (((as_object_header*)v.ptr)->vtable != (void*)&Date_vt) return 0;');
    this.line('*ms = ((Date*)v.ptr)->_time;');
    this.line('return 1;');
    this.indent--;
    this.line('}');
    this.line('as_value as_amf_date_new(double ms) { Date* d = Date_new(); d->_time = ms; return as_v_obj(d); }');
    this.line('int Date_getFullYear(void* _this) { return Date_tm((Date*)_this)->tm_year + 1900; }');
    this.line('int Date_getMonth(void* _this) { return Date_tm((Date*)_this)->tm_mon; }');
    this.line('int Date_getDate(void* _this) { return Date_tm((Date*)_this)->tm_mday; }');
    this.line('int Date_getDay(void* _this) { return Date_tm((Date*)_this)->tm_wday; }');
    this.line('int Date_getHours(void* _this) { return Date_tm((Date*)_this)->tm_hour; }');
    this.line('int Date_getMinutes(void* _this) { return Date_tm((Date*)_this)->tm_min; }');
    this.line('int Date_getSeconds(void* _this) { return Date_tm((Date*)_this)->tm_sec; }');
    // milliseconds / millisecondsUTC (AIR 2+ extension of the ES3 Date): the
    // millisecond component. The same expression serves both -- a UTC offset is a
    // whole number of minutes in every real time zone, so the sub-second component
    // is identical either way. The C `%` on a negative epoch must not go negative,
    // which is what the correction below is for.
    this.line('int Date_get_milliseconds(void* _this) { double raw = fmod(((Date*)_this)->_time, 1000.0); int ms = (int)raw; if (ms < 0) ms += 1000; return ms; }');
    this.line('void Date_set_milliseconds(void* _this, double value) {');
    this.indent++;
    this.line('Date* o = (Date*)_this;');
    // Keep the whole seconds, replace only the component. AIR truncates toward zero
    // and accepts any number (a value outside 0..999 rolls into the seconds, which
    // the floor() of the second line already expresses).
    this.line('double base = floor(o->_time / 1000.0) * 1000.0;');
    this.line('o->_time = base + value;');
    this.indent--;
    this.line('}');
    // The UTC namings of the same pair: every real zone offset is a whole number of
    // MINUTES, so the sub-second component is identical in local and UTC time and both
    // delegate to the expression above (AIR's millisecondsUTC differs from the
    // LOCAL one only in what the whole-second part belongs to).
    this.line('int Date_get_millisecondsUTC(void* _this) { return Date_get_milliseconds(_this); }');
    this.line('void Date_set_millisecondsUTC(void* _this, double value) { Date_set_milliseconds(_this, value); }');
    // The remaining local-time Date properties delegate straight to the getX()
    // methods above, so there is exactly one place that knows how a component is
    // read (Date_tm = localtime). `day` is read-only in AIR.
    this.line('int Date_get_fullYear(void* _this) { return Date_getFullYear(_this); }');
    this.line('int Date_get_month(void* _this) { return Date_getMonth(_this); }');
    this.line('int Date_get_date(void* _this) { return Date_getDate(_this); }');
    this.line('int Date_get_day(void* _this) { return Date_getDay(_this); }');
    this.line('int Date_get_hours(void* _this) { return Date_getHours(_this); }');
    this.line('int Date_get_minutes(void* _this) { return Date_getMinutes(_this); }');
    this.line('int Date_get_seconds(void* _this) { return Date_getSeconds(_this); }');
    // Component SETTERS (d.hours = 5, d.month = 12): AS3/ES3 assign the component on
    // the local calendar and let the DATE normalize -- setMonth(12) rolls into January
    // of the next year, setDate(31) in a 30-day month rolls into the 1st -- which is
    // exactly what mktime does with an over-range tm field, so the snapshot/mktime pair
    // reproduces the documented behaviour instead of re-deriving calendar arithmetic.
    // The sub-second part of the old value is carried over (mktime has no ms field),
    // and a non-finite component makes the whole date NaN, like AIR's setters.
    this.line('static void as_date_set_component(Date* o, int which, double value) {');
    this.indent++;
    this.line('if (!(value == value)) { o->_time = NAN; return; }  /* NaN component: the date is invalid */');
    this.line('struct tm t = *Date_tm(o);');
    this.line('switch (which) {');
    this.indent++;
    this.line('case 0: t.tm_year = (int)value - 1900; break;');
    this.line('case 1: t.tm_mon = (int)value; break;');
    this.line('case 2: t.tm_mday = (int)value; break;');
    this.line('case 3: t.tm_hour = (int)value; break;');
    this.line('case 4: t.tm_min = (int)value; break;');
    this.line('case 5: t.tm_sec = (int)value; break;');
    this.line('default: break;');
    this.indent--;
    this.line('}');
    this.line('t.tm_isdst = -1;  /* let mktime pick the DST offset for the new wall-clock time */');
    this.line('time_t secs = mktime(&t);');
    this.line('if (secs == (time_t)-1) { o->_time = NAN; return; }');
    this.line('double sub = fmod(o->_time, 1000.0); if (sub < 0) sub += 1000.0;');
    this.line('o->_time = (double)secs * 1000.0 + sub;');
    this.indent--;
    this.line('}');
    this.line('void Date_set_fullYear(void* _this, double value) { as_date_set_component((Date*)_this, 0, value); }');
    this.line('void Date_set_month(void* _this, double value) { as_date_set_component((Date*)_this, 1, value); }');
    this.line('void Date_set_date(void* _this, double value) { as_date_set_component((Date*)_this, 2, value); }');
    this.line('void Date_set_hours(void* _this, double value) { as_date_set_component((Date*)_this, 3, value); }');
    this.line('void Date_set_minutes(void* _this, double value) { as_date_set_component((Date*)_this, 4, value); }');
    this.line('void Date_set_seconds(void* _this, double value) { as_date_set_component((Date*)_this, 5, value); }');
    this.line('char* Date_toDateString(void* _this) {');
    this.indent++;
    this.line('struct tm* t = Date_tm((Date*)_this);');
    this.line('static const char* days[] = {"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};');
    this.line('static const char* months[] = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};');
    this.line('char* r = as_str_alloc(32);');
    this.line('snprintf(r, 32, "%s %s %02d %04d", days[t->tm_wday], months[t->tm_mon], t->tm_mday, t->tm_year + 1900);');
    this.line('return r;');
    this.indent--;
    this.line('}');
    // toTimeString: "HH:MM:SS GMT+HHMM (zone)" in AIR. Callers slice the first 8
    // characters (a clock), so the value is the local time and the zone suffix is
    // the numeric offset -- the zone NAME would need the platform tz database.
    this.line('char* Date_toTimeString(void* _this) {');
    this.indent++;
    this.line('struct tm* t = Date_tm((Date*)_this);');
    // The zone offset is local-vs-UTC for the same instant. `_time` holds
    // milliseconds as a double (the Date field), so it is converted to time_t
    // first: gmtime takes a time_t*, not the raw field (clang rejected the field
    // directly: incompatible pointer types double* -> const time_t*).
    this.line('time_t tt = (time_t)(((Date*)_this)->_time / 1000.0);');
    this.line('struct tm lt = *t, gt = *gmtime(&tt);');
    this.line('gt.tm_isdst = -1;');
    this.line('long off = (long)(mktime(&lt) - mktime(&gt));');
    this.line('char* r = as_str_alloc(48);');
    this.line('int hh = (int)(off / 3600), mm = (int)((off < 0 ? -off : off) % 3600) / 60;');
    this.line('snprintf(r, 48, "%02d:%02d:%02d GMT%c%02d%02d", t->tm_hour, t->tm_min, t->tm_sec, off < 0 ? \'-\' : \'+\', hh < 0 ? -hh : hh, mm);');
    this.line('return r;');
    this.indent--;
    this.line('}');
    // toLocaleTimeString(): AIR renders this through the locale's time pattern
    // ("5:31:00 AM" for en-US), which needs the locale database this backend does
    // not carry. The platform-independent part IS the local clock time, so it is
    // toTimeString's value without the zone suffix — documented approximation.
    this.line('char* Date_toLocaleTimeString(void* _this) {');
    this.indent++;
    this.line('char* full = Date_toTimeString(_this);');
    this.line('char* sp = strstr(full, " GMT");');
    this.line('if (sp == NULL) return full;');
    this.line('int n = (int)(sp - full);');
    this.line('char* r = as_str_alloc(n + 1);');
    this.line('memcpy(r, full, (size_t)n); r[n] = 0;');
    this.line('return r;');
    this.indent--;
    this.line('}');
    this.line('char* Date_toUTCString(void* _this) {');
    this.indent++;
    this.line('time_t t = (time_t)(((Date*)_this)->_time / 1000.0);');
    this.line('struct tm* g = gmtime(&t);');
    this.line('static const char* days[] = {"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};');
    this.line('static const char* months[] = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};');
    this.line('char* r = as_str_alloc(40);');
    this.line('snprintf(r, 40, "%s, %02d %s %04d %02d:%02d:%02d GMT", days[g->tm_wday], g->tm_mday, months[g->tm_mon], g->tm_year + 1900, g->tm_hour, g->tm_min, g->tm_sec);');
    this.line('return r;');
    this.indent--;
    this.line('}');
    this.line('');
    // built-in RegExp: compiles the pattern at construction (runtime), exposes
    // source/flags/lastIndex and the boolean flags, and provides exec/test.
    //
    // A pattern that does not compile is NOT an error in AVM2. RegExpObject's
    // completeInitialization() calls RegExp::compile() and then throws the
    // reported error away (avmplus core/RegExp.cpp stores it in *errorptr and
    // core/RegExpObject.cpp never reads it back), so the object survives with
    // m_compiledData == NULL and every exec returns < 0, i.e. "no match". ES3
    // says SyntaxError; AIR is the oracle here, so we keep the inert regex:
    // exec -> null, test -> false, String.replace -> subject unchanged.
    // Evidence: talkmed-meeting builds new RegExp("[") on EVERY recognised
    // real-time-translation sentence (AISubTitleSetupWindow.sqliteEscape), which
    // runs fine on adl but threw here and swallowed the whole subtitle stream.
    this.line('void RegExp_ctor(RegExp* o, char* pattern, char* flags) {');
    this.indent++;
    this.line('o->source = pattern;');
    this.line('o->flags = flags;');
    this.line('gc_write_barrier((void*)pattern);');
    this.line('gc_write_barrier((void*)flags);');
    this.line('o->lastIndex = 0;');
    this.line('o->global = (flags != NULL && strchr(flags, \'g\') != NULL);');
    this.line('o->ignoreCase = (flags != NULL && strchr(flags, \'i\') != NULL);');
    this.line('o->multiline = (flags != NULL && strchr(flags, \'m\') != NULL);');
    this.line('o->dotall = (flags != NULL && strchr(flags, \'s\') != NULL);');
    this.line('o->extended = (flags != NULL && strchr(flags, \'x\') != NULL);');
    this.line('o->compiled = as_regex_compile(pattern, flags);');
    this.line('// Inert when the pattern failed to compile: as_regex_search returns -1 on err.');
    this.indent--;
    this.line('}');
    this.line('RegExp* RegExp_new(char* pattern, char* flags) {');
    this.indent++;
    this.line('RegExp* o = (RegExp*)gc_alloc(GCT_CLASS, sizeof(RegExp));');
    this.line('o->vtable = &RegExp_vt;');
    this.line('RegExp_ctor(o, pattern, flags);');
    this.line('return o;');
    this.indent--;
    this.line('}');
    this.line('as_array* RegExp_exec(void* _this, char* s) {');
    this.indent++;
    this.line('RegExp* re = (RegExp*)_this;');
    this.line('if (re->compiled == NULL || re->compiled->err) return NULL;');
    this.line('int len = (int)strlen(s);');
    this.line('int cap[2 * (AS_RE_MAX_GROUPS + 1)];');
    this.line('for (int i = 0; i < 2 * (re->compiled->ngroups + 1); i++) cap[i] = -1;');
    this.line('int start = re->global ? re->lastIndex : 0;');
    this.line('int end = -1;');
    this.line('int m = as_regex_search(re->compiled, s, len, start, cap, &end);');
    this.line('if (m < 0) { if (re->global) re->lastIndex = 0; return NULL; }');
    this.line('if (re->global) re->lastIndex = end;');
    this.line('return as_regex_make_result(s, m, end, re->compiled, cap);');
    this.indent--;
    this.line('}');
    this.line('bool RegExp_test(void* _this, char* s) {');
    this.indent++;
    this.line('RegExp* re = (RegExp*)_this;');
    this.line('if (re->compiled == NULL || re->compiled->err) return false;');
    this.line('int len = (int)strlen(s);');
    this.line('int cap[2 * (AS_RE_MAX_GROUPS + 1)];');
    this.line('for (int i = 0; i < 2 * (re->compiled->ngroups + 1); i++) cap[i] = -1;');
    this.line('int start = re->global ? re->lastIndex : 0;');
    this.line('int end = -1;');
    this.line('int m = as_regex_search(re->compiled, s, len, start, cap, &end);');
    this.line('if (m < 0) { if (re->global) re->lastIndex = 0; return false; }');
    this.line('if (re->global) re->lastIndex = end;');
    this.line('return true;');
    this.indent--;
    this.line('}');
    this.line('');
    // ---- dynamic string method dispatch ----
    // A method invoked on a dynamically-typed (`*`) value that happens to be a
    // string at runtime. Strings are raw char* (no vtable), so as_dyn_call would
    // dereference the string data as an object header and crash. as_any_call
    // routes tag-3 receivers here; every method reuses the static string helpers.
    // match/search/replace accept either a RegExp object (tag 4) or a String
    // pattern (tag 3) per AS3 semantics.
    this.line('static as_value as_str_dyn_call(char* s, const char* name, as_value* args, int argc) {');
    this.indent++;
    this.line('if (strcmp(name, "match") == 0) {');
    this.indent++;
    this.line('as_regex* re = args[0].tag == 4 ? ((RegExp*)args[0].ptr)->compiled : as_regex_compile(as_v_str_val(args[0]), "");');
    this.line('int global = args[0].tag == 4 ? ((RegExp*)args[0].ptr)->global : 0;');
    this.line('return as_v_arr((void*)as_str_match_regex(s, re, global));');
    this.indent--;
    this.line('}');
    this.line('if (strcmp(name, "search") == 0) {');
    this.indent++;
    this.line('as_regex* re = args[0].tag == 4 ? ((RegExp*)args[0].ptr)->compiled : as_regex_compile(as_v_str_val(args[0]), "");');
    this.line('return as_v_num((double)as_str_search_regex(s, re));');
    this.indent--;
    this.line('}');
    this.line('if (strcmp(name, "replace") == 0) {');
    this.indent++;
    this.line('if (args[0].tag == 4) {');
    this.indent++;
    this.line('RegExp* re = (RegExp*)args[0].ptr;');
    this.line('return as_v_str(as_str_replace_regex(s, re->compiled, argc >= 2 ? as_v_str_val(args[1]) : "", re->global));');
    this.indent--;
    this.line('}');
    this.line('return as_v_str(as_str_replace(s, as_v_str_val(args[0]), argc >= 2 ? as_v_str_val(args[1]) : ""));');
    this.indent--;
    this.line('}');
    this.line('if (strcmp(name, "charAt") == 0) return as_v_str(as_str_charAt(s, as_v_int_cast(args[0])));');
    this.line('if (strcmp(name, "charCodeAt") == 0) return as_v_num((double)as_str_charCodeAt(s, as_v_int_cast(args[0])));');
    this.line('if (strcmp(name, "indexOf") == 0) return as_v_num((double)as_str_indexOf_from(s, as_v_str_val(args[0]), argc >= 2 ? as_v_int_cast(args[1]) : 0));');
    this.line('if (strcmp(name, "lastIndexOf") == 0) return as_v_num((double)as_str_lastIndexOf_from(s, as_v_str_val(args[0]), argc >= 2 ? as_v_int_cast(args[1]) : 0x7FFFFFFF));');
    this.line('if (strcmp(name, "substring") == 0) {');
    this.indent++;
    this.line('int from = as_v_int_cast(args[0]);');
    this.line('int to = argc >= 2 ? as_v_int_cast(args[1]) : (int)strlen(s);');
    this.line('return as_v_str(as_str_substring(s, from, to));');
    this.indent--;
    this.line('}');
    this.line('if (strcmp(name, "substr") == 0) {');
    this.indent++;
    this.line('int from = as_v_int_cast(args[0]);');
    this.line('int len = argc >= 2 ? as_v_int_cast(args[1]) : (int)strlen(s);');
    this.line('return as_v_str(as_str_substr(s, from, len));');
    this.indent--;
    this.line('}');
    this.line('if (strcmp(name, "slice") == 0) {');
    this.indent++;
    this.line('int from = as_v_int_cast(args[0]);');
    this.line('int to = argc >= 2 ? as_v_int_cast(args[1]) : (int)strlen(s);');
    this.line('return as_v_str(as_str_slice(s, from, to));');
    this.indent--;
    this.line('}');
    this.line('if (strcmp(name, "split") == 0) return as_v_arr((void*)as_str_split(s, as_v_str_val(args[0])));');
    this.line('if (strcmp(name, "toUpperCase") == 0) return as_v_str(as_str_toUpper(s));');
    this.line('if (strcmp(name, "toLowerCase") == 0) return as_v_str(as_str_toLower(s));');
    // AVM2 implements the locale aliases with the plain methods themselves --
    // core/String.as: `prototype.toLowerCase = prototype.toLocaleLowerCase = ...`
    // and the same pairing for toUpperCase. Missing them here is not a silent
    // miss: the call fell through to as_v_null(), the String-typed slot then held
    // NULL, and the next `name.indexOf(...)` (emitted with the #1009 null-receiver
    // guard) threw "Error #1009" out of ShareWindowView.selectItemView. AIR runs
    // that exact line (sourceName.toLocaleLowerCase()) and matches "wps office".
    this.line('if (strcmp(name, "toLocaleLowerCase") == 0) return as_v_str(as_str_toLower(s));');
    this.line('if (strcmp(name, "toLocaleUpperCase") == 0) return as_v_str(as_str_toUpper(s));');
    // concat(...args) folds the receiver with each argument in order, exactly like
    // the static path's as_str_concat_n; as_str_concat substitutes "null" for a
    // NULL part (ES3 ToString(null)), so a null argument cannot strlen(NULL).
    this.line('if (strcmp(name, "concat") == 0) {');
    this.indent++;
    this.line('char* r = s;');
    this.line('for (int i = 0; i < argc; i++) r = as_str_concat(r, as_v_str_val(args[i]));');
    this.line('return as_v_str(r);');
    this.indent--;
    this.line('}');
    // localeCompare/startsWith/endsWith take `other:*`, so the argument is a
    // boxed value that must be stringified the same way the static path does.
    this.line('if (strcmp(name, "localeCompare") == 0) {');
    this.indent++;
    this.line('const char* o = argc >= 1 ? as_v_str_val(args[0]) : "undefined";');
    this.line('return as_v_num((double)as_str_localeCompare(s, o == NULL ? "null" : o));');
    this.indent--;
    this.line('}');
    this.line('if (strcmp(name, "startsWith") == 0) {');
    this.indent++;
    this.line('const char* o = argc >= 1 ? as_v_str_val(args[0]) : "undefined";');
    this.line('return as_v_bool(as_str_startsWith(s, o == NULL ? "null" : o));');
    this.indent--;
    this.line('}');
    this.line('if (strcmp(name, "endsWith") == 0) {');
    this.indent++;
    this.line('const char* o = argc >= 1 ? as_v_str_val(args[0]) : "undefined";');
    this.line('return as_v_bool(as_str_endsWith(s, o == NULL ? "null" : o));');
    this.indent--;
    this.line('}');
    this.line('if (strcmp(name, "toString") == 0 || strcmp(name, "valueOf") == 0) return as_v_str(s);');
    this.line('return as_v_null();');
    this.indent--;
    this.line('}');
    this.line('');
    this.line('static as_value as_any_call(as_value v, const char* name, as_value* args, int argc) {');
    this.indent++;
    // Calling a method on null/undefined throws #1009/#1010 (measured on adl
    // 51.4.1: `var y:* = null; y.bar()` -> #1009).
    this.line('v = as_req_box(v);');
    this.line('if (v.tag == 3) return as_str_dyn_call((char*)v.ptr, name, args, argc);');
    // An Array is not an object with a vtable: passing it to as_dyn_call would
    // read the vtable header out of its element buffer and crash (measured:
    // `var a:* = [1,2]; a.toString()` segfaulted before this branch). The dynamic
    // receiver resolves the Array method set by name instead.
    this.line('if (v.tag == 6) return as_arr_call((as_array*)v.ptr, name, args, argc);');
    this.line('return as_dyn_call(v.ptr, name, args, argc);');
    this.indent--;
    this.line('}');
    this.line('');
    // ---- flash.events core engine (stage 33) ----
    // Listener-table keys are "<type>#cap" / "<type>#bub"; as_object stores them
    // to an as_array of boxed as_fn closures. The key lives in the arena (program
    // lifetime), so as_object's pointer-keyed storage is safe.
    this.line('static char* as_disp_key(const char* type, bool capture) {');
    this.indent++;
    this.line('size_t n = strlen(type) + 5;');
    this.line('char* k = as_str_alloc(n);');
    this.line('snprintf(k, n, "%s#%s", type, capture ? "cap" : "bub");');
    this.line('return k;');
    this.indent--;
    this.line('}');
    // Lookup-only variant: build the same key in a caller-provided stack buffer
    // so the per-frame event dispatch path (as_disp_phase/as_disp_target) does
    // not leak an arena allocation for every listener probe. as_disp_key above
    // is kept only for addEventListener, which stores the key persistently.
    this.line('static as_value as_listeners_get(as_object* listeners, const char* type, bool capture) {');
    this.indent++;
    this.line('if (listeners == NULL) return as_v_null();');
    this.line('char k[64];');
    this.line('snprintf(k, sizeof(k), "%s#%s", type, capture ? "cap" : "bub");');
    this.line('return as_object_get(listeners, k);');
    this.indent--;
    this.line('}');
    // ENTER_FRAME is a broadcast event: it must reach every object that
    // registered an "enterFrame" listener, including objects NOT on the display
    // list (GreenSock drives its tweens from a private static Shape).
    // as_ef_objs holds one slot per such object (deduplicated by pointer).
    this.line('static void** as_ef_objs = NULL;');
    this.line('static int as_ef_count = 0;');
    this.line('static int as_ef_cap = 0;');
    this.line('static void as_ef_register(void* obj) {');
    this.indent++;
    this.line('for (int i = 0; i < as_ef_count; i++) if (as_ef_objs[i] == obj) return;');
    this.line('if (as_ef_count == as_ef_cap) {');
    this.indent++;
    this.line('as_ef_cap = as_ef_cap == 0 ? 8 : as_ef_cap * 2;');
    this.line('as_ef_objs = (void**)realloc(as_ef_objs, (size_t)as_ef_cap * sizeof(void*));');
    this.indent--;
    this.line('}');
    this.line('as_ef_objs[as_ef_count++] = obj;');
    this.indent--;
    this.line('}');
    this.line('static void as_ef_unregister(void* obj) {');
    this.indent++;
    this.line('EventDispatcher* d = (EventDispatcher*)obj;');
    this.line('if (d->listeners != NULL) {');
    this.indent++;
    this.line('as_value vc = as_listeners_get(d->listeners, "enterFrame", true);');
    this.line('as_value vb = as_listeners_get(d->listeners, "enterFrame", false);');
    this.line('if ((vc.tag == 6 && ((as_array*)vc.ptr)->length > 0) || (vb.tag == 6 && ((as_array*)vb.ptr)->length > 0)) return;');
    this.indent--;
    this.line('}');
    this.line('for (int i = 0; i < as_ef_count; i++) {');
    this.indent++;
    this.line('if (as_ef_objs[i] == obj) { as_ef_objs[i] = as_ef_objs[--as_ef_count]; return; }');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    // ---- dispatch-time listener snapshot ----
    // AIR (AVM2) walks the listener list AS IT STOOD when the phase started:
    //   C1 a listener removes ITSELF      -> the next one still runs         (A,B)
    //   C2 a listener removes the NEXT    -> that one still runs this time   (A,B)
    //   C3 a listener ADDS one            -> waits for the next dispatch     (A)
    //   C4 remove itself, then re-add     -> both run, exactly once          (A,B)
    // measured on adl 51.4.1, temp/disprem (C1b/C3b cover the follow-up dispatch).
    //
    // Walking the live array in place cannot express that: a removal shifted the
    // rest down (so the loop's index skipped the entry AFTER the removed one) and an
    // addition could appear mid-walk. The skipped entry is not academic -- the app
    // registers FixStageDpi's Event.CLOSE handler before the window's own one, and
    // that first handler removes itself, so the window's cleanup never ran, its
    // static singleton stayed behind, and the 设置/资料库 window could never be
    // opened a second time (temp/nwreopen: closeCount=0 before, 1 after).
    //
    // So a phase walks a SNAPSHOT copy while add/remove stay immediate on the live
    // list. The copies live in rooted buffers reused per dispatch nesting level: no
    // allocation in the steady state, and a closure an earlier listener removed is
    // still reachable from the GC even if some listener calls System.gc().
    // `as_disp_depth` counts nested dispatchEvent calls (the frame guard restores it
    // to 0 when an uncaught exception unwinds a dispatch).
    this.line('#define AS_DISP_SNAP_SLOTS 8');
    this.line('static as_array* as_disp_snaps[AS_DISP_SNAP_SLOTS];');
    this.line('static int as_disp_snaps_reg = 0;');
    this.line('static int as_disp_depth = 0;');
    // Invoke each listener in an array with the single Event argument. An as_fn
    // closure takes (env, as_value*, argc); immStopped stops the remaining ones.
    // Returns whether at least one listener actually ran. AIR uses that fact:
    // a dispatch that delivers to nobody leaves `event.target` alone (measured
    // on adl 51.4.1 -- temp/dispprobe, probes 1/6/7: no listener anywhere keeps
    // target == null), while a delivering dispatch claims it.
    this.line('static bool as_disp_arr(as_array* arr, Event* evt) {');
    this.indent++;
    // A one-entry list has nothing that a mutation could hide (the single listener
    // is already running), so the common case skips the copy entirely.
    this.line('int slot = as_disp_depth - 1;');
    this.line('if (arr->length > 1 && slot >= 0 && slot < AS_DISP_SNAP_SLOTS) {');
    this.indent++;
    this.line('if (!as_disp_snaps_reg) {');
    this.indent++;
    this.line('as_disp_snaps_reg = 1;');
    this.line('for (int i = 0; i < AS_DISP_SNAP_SLOTS; i++) gc_root_register((void**)&as_disp_snaps[i]);');
    this.indent--;
    this.line('}');
    this.line('as_array* snap = as_disp_snaps[slot];');
    this.line('if (snap == NULL) { snap = as_array_new(); as_disp_snaps[slot] = snap; }');
    this.line('snap->length = 0;');
    this.line('for (int i = 0; i < arr->length; i++) as_array_push(snap, arr->data[i]);');
    this.line('arr = snap;');
    this.indent--;
    this.line('}');
    this.line('bool ran = false;');
    this.line('int n = arr->length;');
    this.line('for (int i = 0; i < n; i++) {');
    this.indent++;
    this.line('if (evt->immStopped) break;');
    this.line('as_fn fn = (as_fn)as_v_obj_val(arr->data[i]);');
    this.line('as_value arg[1];');
    this.line('arg[0] = as_v_obj((void*)evt);');
    this.line('fn->fn(fn->env, arg, 1);');
    this.line('ran = true;');
    this.indent--;
    this.line('}');
    this.line('return ran;');
    this.indent--;
    this.line('}');
    // Walk up the parent chain (display list in later stages; NULL for now).
    this.line('static void* as_disp_parent(void* obj) { return (void*)((EventDispatcher*)obj)->parent; }');
    // One phase at one target: set currentTarget, then run the listeners for the
    // capture or bubble key of the event type.
    this.line('static bool as_disp_phase(Event* evt, void* current, bool capture) {');
    this.indent++;
    this.line('EventDispatcher* d = (EventDispatcher*)current;');
    this.line('evt->currentTarget = (Object*)current;');
    this.line('if (d->listeners == NULL) return false;');
    this.line('as_value v = as_listeners_get(d->listeners, evt->type, capture);');
    this.line('if (v.tag == 6) return as_disp_arr((as_array*)v.ptr, evt);');
    this.line('return false;');
    this.indent--;
    this.line('}');
    // Target phase: the target runs ONLY its non-capture (bubble) listeners.
    //
    // AIR never runs a useCapture listener registered on the TARGET itself: the
    // capture phase walks from the root down to the target's PARENT, and AT_TARGET
    // consults only the bubble list. Measured on adl 51.4.1 (temp/dupprobe, cases
    // F/G/H): a capture-only listener on a bare EventDispatcher never runs (0), and
    // on a p->c chain a dispatch from `c` gives p.cap@1, c.bub@2, p.bub@3 -- the
    // target's own capture listener is absent. Running both lists here (as this did)
    // fired the target's capture listener too, which AIR never does.
    this.line('static bool as_disp_target(Event* evt, void* target) {');
    this.indent++;
    this.line('evt->eventPhase = 2;');
    this.line('evt->currentTarget = (Object*)target;');
    this.line('EventDispatcher* d = (EventDispatcher*)target;');
    this.line('if (d->listeners == NULL) return false;');
    // AT_TARGET consults the NON-capture list only. AIR's capture phase walks root
    // -> target's PARENT, so a useCapture listener registered on the target itself
    // never runs (measured on adl 51.4.1, temp/dupprobe cases D/F/G/H: a capture-only
    // listener on a bare dispatcher fires zero times, and a dispatch from `c` on a
    // p->c chain gives p.cap@1, c.bub@2, p.bub@3). Running the capture list here as
    // well double-fired such listeners -- which for the drag idiom (a container that
    // registers its own MOUSE_DOWN with capture) means the handler runs twice and the
    // second run sees state the first one already consumed.
    this.line('as_value vb = as_listeners_get(d->listeners, evt->type, false);');
    this.line('if (vb.tag == 6) return as_disp_arr((as_array*)vb.ptr, evt);');
    this.line('return false;');
    this.indent--;
    this.line('}');
    this.line('');
    // built-in Event: constructor copies type/bubbles/cancelable and zeroes the
    // target/currentTarget/phase plus the three propagation flags.
    this.line('void Event_ctor(Event* o, char* type, bool bubbles, bool cancelable) {');
    this.indent++;
    this.line('o->type = type;');
    this.line('gc_write_barrier((void*)type);');
    this.line('o->bubbles = bubbles;');
    this.line('o->cancelable = cancelable;');
    this.line('o->target = NULL;');
    this.line('o->currentTarget = NULL;');
    // AIR constructs an event already AT_TARGET (`new Event("x", true, true).toString()`
    // reports eventPhase=2 on adl 51.4.1; measured in temp/evtdefprobe).
    this.line('o->eventPhase = 2;');
    this.line('o->cancelled = false;');
    this.line('o->propStopped = false;');
    this.line('o->immStopped = false;');
    this.indent--;
    this.line('}');
    this.line('Event* Event_new(char* type, bool bubbles, bool cancelable) {');
    this.indent++;
    this.line('Event* o = (Event*)gc_alloc(GCT_CLASS, sizeof(Event));');
    this.line('o->vtable = &Event_vt;');
    this.line('Event_ctor(o, type, bubbles, cancelable);');
    this.line('return o;');
    this.indent--;
    this.line('}');
    // AIR's Event.formatToString(className, ...propertyNames): "[" + className,
    // then " name=value" per extra argument, then "]" -- a String value is
    // DOUBLE-QUOTED, every other value is rendered by its own string form
    // (measured on adl 51.4.1, temp/airref/Main.as: `[MyEv type="click" bubbles=false
    // cancelable=false eventPhase=2]`, a Number as `myNum=5`, null as `myNull=null`,
    // and no extras at all as `[OnlyName]`). Each property is read back BY NAME
    // through the dynamic reader, so a name the receiver does not carry raises
    // exactly the ReferenceError #1069 AIR raises (as_throw_sealed_get).
    this.line('char* Event_formatToString(void* _this, char* className, as_array* arguments) {');
    this.indent++;
    this.line('char* out = as_str_concat("[", className);');
    this.line('int n = (arguments != NULL) ? arguments->length : 0;');
    this.line('for (int i = 0; i < n; i++) {');
    this.indent++;
    this.line('char* name = as_v_str_val(as_array_get(arguments, i));');
    this.line('out = as_str_concat(out, " ");');
    this.line('out = as_str_concat(out, name);');
    this.line('out = as_str_concat(out, "=");');
    this.line('as_value v = as_dyn_get((void*)_this, name);');
    this.line('if (v.tag == 3) { out = as_str_concat(out, "\\""); out = as_str_concat(out, (char*)v.ptr); out = as_str_concat(out, "\\""); }');
    this.line('else out = as_str_concat(out, as_v_str_val(v));');
    this.indent--;
    this.line('}');
    this.line('return as_str_concat(out, "]");');
    this.indent--;
    this.line('}');
    this.line('char* Event_toString(void* _this) {');
    this.indent++;
    this.line('Event* e = (Event*)_this;');
    this.line('char* r = as_str_alloc(128);');
    this.line('snprintf(r, 128, "[Event type=\\"%s\\" bubbles=%s cancelable=%s eventPhase=%d]",');
    this.line('  e->type ? e->type : "", e->bubbles ? "true" : "false", e->cancelable ? "true" : "false", e->eventPhase);');
    this.line('return r;');
    this.indent--;
    this.line('}');
    this.line('Event* Event_clone(void* _this) {');
    this.indent++;
    this.line('Event* e = (Event*)_this;');
    this.line('Event* c = Event_new(e->type, e->bubbles, e->cancelable);');
    this.line('c->target = e->target;');
    this.line('return c;');
    this.indent--;
    this.line('}');
    this.line('void Event_preventDefault(void* _this) { Event* e = (Event*)_this; if (e->cancelable) e->cancelled = true; }');
    this.line('bool Event_isDefaultPrevented(void* _this) { return ((Event*)_this)->cancelled; }');
    this.line('void Event_stopPropagation(void* _this) { ((Event*)_this)->propStopped = true; }');
    this.line('void Event_stopImmediatePropagation(void* _this) { Event* e = (Event*)_this; e->propStopped = true; e->immStopped = true; }');
    this.line('');
    // built-in EventDispatcher: listeners table (lazily allocated) + parent link.
    // The `target` constructor argument is AIR's dispatch target: an
    // `new EventDispatcher(this)` relays its events with `this` as event.target
    // (away3d's CascadeShadowMapper relies on that), so it is kept in its own slot
    // rather than being folded onto the display `parent` link, which drives
    // event bubbling and root resolution.
    this.line('void EventDispatcher_ctor(EventDispatcher* o, Object* target) { o->listeners = NULL; o->parent = NULL; o->_evtarget = target; if (target != NULL) gc_write_barrier((void*)target); }');
    this.line('EventDispatcher* EventDispatcher_new(Object* target) {');
    this.indent++;
    this.line('EventDispatcher* o = (EventDispatcher*)gc_alloc(GCT_CLASS, sizeof(EventDispatcher));');
    this.line('o->vtable = &EventDispatcher_vt;');
    this.line('EventDispatcher_ctor(o, target);');
    this.line('return o;');
    this.indent--;
    this.line('}');
    this.line('void EventDispatcher_addEventListener(void* _this, char* type, as_fn listener, bool useCapture, int priority, bool useWeakReference) {');
    this.indent++;
    this.line('(void)priority; (void)useWeakReference; // priority/weak-ref are accepted but not reordered in this subset');
    this.line('EventDispatcher* d = (EventDispatcher*)_this;');
    this.line('if (d->listeners == NULL) d->listeners = as_object_new();');
    this.line('char* key = as_disp_key(type, useCapture);');
    this.line('as_value v = as_object_get(d->listeners, key);');
    this.line('as_array* arr;');
    this.line('if (v.tag == 6) { arr = (as_array*)v.ptr; }');
    this.line('else { arr = as_array_new(); as_object_set(d->listeners, key, as_v_arr((void*)arr)); }');
    // AIR does NOT register the same listener twice: a second addEventListener with
    // the same listener function AND the same receiver AND the same useCapture is a
    // no-op (measured on adl 51.4.1, temp/dupprobe cases A/B/C: the very same closure
    // added twice runs once; a bound method added twice -- two distinct closures over
    // one method+receiver -- also runs once; add twice then remove once runs zero
    // times, i.e. there was only ever one entry). Appending the duplicate instead
    // made dual-registered handlers run twice and made removeEventListener (which
    // removes one entry) leave a stray listener behind -- the TalkMED home page's
    // scrollbars re-register MOUSE_DOWN from a subclassed ADDED_TO_STAGE hook that
    // does not remove itself (com.vsdevelop.proxy.ViewControl's base one does), so the
    // drag installed TWO stage mouseMove/mouseUp pairs, one mouseUp removed only one
    // of them, and the leftover pair kept running the app's drag code -- which
    // disables mouse on the scrolled container and never bounces the flick back
    // (measured: temp/tkmeet-mac d28dbg.txt; pinned by examples/listener_identity.as).
    this.line('for (int i = 0; i < arr->length; i++) {');
    this.indent++;
    this.line('as_fn a = (as_fn)as_v_obj_val(arr->data[i]);');
    this.line('if (a->fn == listener->fn && a->env == listener->env) return;');
    this.indent--;
    this.line('}');
    this.line('as_array_push(arr, as_v_obj((void*)listener));');
    this.line('if (strcmp(type, "enterFrame") == 0) as_ef_register(_this);');
    this.indent--;
    this.line('}');
    this.line('void EventDispatcher_removeEventListener(void* _this, char* type, as_fn listener, bool useCapture) {');
    this.indent++;
    this.line('EventDispatcher* d = (EventDispatcher*)_this;');
    this.line('if (d->listeners == NULL) return;');
    this.line('as_value v = as_listeners_get(d->listeners, type, useCapture);');
    this.line('if (v.tag != 6) return;');
    this.line('as_array* arr = (as_array*)v.ptr;');
    this.line('for (int i = 0; i < arr->length; i++) {');
    this.indent++;
    // AS3 removes by *function identity* (same implementation + same bound
    // receiver), not closure-pointer identity. Each `this.method` reference
    // allocates a fresh closure, so comparing the closure pointer would make
    // removeEventListener a no-op for bound methods.
    this.line('as_fn a = (as_fn)as_v_obj_val(arr->data[i]);');
    this.line('if (a->fn == listener->fn && a->env == listener->env) {');
    this.indent++;
    this.line('for (int j = i; j < arr->length - 1; j++) arr->data[j] = arr->data[j + 1];');
    this.line('arr->length--;');
    this.line('if (strcmp(type, "enterFrame") == 0) as_ef_unregister(_this);');
    this.line('return;');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('bool EventDispatcher_hasEventListener(void* _this, char* type) {');
    this.indent++;
    this.line('EventDispatcher* d = (EventDispatcher*)_this;');
    this.line('if (d->listeners == NULL) return false;');
    this.line('as_value vc = as_listeners_get(d->listeners, type, true);');
    this.line('as_value vb = as_listeners_get(d->listeners, type, false);');
    // The live list is the answer: add/remove stay immediate, only the walk order is
    // frozen (see as_disp_arr), so a handler that removed itself is really gone by the
    // time anyone asks afterwards.
    this.line('return (vc.tag == 6 && ((as_array*)vc.ptr)->length > 0) || (vb.tag == 6 && ((as_array*)vb.ptr)->length > 0);');
    this.indent--;
    this.line('}');
    this.line('bool EventDispatcher_willTrigger(void* _this, char* type) { return EventDispatcher_hasEventListener(_this, type); }');
    this.line('bool EventDispatcher_dispatchEvent(void* _this, Event* event) {');
    this.indent++;
    // AIR: an EventDispatcher built with an explicit target relays every event with
    // that object as the target; otherwise the dispatcher itself is the target.
    //
    // The event's `target` is claimed by the dispatcher that actually delivers:
    // listeners see the dispatcher as their target (measured -- a listener list on
    // the *previous* dispatcher must NOT run again, adl 51.4.1 temp/dispprobe probe
    // 8/9: `d2.dispatchEvent(e)` after d1 dispatched e runs only d2's listeners).
    // What happens to the field afterwards is also AIR-measured (probe 10 sweep):
    //   * nobody listened        -> leave the field alone (a no-op dispatch must not
    //                               make `e.target` become the dispatcher)
    //   * event was untargeted    -> it keeps the claiming dispatcher
    //   * event was already targeted (a re-dispatch, e.g. away3d's fake bubbling
    //     re-dispatching a lens event from the camera) -> swap for the duration and
    //     restore the previous target afterwards (nested re-dispatch included).
    this.line('EventDispatcher* disp = (EventDispatcher*)_this;');
    // Entering a dispatch: as_disp_arr takes its snapshot from the nesting level
    // (see AS_DISP_SNAP_SLOTS above), so the depth must be exact.
    this.line('as_disp_depth++;');
    this.line('void* own = disp->_evtarget != NULL ? disp->_evtarget : _this;');
    this.line('Object* savedTarget = event->target;');
    this.line('event->target = (Object*)own;');
    // Build the ancestor chain in a fixed stack buffer instead of an arena array:
    // dispatchEvent runs every frame for ENTER_FRAME, and a per-call as_array_new()
    // + as_array_push() leaked an arena slot (never reclaimed) on every dispatch.
    this.line('void* ancestors[64];');
    this.line('int anc_count = 0;');
    this.line('for (void* p = as_disp_parent(own); p != NULL && anc_count < 64; p = as_disp_parent(p)) ancestors[anc_count++] = p;');
    this.line('bool ran = false;');
    this.line('event->eventPhase = 1; // CAPTURING (outermost -> target parent)');
    this.line('for (int i = anc_count - 1; i >= 0; i--) { if (event->propStopped) break; if (as_disp_phase(event, ancestors[i], true)) ran = true; }');
    this.line('if (!event->propStopped && as_disp_target(event, own)) ran = true;');
    this.line('event->eventPhase = 3; // BUBBLING (target parent -> outermost)');
    this.line('if (event->bubbles) { for (int i = 0; i < anc_count; i++) { if (event->propStopped) break; if (as_disp_phase(event, ancestors[i], false)) ran = true; } }');
    this.line('if (!ran || savedTarget != NULL) event->target = savedTarget;');
    this.line('as_disp_depth--;');
    this.line('return !event->cancelled;');
    this.indent--;
    this.line('}');
    this.line('');
    // flash.desktop.NativeApplication: a single global EventDispatcher-backed
    // singleton (window activate/deactivate events). Lazily constructed and
    // registered as a GC permanent root.
    this.line('void NativeApplication_ctor(NativeApplication* o) { EventDispatcher_ctor((EventDispatcher*)o, NULL); }');
    this.line('NativeApplication* NativeApplication_new(void) {');
    this.indent++;
    this.line('NativeApplication* o = (NativeApplication*)gc_alloc(GCT_CLASS, sizeof(NativeApplication));');
    this.line('o->vtable = &NativeApplication_vt;');
    this.line('NativeApplication_ctor(o);');
    this.line('return o;');
    this.indent--;
    this.line('}');
    this.line('static NativeApplication* ASC_native_app = NULL;');
    // systemIdleMode lives in a file-scope string so a get/set pair round-trips
    // through the singleton; AIR's default is SystemIdleMode.NORMAL.
    this.line('static char* ASC_idle_mode = (char*)"normal";');
    this.line('NativeApplication* NativeApplication_get_nativeApplication_static(void* _this) {');
    this.indent++;
    this.line('(void)_this;');
    this.line('if (ASC_native_app == NULL) ASC_native_app = NativeApplication_new();');
    this.line('return ASC_native_app;');
    this.indent--;
    this.line('}');
    this.line('char* NativeApplication_get_systemIdleMode(void* _this) { (void)_this; return ASC_idle_mode; }');
    // Setting it stores the value (so a read-back agrees with what was written, the
    // way AIR reports the mode it is in) but the idle-timer part has no backend, so
    // a KEEP_AWAKE request is reported once rather than silently ignored.
    this.line('void NativeApplication_set_systemIdleMode(void* _this, char* value) { (void)_this; ASC_idle_mode = value; if (value != NULL && strcmp(value, "keepAwake") == 0) as_shell_unsupported((char*)"flash.desktop.NativeApplication.systemIdleMode (this build never inhibits the system idle timer)"); }');
    // ---- NativeApplication: icon / menu / autoExit / capability bits (阶段二百五十五) ----
    // The statics live here (not in the menu block below) because the setters and
    // getters are emitted here; the menu subsystem further down only uses them.
    this.line('static NativeMenu* ASC_app_menu = NULL;');
    this.line('static NativeMenu* ASC_dock_menu = NULL;');
    this.line('static as_array* ASC_menu_tags = NULL;');
    this.line('static DockIcon* ASC_icon_singleton = NULL;');
    // The tray icon and its menu: C statics on purpose (the Cocoa status item points
    // at the same NSMenu), so both are permanent GC roots too -- see
    // gc_mark_user_roots. Declared unconditionally so that block compiles with the
    // tray switch off.
    this.line('static SystemTrayIcon* ASC_tray_icon = NULL;');
    this.line('static NativeMenu* ASC_tray_menu = NULL;');
    this.line('static void as_menu_sync(NativeMenu* from);');
    // autoExit is REAL, not just stored: the shared event loop keeps running with
    // zero open windows while it is false. Measured on adl 51.4.1 (temp/deskprobe2/
    // probe5-log.txt): autoExit=false + a hidden window keeps the app alive, which
    // is the Dock-icon-only shape this demo's fallback needs.
    this.line('static bool ASC_auto_exit = true;');
    this.line('bool NativeApplication_get_autoExit(void* _this) { (void)_this; return ASC_auto_exit; }');
    this.line('void NativeApplication_set_autoExit(void* _this, bool value) { (void)_this; ASC_auto_exit = value; sk_window_set_auto_exit(value ? 1 : 0); }');
    // Measured: reading na.menu on adl hands back adl's OWN four-item menu, never
    // null. This backend has no menu model of its own before the app installs one,
    // so it answers an EMPTY NativeMenu rather than null -- the shape a real AIR app
    // sees (a menu object) and the one an `if (na.menu) { ... }` guard expects.
    this.line('NativeMenu* NativeApplication_get_menu(void* _this) {');
    this.indent++;
    this.line('(void)_this;');
    this.line('if (ASC_app_menu == NULL) { ASC_app_menu = NativeMenu_new(); gc_write_barrier((void*)ASC_app_menu); }');
    this.line('return ASC_app_menu;');
    this.indent--;
    this.line('}');
    // Measured: assigning a NativeMenu really replaces the Cocoa menu bar (the
    // process's AX tree then reports the new top-level item). AIR CRASHES on
    // `na.menu = null` (the process dies inside the assignment), so a null write is
    // refused loudly instead of being replicated.
    this.line('void NativeApplication_set_menu(void* _this, NativeMenu* value) {');
    this.indent++;
    this.line('(void)_this;');
    this.line('if (value == NULL) { as_shell_unsupported((char*)"flash.desktop.NativeApplication.menu = null (adl crashes on this; the menu is left unchanged)"); return; }');
    this.line('ASC_app_menu = value; gc_write_barrier((void*)value);');
    this.line('as_menu_sync(value);');
    this.indent--;
    this.line('}');
    // AIR answers #2014 under adl ("Feature is not available at this time.") because
    // the app is not installed; this build never had a login-item backend at all, so
    // it reports the same error rather than inventing a boolean.
    this.line('bool NativeApplication_get_startAtLogin(void* _this) { (void)_this; as_throw(IllegalOperationError_new((char*)"Error #2014: Feature is not available at this time.", 2014)); return false; }');
    for (const [flag, macro] of [['supportsDockIcon', 'ASC_HAS_DOCK'], ['supportsSystemTrayIcon', 'ASC_HAS_TRAY'], ['supportsMenu', 'ASC_HAS_APP_MENU'], ['supportsStartAtLogin', 'ASC_HAS_LOGIN_ITEM'], ['supportsDefaultApplication', 'ASC_HAS_DEFAULT_APP']] as const) {
      this.line(`bool NativeApplication_get_${flag}_static(void* _this) { (void)_this; return ${macro} ? true : false; }`);
    }
