    this.line('DisplayObject* DisplayObject_new(void) {');
    this.indent++;
    this.line('DisplayObject* o = (DisplayObject*)gc_alloc(GCT_CLASS, sizeof(DisplayObject));');
    this.line('o->vtable = &DisplayObject_vt;');
    this.line('DisplayObject_ctor(o);');
