    this.line('unsigned bits; memcpy(&bits, &v, 4); as_ba_put_u32(target, bits);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('return (double)want;');
    this.indent--;
    this.line('}');
