    this.line('double SoundChannel_get_position(void* _this) { SoundChannel* o = (SoundChannel*)_this; if (o->_ch_voice >= 0) o->_ch_pos = as_audio_voice_pos_ms(o->_ch_voice); return o->_ch_pos; }');
