    this.line('Socket* Socket_new(char* host, int port) { Socket* o = (Socket*)gc_alloc(GCT_CLASS, sizeof(Socket)); o->vtable = &Socket_vt; Socket_ctor(o, host, port); return o; }');
    this.line('// connect(): synchronous validation, asynchronous result. The port check comes');
    this.line('// first — a bad port is rejected even when the host is fine.');
    this.line('void Socket_connect(void* _this, char* host, int port) {');
    this.line('    Socket* o = (Socket*)_this;');
    this.line('    if (host == NULL) { as_throw(TypeError_new((char*)"Error #1009: Cannot access a property or method of a null object reference.", 1009)); return; }');
    this.line('    if (port < 0 || port > 65535) { as_throw(SecurityError_new((char*)"Error #2003: Invalid socket port number specified.", 2003)); return; }');
    this.line('    if (o->_sock == NULL) {');
    this.line('        o->_sock = (void*)as_sock_new(0);');
    this.line('        if (o->_sock == NULL) return;');
    this.line('    }');
    this.line('    as_sock* s = (as_sock*)o->_sock;');
    this.line('    as_sock_set_timeout(s, o->timeout);');
    this.line('    as_sock_set_obj(s, (void*)o);');
    this.line('    as_sock_connect(s, host, port);');
    this.line('    as_sock_set_no_delay(s, o->tcpNoDelay ? 1 : 0);');
    this.line('}');
    this.line('void Socket_close(void* _this) {');
    this.line('    Socket* o = (Socket*)_this;');
    this.line('    if (o->_sock == NULL) { Socket__invalid(); return; }');
    this.line('    as_sock_close((as_sock*)o->_sock);');
    this.line('    o->_sock = NULL;');
    this.line('}');
    this.line('void Socket_flush(void* _this) {');
    this.line('    Socket* o = (Socket*)_this;');
    this.line('    if (!Socket__live(o)) { Socket__invalid(); return; }');
    this.line('    as_sock_try_flush((as_sock*)o->_sock);');
    this.line('}');
    this.line('unsigned Socket_get_bytesAvailable(void* _this) {');
    this.line('    if (!Socket__live(_this)) { Socket__invalid(); return 0; }');
    this.line('    return (unsigned)Socket__avail(_this);');
    this.line('}');
    this.line('unsigned Socket_get_bytesPending(void* _this) {');
    this.line('    if (!Socket__live(_this)) { Socket__invalid(); return 0; }');
    this.line('    return (unsigned)as_sock_pending((as_sock*)((Socket*)_this)->_sock);');
    this.line('}');
    this.line('bool Socket_get_connected(void* _this) { return Socket__connected(_this) != 0; }');
    this.line('char* Socket_get_localAddress(void* _this) { as_sock* s = (as_sock*)((Socket*)_this)->_sock; return s == NULL ? NULL : (char*)as_sock_local_addr(s); }');
    this.line('int Socket_get_localPort(void* _this) { as_sock* s = (as_sock*)((Socket*)_this)->_sock; return s == NULL ? 0 : as_sock_local_port(s); }');
    this.line('char* Socket_get_remoteAddress(void* _this) { as_sock* s = (as_sock*)((Socket*)_this)->_sock; return s == NULL ? NULL : (char*)as_sock_remote_addr(s); }');
    this.line('int Socket_get_remotePort(void* _this) { as_sock* s = (as_sock*)((Socket*)_this)->_sock; return s == NULL ? 0 : as_sock_remote_port(s); }');
    this.line('// ---- IDataInput read side -------------------------------------------------');
    this.line('bool Socket_readBoolean(void* _this) { return Socket__uint(_this, 1, 0) != 0; }');
    this.line('int Socket_readByte(void* _this) { return (int)(signed char)Socket__uint(_this, 1, 0); }');
    this.line('unsigned Socket_readUnsignedByte(void* _this) { return (unsigned)Socket__uint(_this, 1, 0); }');
    this.line('int Socket_readShort(void* _this) { return (int)(short)Socket__uint(_this, 2, Socket__little(_this)); }');
    this.line('unsigned Socket_readUnsignedShort(void* _this) { return (unsigned)Socket__uint(_this, 2, Socket__little(_this)); }');
    this.line('int Socket_readInt(void* _this) { return (int)(int32_t)Socket__uint(_this, 4, Socket__little(_this)); }');
    this.line('unsigned Socket_readUnsignedInt(void* _this) { return (unsigned)Socket__uint(_this, 4, Socket__little(_this)); }');
    this.line('double Socket_readFloat(void* _this) {');
    this.line('    unsigned char buf[4]; float f = 0.0f;');
    this.line('    if (!Socket__need(_this, 4)) { Socket__eof(); return 0.0; }');
    this.line('    Socket__read(_this, buf, 4);');
    this.line('    if (Socket__little(_this)) { unsigned char r[4]; for (int i = 0; i < 4; i++) r[i] = buf[3 - i]; memcpy(&f, r, 4); }');
    this.line('    else memcpy(&f, buf, 4);');
    this.line('    return (double)f;');
    this.line('}');
    this.line('double Socket_readDouble(void* _this) {');
    this.line('    unsigned char buf[8]; double d = 0.0;');
    this.line('    if (!Socket__need(_this, 8)) { Socket__eof(); return 0.0; }');
    this.line('    Socket__read(_this, buf, 8);');
    this.line('    if (Socket__little(_this)) { unsigned char r[8]; for (int i = 0; i < 8; i++) r[i] = buf[7 - i]; memcpy(&d, r, 8); }');
    this.line('    else memcpy(&d, buf, 8);');
    this.line('    return d;');
    this.line('}');
    this.line('// A read of n bytes into a fresh GC string. Bytes are copied verbatim: this');
    this.line('// subset\'s String is a UTF-8 byte sequence (same rule as ByteArray.readUTFBytes).');
    this.line('static char* Socket__str(Socket* o, int n) {');
    this.line('    if (!Socket__live((void*)o)) { Socket__invalid(); return as_str_empty(); }');
    this.line('    if (n < 0) n = 0;');
    this.line('    if (Socket__avail(o) < n) { Socket__eof(); return as_str_empty(); }');
    this.line('    char* s = as_str_alloc((size_t)n + 1);');
    this.line('    if (n > 0) Socket__read((void*)o, s, n);');
    this.line('    s[n] = \'\\0\';');
    this.line('    return s;');
    this.line('}');
    this.line('char* Socket_readUTFBytes(void* _this, unsigned length) { return Socket__str((Socket*)_this, (int)length); }');
    this.line('// readUTF: an unsigned 16-bit byte count, then that many bytes.');
    this.line('char* Socket_readUTF(void* _this) {');
    this.line('    Socket* o = (Socket*)_this;');
    this.line('    unsigned n = (unsigned)Socket__uint(o, 2, 0);');
    this.line('    return Socket__str(o, (int)n);');
    this.line('}');
    this.line('// readMultiByte decodes with the named charset through the shared codec');
    this.line('// (as_multibyte_decode); \'unicode\' honours the socket endian property.');
    this.line('char* Socket_readMultiByte(void* _this, unsigned length, char* charSet) {');
    this.line('    Socket* o = (Socket*)_this;');
    this.line('    char* raw = Socket__str(o, (int)length);');
    this.line('    return as_multibyte_decode((const unsigned char*)raw, length, charSet);');
    this.line('}');
    this.line('void Socket_readBytes(void* _this, ByteArray* bytes, unsigned offset, unsigned length) {');
    this.line('    Socket* o = (Socket*)_this;');
    this.line('    if (!Socket__live(o)) { Socket__invalid(); return; }');
    this.line('    unsigned avail = (unsigned)Socket__avail(o);');
    this.line('    unsigned n = (length == 0 || length > avail) ? avail : length;');
    this.line('    if (offset + n > (unsigned)bytes->capacity) {');
    this.line('        int need = (int)(offset + n);');
    this.line('        void* nd = gc_alloc(GCT_BYTES, (size_t)(need > 0 ? need : 1));');
    this.line('        if (bytes->data != NULL && bytes->length > 0) memcpy(nd, bytes->data, (size_t)bytes->length);');
    this.line('        bytes->data = nd; bytes->capacity = need;');
    this.line('        gc_write_barrier((void*)nd);');
    this.line('    }');
    this.line('    if (n > 0) Socket__read(o, (unsigned char*)bytes->data + offset, (int)n);');
    this.line('    if ((int)(offset + n) > bytes->length) bytes->length = (int)(offset + n);');
    this.line('}');
    this.line('// ---- IDataOutput write side ----------------------------------------------');
    this.line('void Socket_writeBoolean(void* _this, bool value) { Socket__put(_this, value ? 1 : 0, 1, 0); }');
    this.line('void Socket_writeByte(void* _this, int value) { Socket__put(_this, (unsigned)(value & 0xff), 1, 0); }');
    this.line('void Socket_writeShort(void* _this, int value) { Socket__put(_this, (unsigned)(value & 0xffff), 2, Socket__little(_this)); }');
    this.line('void Socket_writeInt(void* _this, int value) { Socket__put(_this, (unsigned)value & 0xffffffffu, 4, Socket__little(_this)); }');
    this.line('void Socket_writeUnsignedInt(void* _this, unsigned value) { Socket__put(_this, (unsigned long long)value, 4, Socket__little(_this)); }');
    this.line('void Socket_writeFloat(void* _this, double value) {');
    this.line('    float f = (float)value; unsigned char buf[4];');
    this.line('    memcpy(buf, &f, 4);');
    this.line('    if (Socket__little(_this)) { unsigned char r[4]; for (int i = 0; i < 4; i++) r[i] = buf[3 - i]; Socket__write(_this, r, 4); }');
    this.line('    else Socket__write(_this, buf, 4);');
    this.line('}');
    this.line('void Socket_writeDouble(void* _this, double value) {');
    this.line('    unsigned char buf[8];');
    this.line('    memcpy(buf, &value, 8);');
    this.line('    if (Socket__little(_this)) { unsigned char r[8]; for (int i = 0; i < 8; i++) r[i] = buf[7 - i]; Socket__write(_this, r, 8); }');
    this.line('    else Socket__write(_this, buf, 8);');
    this.line('}');
    this.line('void Socket_writeUTFBytes(void* _this, char* value) {');
    this.line('    if (value == NULL) value = (char*)"";');
    this.line('    Socket__write(_this, value, (int)strlen(value));');
    this.line('}');
    this.line('// writeUTF prefixes the byte count. Like ByteArray.writeUTF in this subset, a');
    this.line('// string longer than 65535 bytes wraps the count rather than throwing the');
    this.line('// RangeError AIR documents (same documented leniency, see flash-net.md section 3.1).');
    this.line('void Socket_writeUTF(void* _this, char* value) {');
    this.line('    if (value == NULL) value = (char*)"";');
    this.line('    Socket__put(_this, (unsigned)strlen(value) & 0xffff, 2, 0);');
    this.line('    Socket__write(_this, value, (int)strlen(value));');
    this.line('}');
    this.line('void Socket_writeMultiByte(void* _this, char* value, char* charSet) { (void)charSet; Socket_writeUTFBytes(_this, value); }');
    this.line('void Socket_writeBytes(void* _this, ByteArray* bytes, unsigned offset, unsigned length) {');
    this.line('    if (!Socket__live(_this)) { Socket__invalid(); return; }');
    this.line('    if (bytes == NULL) { as_throw(TypeError_new((char*)"Error #1009: Cannot access a property or method of a null object reference.", 1009)); return; }');
    this.line('    unsigned total = (unsigned)bytes->length;');
    this.line('    if (offset > total) { as_throw(RangeError_new((char*)"Error #2006: The supplied index is out of bounds.", 2006)); return; }');
    this.line('    unsigned n = (length == 0 || offset + length > total) ? (total - offset) : length;');
    this.line('    if (n > 0) Socket__write(_this, (unsigned char*)bytes->data + offset, (int)n);');
    this.line('}');
    // writeObject is exact: AMF3-serialize into a buffer, then hand it to the same
    // write sink every write* method uses (the objectEncoding check inside the
    // codec is what makes AMF0 throw, as on ByteArray).
    this.line('void Socket_writeObject(void* _this, as_value object) {');
    this.line('    if (!Socket__live(_this)) { Socket__invalid(); return; }');
    this.line('    as_amf_err err; size_t len = 0;');
    this.line('    unsigned char* buf = as_amf_write_object(object, (int)((Socket*)_this)->objectEncoding, &len, &err);');
    this.line('    if (buf == NULL) { if (err.code != 0) as_amf_throw_err(&err); return; }');
    this.line('    if (len > 0) Socket__write(_this, buf, (int)len);');
    this.line('    free(buf);');
    this.line('}');
    // readObject is the one IDataInput member this subset cannot model, and the
    // refusal is explicit rather than a wrong answer: an AMF3 value may span
    // several packets, and Socket__read consumes bytes from the transport with no
    // push-back, so a partially-arrived value would silently swallow the bytes
    // that follow it. AIR buffers; we do not. Read the bytes with readBytes() and
    // parse them with ByteArray.readObject() instead (identical AMF3 codec).
    this.line('as_value Socket_readObject(void* _this) {');
    this.line('    (void)_this;');
    this.line('    as_throw(Error_new((char*)"Socket.readObject is not supported by this subset: the socket read side is not seekable, so an AMF3 value spanning packets cannot be parsed without consuming the bytes after it. Use Socket.readBytes() with ByteArray.readObject().", 0));');
    this.line('    return as_v_null();');
    this.line('}');
    this.line('');
    // ---- flash.net.ServerSocket (stage 89·54) ----
    //
    // bind() is the only place a listening transport is created, so it is also
    // where a previously bound one is released — the reference lets bind() move
    // the socket to a different port, and the example code closes the object
    // instead because a CLOSED ServerSocket cannot be reopened. That last rule is
    // enforced here with `_closed`: after close() a later bind() reports the same
    // IOError #2002 the reference's listen()-on-closed measurement produced.
    this.line('void ServerSocket_ctor(ServerSocket* o) {');
    this.line('    EventDispatcher_ctor((EventDispatcher*)o, NULL);');
    this.line('    o->_sock = NULL;');
    this.line('    o->_closed = 0;');
    this.line('}');
    this.line('ServerSocket* ServerSocket_new(void) { ServerSocket* o = (ServerSocket*)gc_alloc(GCT_CLASS, sizeof(ServerSocket)); o->vtable = &ServerSocket_vt; ServerSocket_ctor(o); return o; }');
    this.line('void ServerSocket_bind(void* _this, int localPort, char* localAddress) {');
    this.line('    ServerSocket* o = (ServerSocket*)_this;');
    this.line('    if (o->_closed) { Socket__invalid(); return; }');
    this.line('    if (o->_sock != NULL) { as_sock_close((as_sock*)o->_sock); o->_sock = NULL; }');
    this.line('    o->_sock = (void*)as_sock_new(1);');
    this.line('    if (o->_sock == NULL) return;');
    this.line('    as_sock* s = (as_sock*)o->_sock;');
    this.line('    as_sock_set_obj(s, (void*)o);');
    this.line('    // AIR\'s port 0 is "next available"; a bind that fails leaves `bound` false,');
    this.line('    // which is the documented way to detect it.');
    this.line('    as_sock_bind(s, localAddress, localPort);');
    this.line('}');
    this.line('void ServerSocket_listen(void* _this, int backlog) {');
    this.line('    ServerSocket* o = (ServerSocket*)_this;');
    this.line('    as_sock* s = (as_sock*)o->_sock;');
    this.line('    if (s == NULL || as_sock_is_dead(s) || !as_sock_is_bound(s)) { Socket__invalid(); return; }');
    this.line('    if (!as_sock_listen(s, backlog)) Socket__invalid();');
    this.line('}');
    this.line('void ServerSocket_close(void* _this) {');
    this.line('    ServerSocket* o = (ServerSocket*)_this;');
    this.line('    if (o->_sock == NULL) { Socket__invalid(); return; }');
    this.line('    as_sock_close((as_sock*)o->_sock);');
    this.line('    o->_sock = NULL;');
    this.line('    o->_closed = 1;');
    this.line('}');
    this.line('bool ServerSocket_get_bound(void* _this) { as_sock* s = (as_sock*)((ServerSocket*)_this)->_sock; return s != NULL && !as_sock_is_dead(s) && as_sock_local_port(s) > 0; }');
    this.line('bool ServerSocket_get_listening(void* _this) { as_sock* s = (as_sock*)((ServerSocket*)_this)->_sock; return s != NULL && !as_sock_is_dead(s) && as_sock_is_listening(s); }');
    this.line('char* ServerSocket_get_localAddress(void* _this) { as_sock* s = (as_sock*)((ServerSocket*)_this)->_sock; if (s == NULL || as_sock_local_port(s) <= 0) return NULL; return (char*)as_sock_local_addr(s); }');
    this.line('int ServerSocket_get_localPort(void* _this) { as_sock* s = (as_sock*)((ServerSocket*)_this)->_sock; return s == NULL ? 0 : as_sock_local_port(s); }');
    this.line('bool ServerSocket_get_isSupported_static(void* _this) { (void)_this; return true; }');
    this.line('');
    // ---- flash.net.XMLSocket (stage 89·54) ----
    //
    // XMLSocket is the NUL-terminated-message protocol over the same transport.
    // adl measured its framing exactly: send() appends the terminator itself
    // (a 5-byte string arrives as 6 bytes) and sends IMMEDIATELY, with no
    // flush(); an inbound message is delivered as DataEvent.DATA with a String
    // payload, one event per terminator; and a message split across frames is
    // assembled rather than reported early.
    this.line('void XMLSocket_ctor(XMLSocket* o, char* host, int port) {');
    this.line('    EventDispatcher_ctor((EventDispatcher*)o, NULL);');
    this.line('    o->timeout = 20000;');
    this.line('    o->_sock = NULL;');
    this.line('    if (host != NULL) XMLSocket_connect((void*)o, host, port);');
    this.line('}');
    this.line('XMLSocket* XMLSocket_new(char* host, int port) { XMLSocket* o = (XMLSocket*)gc_alloc(GCT_CLASS, sizeof(XMLSocket)); o->vtable = &XMLSocket_vt; XMLSocket_ctor(o, host, port); return o; }');
    this.line('void XMLSocket_connect(void* _this, char* host, int port) {');
    this.line('    XMLSocket* o = (XMLSocket*)_this;');
    this.line('    if (host == NULL) { as_throw(TypeError_new((char*)"Error #1009: Cannot access a property or method of a null object reference.", 1009)); return; }');
    this.line('    if (port < 0 || port > 65535) { as_throw(SecurityError_new((char*)"Error #2003: Invalid socket port number specified.", 2003)); return; }');
    this.line('    if (o->_sock == NULL) {');
    this.line('        o->_sock = (void*)as_sock_new(0);');
    this.line('        if (o->_sock == NULL) return;');
    this.line('    }');
    this.line('    as_sock* s = (as_sock*)o->_sock;');
    this.line('    as_sock_set_timeout(s, o->timeout);');
    this.line('    as_sock_set_obj(s, (void*)o);');
    this.line('    as_sock_connect(s, host, port);');
    this.line('}');
    this.line('void XMLSocket_close(void* _this) {');
    this.line('    XMLSocket* o = (XMLSocket*)_this;');
    this.line('    if (o->_sock == NULL) { Socket__invalid(); return; }');
    this.line('    as_sock_close((as_sock*)o->_sock);');
    this.line('    o->_sock = NULL;');
    this.line('}');
    this.line('bool XMLSocket_get_connected(void* _this) {');
    this.line('    as_sock* s = (as_sock*)((XMLSocket*)_this)->_sock;');
    this.line('    return s != NULL && !as_sock_is_dead(s) && as_sock_state_of(s) == AS_SOCK_CONNECTED;');
    this.line('}');
    // send(): the terminator is part of the wire format, so this is where it is
    // appended. The reference types the parameter Object and AIR accepts an XML
    // value or a String (stringifying anything else, measured: 42 becomes "42"),
    // so the slot is dynamic and the coercion is the same one an implicit
    // String conversion uses. A null argument raises the #1009 a null connect()
    // host raises (measured) rather than sending the literal "null".
    this.line('void XMLSocket_send(void* _this, as_value object) {');
    this.line('    XMLSocket* o = (XMLSocket*)_this;');
    this.line('    if (!XMLSocket_get_connected(o)) { Socket__invalid(); return; }');
    this.line('    if (object.tag == 0 || object.tag == 5) { as_throw(TypeError_new((char*)"Error #1009: Cannot access a property or method of a null object reference.", 1009)); return; }');
    this.line('    char* text = as_coerce_str(object);');
    this.line('    if (text == NULL) { as_throw(TypeError_new((char*)"Error #1009: Cannot access a property or method of a null object reference.", 1009)); return; }');
    this.line('    as_sock* s = (as_sock*)o->_sock;');
    this.line('    int n = (int)strlen(text);');
    this.line('    if (n > 0) as_sock_write(s, text, n);');
    this.line('    as_sock_write(s, "", 1);');
    this.line('    as_sock_try_flush(s);');
    this.line('}');
    // Hand over every complete NUL-terminated message as a DataEvent. The scan
    // consumes nothing until a terminator is found, so a message that arrives
    // split across frames stays buffered until it is whole.
    this.line('static int XMLSocket__deliver(XMLSocket* o) {');
    this.line('    int sent = 0;');
    this.line('    for (;;) {');
    this.line('        as_sock* s = (as_sock*)o->_sock;');
    this.line('        if (s == NULL) break;');
    this.line('        int at = as_sock_index_of(s, 0);');
    this.line('        if (at < 0) break;');
    this.line('        char* msg = as_str_alloc((size_t)at + 1);');
    this.line('        if (at > 0) as_sock_read(s, msg, at);');
    this.line('        msg[at] = \'\\0\';');
    this.line('        unsigned char nul = 0;');
    this.line('        as_sock_read(s, &nul, 1);');
    this.line('        EventDispatcher_dispatchEvent((void*)o, (Event*)DataEvent_new((char*)"data", false, false, msg));');
    this.line('        sent++;');
    this.line('        if (as_sock_is_dead(s)) break;');
    this.line('    }');
    this.line('    return sent;');
    this.line('}');
    this.line('');
    // ---- flash.net.SecureSocket (stage 89·54) ----
    //
    // TLS is NOT implemented, and the class says so instead of silently handing
    // the app a plaintext connection: isSupported is false and connect()
    // dispatches the socket ioError. SecureSocket.isSupported is the documented
    // way to feature-detect TLS, so an app that checks it takes its own fallback,
    // and an app that does not still fails loudly. What is missing is the TLS
    // state machine over the non-blocking transport plus AIR's
    // serverCertificateValidate handshake (the app validates untrusted certs);
    // it is recorded in TODO.md's leftover table, not papered over here.
    this.line('static char* Socket__ioerror_text(const char* url);');
    this.line('static IOErrorEvent* Socket__ioerror_event(const char* url);');
    this.line('void SecureSocket_ctor(SecureSocket* o) {');
    this.line('    Socket_ctor((Socket*)o, NULL, 0);');
    this.line('}');
    this.line('SecureSocket* SecureSocket_new(void) { SecureSocket* o = (SecureSocket*)gc_alloc(GCT_CLASS, sizeof(SecureSocket)); o->vtable = &SecureSocket_vt; SecureSocket_ctor(o); return o; }');
    this.line('void SecureSocket_connect(void* _this, char* host, int port) {');
    this.line('    SecureSocket* o = (SecureSocket*)_this;');
    this.line('    if (host == NULL) { as_throw(TypeError_new((char*)"Error #1009: Cannot access a property or method of a null object reference.", 1009)); return; }');
    this.line('    if (port < 0 || port > 65535) { as_throw(SecurityError_new((char*)"Error #2003: Invalid socket port number specified.", 2003)); return; }');
    this.line('    EventDispatcher_dispatchEvent((void*)o, (Event*)Socket__ioerror_event(host));');
    this.line('}');
    this.line('bool SecureSocket_get_isSupported_static(void* _this) { (void)_this; return false; }');
    this.line('char* SecureSocket_get_serverCertificateStatus(void* _this) { (void)_this; return (char*)"unknown"; }');
    this.line('void SecureSocket_addBinaryChainBuildingCertificate(void* _this, ByteArray* certificate, bool trusted) { (void)_this; (void)certificate; (void)trusted; }');
    this.line('');
    // ---- the AS3 side of the socket seam ----
    //
    // as_sock_dispatch() is the second half of the frame-boundary pump (the first
    // half, as_sock_pump, lives in RUNTIME_PREAMBLE and knows nothing about AS3).
    // It walks the registry, turning raised flags into events, and is called from
    // as_async_tick — so socket events arrive on the same frame boundary as every
    // other asynchronous event in this runtime. It is also what keeps AIR's
    // "everything is dispatched between frames" model intact: nothing here runs
    // on a worker thread.
    //
    // Three rules keep a listener from breaking the walk:
    //   * a socket the pump marked dead is skipped, so close() from inside an
    //     earlier dispatch cannot deliver an event for a socket that is gone;
    //   * a flag is cleared BEFORE its event is dispatched, so a re-entrant tick
    //     (a listener calling tickTimers) cannot replay it;
    //   * nothing is freed here. close() only marks dead; as_sock_reap() at the
    //     tail — which refuses to run while as_sock_dispatching is set — frees.
    //
    // The order is fixed: CONNECT, then ACCEPT, then DATA, then OUTPUT, then
    // ERROR, then CLOSE. DATA before CLOSE is required — the last chunk of a
    // connection must be readable before the close event retires the socket.
    this.line('// flash.events.ServerSocketConnectEvent / OutputProgressEvent: the two event');
    this.line('// classes the socket layer introduces. Both extend Event (hand-written like the');
    this.line('// other flash.events subclasses in this file, stage 59).');
    this.line('void ServerSocketConnectEvent_ctor(ServerSocketConnectEvent* o, char* type, bool bubbles, bool cancelable, Socket* socket) {');
    this.line('    Event_ctor((Event*)o, type, bubbles, cancelable);');
    this.line('    o->socket = socket;');
    this.line('    gc_write_barrier((void*)socket);');
    this.line('}');
    this.line('ServerSocketConnectEvent* ServerSocketConnectEvent_new(char* type, bool bubbles, bool cancelable, Socket* socket) {');
    this.line('    ServerSocketConnectEvent* o = (ServerSocketConnectEvent*)gc_alloc(GCT_CLASS, sizeof(ServerSocketConnectEvent));');
    this.line('    o->vtable = &ServerSocketConnectEvent_vt;');
    this.line('    ServerSocketConnectEvent_ctor(o, type, bubbles, cancelable, socket);');
    this.line('    return o;');
    this.line('}');
    this.line('void OutputProgressEvent_ctor(OutputProgressEvent* o, char* type, bool bubbles, bool cancelable, double bytesPending, double bytesTotal) {');
    this.line('    Event_ctor((Event*)o, type, bubbles, cancelable);');
    this.line('    o->bytesPending = bytesPending;');
    this.line('    o->bytesTotal = bytesTotal;');
    this.line('}');
    this.line('OutputProgressEvent* OutputProgressEvent_new(char* type, bool bubbles, bool cancelable, double bytesPending, double bytesTotal) {');
    this.line('    OutputProgressEvent* o = (OutputProgressEvent*)gc_alloc(GCT_CLASS, sizeof(OutputProgressEvent));');
    this.line('    o->vtable = &OutputProgressEvent_vt;');
    this.line('    OutputProgressEvent_ctor(o, type, bubbles, cancelable, bytesPending, bytesTotal);');
    this.line('    return o;');
    this.line('}');
    this.line('');
    // AIR pairs the message with errorID 2031 (measured; the text alone is not
    // enough — code reads the number). `id` is fixed: every transport failure a
    // connect attempt produces reports 2031, and no other socket failure has a
    // measured id yet (see the leftover table in TODO.md).
    this.line('static IOErrorEvent* Socket__ioerror_event(const char* url) {');
    this.line('    IOErrorEvent* e = IOErrorEvent_new((char*)"ioError", false, false, Socket__ioerror_text(url));');
    this.line('    e->errorID = 2031;');
    this.line('    return e;');
    this.line('}');
    this.line('static char* Socket__ioerror_text(const char* url) {');
    this.line('    size_t n = strlen(url == NULL ? "" : url) + 48;');
    this.line('    char* t = as_str_alloc(n);');
    this.line('    snprintf(t, n, "Error #2031: Socket Error. URL: %s", url == NULL ? "" : url);');
    this.line('    return t;');
    this.line('}');
    this.line('int as_sock_dispatch(void) {');
    this.line('    int total = 0;');
    this.line('    as_sock_dispatching = 1;');
    this.line('    int n = as_sock_count_all();');
    this.line('    for (int i = 0; i < n; i++) {');
    this.line('        as_sock* s = as_sock_at(i);');
    this.line('        if (as_sock_is_dead(s)) continue;');
    this.line('        int ev = as_sock_events_of(s);');
    this.line('        void* obj = as_sock_obj_of(s);');
    this.line('        if (obj == NULL) continue;');
    this.line('        if (ev & AS_SOCK_EV_CONNECT) {');
    this.line('            as_sock_clear_events(s, AS_SOCK_EV_CONNECT);');
    this.line('            EventDispatcher_dispatchEvent(obj, (Event*)Event_new((char*)"connect", false, false));');
    this.line('            total++;');
    this.line('            if (as_sock_is_dead(s)) continue;');
    this.line('            ev = as_sock_events_of(s);');
    this.line('        }');
    this.line('        if (ev & AS_SOCK_EV_ACCEPT) {');
    this.line('            as_sock_clear_events(s, AS_SOCK_EV_ACCEPT);');
    this.line('            as_sock* c = as_sock_take_accepted(s);');
    this.line('            if (c != NULL) {');
    this.line('                Socket* peer = Socket_new(NULL, 0);');
    this.line('                peer->_sock = (void*)c;');
    this.line('                as_sock_set_obj(c, (void*)peer);');
    this.line('                // ONE event, a ServerSocketConnectEvent: its type is');
    this.line('                // ServerSocketConnectEvent.CONNECT === Event.CONNECT === "connect"');
    this.line('                // and it extends Event, so a single dispatch reaches listeners');
    this.line('                // registered for either constant (measured on adl).');
    this.line('                EventDispatcher_dispatchEvent(obj, (Event*)ServerSocketConnectEvent_new((char*)"connect", false, false, peer));');
    this.line('                total++;');
    this.line('            }');
    this.line('            if (as_sock_is_dead(s)) continue;');
    this.line('            ev = as_sock_events_of(s);');
    this.line('        }');
    this.line('        if (ev & AS_SOCK_EV_DATA) {');
    this.line('            as_sock_clear_events(s, AS_SOCK_EV_DATA);');
    this.line('            if (as_is(obj, &XMLSocket_vt)) {');
    this.line('                total += XMLSocket__deliver((XMLSocket*)obj);');
    this.line('            } else {');
    this.line('                // bytesTotal stays 0: a socket has no declared length (measured).');
    this.line('                EventDispatcher_dispatchEvent(obj, (Event*)ProgressEvent_new((char*)"socketData", false, false, (unsigned)as_sock_avail(s), 0));');
    this.line('                total++;');
    this.line('            }');
    this.line('            if (as_sock_is_dead(s)) continue;');
    this.line('            ev = as_sock_events_of(s);');
    this.line('        }');
    this.line('        if (ev & AS_SOCK_EV_OUTPUT) {');
    this.line('            as_sock_clear_events(s, AS_SOCK_EV_OUTPUT);');
    this.line('            if (!as_is(obj, &XMLSocket_vt)) {');
    this.line('                EventDispatcher_dispatchEvent(obj, (Event*)OutputProgressEvent_new((char*)"outputProgress", false, false, (double)as_sock_pending(s), 0.0));');
    this.line('                total++;');
    this.line('            }');
    this.line('            if (as_sock_is_dead(s)) continue;');
    this.line('            ev = as_sock_events_of(s);');
    this.line('        }');
    this.line('        if (ev & AS_SOCK_EV_ERROR) {');
    this.line('            as_sock_clear_events(s, AS_SOCK_EV_ERROR);');
    this.line('            EventDispatcher_dispatchEvent(obj, (Event*)Socket__ioerror_event(as_sock_url(s)));');
    this.line('            total++;');
    this.line('            if (as_sock_is_dead(s)) continue;');
    this.line('            ev = as_sock_events_of(s);');
    this.line('        }');
    this.line('        if (ev & AS_SOCK_EV_CLOSE) {');
    this.line('            as_sock_clear_events(s, AS_SOCK_EV_CLOSE);');
    this.line('            EventDispatcher_dispatchEvent(obj, (Event*)Event_new((char*)"close", false, false));');
    this.line('            total++;');
    this.line('        }');
    this.line('    }');
    this.line('    as_sock_dispatching = 0;');
    this.line('    as_sock_reap();');
    this.line('    return total;');
    this.line('}');
    this.line('');

    // URLVariables: dynamic class (AS3 `dynamic class`). Arbitrary string-keyed
    // properties live in the `_dyn` slot table (see the dynamic-class mechanism);
    // toString() serializes them as a URL-encoded query string (key=value&...),
    // insertion-ordered for deterministic output (AIR walks its hash order -- a
    // documented ordering divergence, see docs/zh-cn/flash-net.md §3.1).
    this.line('void URLVariables_ctor(URLVariables* o, char* source) {');
    this.indent++;
    this.line('Object_ctor((Object*)o);');
    this.line('o->_dyn = as_object_new();');
    this.line('gc_write_barrier((void*)o->_dyn);');
    // AIR: the constructor decodes any non-null argument, so it is the same
    // operation as the public decode() and is delegated to it.
    this.line('URLVariables_decode((void*)o, source);');
    this.indent--;
    this.line('}');
    this.line('URLVariables* URLVariables_new(char* source) { URLVariables* o = (URLVariables*)gc_alloc(GCT_CLASS, sizeof(URLVariables)); o->vtable = &URLVariables_vt; URLVariables_ctor(o, source); return o; }');
    // URLVariables.decode(source): split "a=1&b=2" into dynamic properties. The
    // source is copied first because the scan writes NULs into the buffer as it
    // walks and the argument string may be caller-owned. Keys are NOT URL-decoded,
    // values are — that asymmetry is AIR's (the constructor always behaved so).
    // AIR throws Error for a pair that is not URL-encoded; this subset decodes
    // leniently instead (docs/zh-cn/flash-net.md §3.1).
    this.line('void URLVariables_decode(void* _this, char* source) {');
    this.indent++;
    this.line('URLVariables* o = (URLVariables*)_this;');
    this.line('if (source == NULL || *source == \'\\0\') return;');
    this.line('char* s = as_str_alloc(strlen(source) + 1);');
    this.line('strcpy(s, source);');
    this.line('char* p = s;');
    this.line('while (*p != \'\\0\') {');
    this.indent++;
    this.line('char* eq = strchr(p, \'=\');');
    this.line('char* amp = strchr(p, \'&\');');
    this.line('if (eq == NULL || (amp != NULL && amp < eq)) break;');
    this.line('*eq = \'\\0\';');
    this.line('char* val = eq + 1;');
    this.line('if (amp != NULL) { *amp = \'\\0\'; amp++; }');
    // Both halves of a pair are percent-decoded, not just the value: measured on
    // adl 51.4.1 (temp/uvarair), `new URLVariables("a%20b=c%20d")` answers the key
    // "a b" and `toString()` gives back "a%20b=c%20d" (the round trip closes only
    // if the key was decoded in the first place), and "plus=a+b" decodes to "a b"
    // for the value -- so '+' is a space in either half.
    this.line('as_object_set(o->_dyn, as_url_decode(p), as_v_str(as_url_decode(val)));');
    this.line('if (amp == NULL) break;');
    this.line('p = amp;');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('char* URLVariables_toString(void* _this) {');
    this.indent++;
    this.line('URLVariables* o = (URLVariables*)_this;');
    this.line('as_object* d = o->_dyn;');
    this.line('if (d == NULL || d->length == 0) return (char*)"";');
    // Both the key AND the value are percent-encoded (measured on adl 51.4.1,
    // temp/uvarair): every non-alphanumeric character, in either half, becomes
    // %XX. The buffer is therefore sized from the ENCODED lengths -- sizing it
    // from the raw ones (the previous form: strlen of the raw value) under-states
    // the write by up to 3x and overflows the GC string, which is what corrupted
    // the heap on TalkMED (阶段一百五十三).
    this.line('size_t total = 0;');
    this.line('for (int i = 0; i < d->length; i++) total += as_url_encoded_len(d->keys[i]) + as_url_encoded_len(as_v_str_val(d->vals[i])) + 2;');
    this.line('char* out = as_str_alloc(total + 1);');
    this.line('char* p = out;');
    this.line('for (int i = 0; i < d->length; i++) {');
    this.indent++;
    this.line('p += as_url_encode_into(p, d->keys[i]);');
    this.line('*p++ = \'=\';');
    this.line('p += as_url_encode_into(p, as_v_str_val(d->vals[i]));');
    this.line('if (i < d->length - 1) *p++ = \'&\';');;
    this.indent--;
    this.line('}');
    this.line('*p = \'\\0\';');
    this.line('return out;');
    this.indent--;
    this.line('}');
    this.line('');
    // Keyboard / Mouse: static-only classes (never instantiated), but they still
    // need concrete ctor/new so any reference links cleanly (like the stage-41
    // constant classes). Mouse.hide/show toggle a file-scope visibility flag.
    this.line('void Keyboard_ctor(Keyboard* o) { Object_ctor((Object*)o); }');
    this.line('Keyboard* Keyboard_new(void) { Keyboard* o = (Keyboard*)gc_alloc(GCT_CLASS, sizeof(Keyboard)); o->vtable = &Keyboard_vt; Keyboard_ctor(o); return o; }');
    // Keyboard.isAccessible(): a single-domain native build has no cross-domain
    // keystroke restriction, so the last key press is always readable.
    this.line('bool Keyboard_isAccessible_static(void) { return true; }');
    this.line('void Mouse_ctor(Mouse* o) { Object_ctor((Object*)o); }');
    this.line('Mouse* Mouse_new(void) { Mouse* o = (Mouse*)gc_alloc(GCT_CLASS, sizeof(Mouse)); o->vtable = &Mouse_vt; Mouse_ctor(o); return o; }');
    this.line('static bool as_mouse_visible = true;');
    this.line('void Mouse_hide_static(void) { as_mouse_visible = false; }');
    this.line('void Mouse_show_static(void) { as_mouse_visible = true; }');
    this.line('');
    // Forward declaration: FileStream_readBytes/writeBytes (below) call as_ba_grow,
    // which is defined in the ByteArray section further down. Since it is static,
    // it needs a prototype before the first call site.
    this.line('static void as_ba_grow(ByteArray* o, int extra);');
    // ---- flash.filesystem (stage 64): File / FileStream / FileMode ----
    // POSIX filesystem probes. stat() works for both files and directories and is
    // available on native POSIX and WASI alike.
    this.line('static bool as_path_exists(const char* p) { struct stat st; return p != NULL && stat(p, &st) == 0; }');
    this.line('static bool as_path_is_dir(const char* p) { struct stat st; return p != NULL && stat(p, &st) == 0 && S_ISDIR(st.st_mode); }');
    // as_path_is_symlink: the ONLY probe that must not follow the link, hence
    // lstat() rather than stat(). Windows has no lstat that reports reparse points
    // reliably, so it asks the file attributes directly -- AIR also answers true for
    // an NTFS junction, which is exactly what FILE_ATTRIBUTE_REPARSE_POINT covers.
    this.line('static bool as_path_is_symlink(const char* p) {');
    this.indent++;
    this.line('if (p == NULL) return false;');
    this.line('#ifdef _WIN32');
    this.indent++;
    this.line('DWORD a = GetFileAttributesA(p);');
    this.line('return a != INVALID_FILE_ATTRIBUTES && (a & FILE_ATTRIBUTE_REPARSE_POINT) != 0;');
    this.indent--;
    this.line('#else');
    this.indent++;
    this.line('struct stat st;');
    this.line('return lstat(p, &st) == 0 && S_ISLNK(st.st_mode);');
    this.indent--;
    this.line('#endif');
    this.indent--;
    this.line('}');
    this.line('static char* as_path_join(const char* a, const char* b) {');
    this.indent++;
    this.line('if (a == NULL || *a == \'\\0\') return (char*)(b ? b : "");');
    this.line('if (b == NULL || *b == \'\\0\') return (char*)a;');
    this.line('char* tmp = as_str_concat(a, "/");');
    this.line('return as_str_concat(tmp, b);');
    this.indent--;
    this.line('}');
    // AIR File static directory shortcuts, resolved from the process environment.
    // userDirectory/desktopDirectory/documentsDirectory read $HOME and append the
    // standard sub-path; applicationDirectory is described at as_app_dir below.
    this.line('static char* as_home_dir(void) {');
    this.indent++;
    this.line('#ifdef _WIN32');
    this.line('char* h = getenv("USERPROFILE");');
    this.line('return (h == NULL || *h == \'\\0\') ? (char*)"." : h;');
    this.line('#else');
    this.line('char* h = getenv("HOME");');
    this.line('return (h == NULL || *h == \'\\0\') ? (char*)"." : h;');
    this.line('#endif');
    this.indent--;
    this.line('}');
    // AIR: applicationDirectory is the directory the application was INSTALLED
    // into. A native build has no installer to ask, so it is derived from the
    // running executable's own path -- the same anchor fre.ts's as_ext_dir uses
    // for `extensions/`, so both answer to one notion of "the app directory".
    // Deliberately NOT the working directory: AIR resolves an app's `assets/...`
    // against the app directory however the app was started (Explorer, a shortcut,
    // or a shell parked in some unrelated folder), and an app that reads
    // `File.applicationDirectory.nativePath + "/assets/<tool>.exe"` -- the real
    // which is what a real AIR app does -- would otherwise find nothing whenever the CWD is
    // not the app directory. WASI and Emscripten have no executable path at all,
    // so they keep "."; the browser build instead packs the app root into the FS
    // image at that path (see preloadPaths in build.ts).
    // Known gap, reported rather than guessed at (AGENTS 1.5): a macOS .app
    // bundle's executable lives in Contents/MacOS while AIR's applicationDirectory
    // is Contents/Resources, and --package xcode-project stages no app data into
    // the bundle yet -- so a bundle build gets Contents/MacOS (see TODO.md).
    this.line('static char as_app_dir_buf[4096];');
    this.line('static int  as_app_dir_ready = 0;');
    this.line('static char* as_app_dir(void) {');
    this.indent++;
    this.line('if (!as_app_dir_ready) {');
    this.indent++;
    this.line('as_app_dir_buf[0] = \'\\0\';');
    this.line('#ifdef _WIN32');
    this.line('DWORD n = GetModuleFileNameA(NULL, as_app_dir_buf, (DWORD)sizeof(as_app_dir_buf));');
    this.line('if (n == 0 || n >= (DWORD)sizeof(as_app_dir_buf)) as_app_dir_buf[0] = \'\\0\';');
    this.line('#elif defined(__APPLE__)');
    this.line('uint32_t sz = (uint32_t)sizeof(as_app_dir_buf);');
    this.line('if (_NSGetExecutablePath(as_app_dir_buf, &sz) != 0) as_app_dir_buf[0] = \'\\0\';');
    this.line('#elif !defined(__wasi__) && !defined(__EMSCRIPTEN__)');
    this.line('ssize_t n = readlink("/proc/self/exe", as_app_dir_buf, sizeof(as_app_dir_buf) - 1);');
    this.line('if (n <= 0) as_app_dir_buf[0] = \'\\0\'; else as_app_dir_buf[n] = \'\\0\';');
    this.line('#endif');
    this.line('// Drop the executable\'s own file name -- and the separator with it, so a');
    this.line('// caller can spell app_dir + "/assets/..." instead of having to decide');
    this.line('// whether the app dir already ends in one.');
    this.line('if (as_app_dir_buf[0] != \'\\0\') {');
    this.indent++;
    this.line('int last = -1, i;');
    this.line('for (i = 0; as_app_dir_buf[i] != \'\\0\'; i++) {');
    this.indent++;
    this.line('if (as_app_dir_buf[i] == \'\\\\\' || as_app_dir_buf[i] == \'/\') last = i;');
    this.indent--;
    this.line('}');
    this.line('if (last > 0) as_app_dir_buf[last] = \'\\0\';');
    this.indent--;
    this.line('}');
    this.line('// No executable path (a platform without one, or a probe that failed):');
    this.line('// "." is what this function returned unconditionally before, so a program');
    this.line('// that relied on CWD resolution keeps working.');
    this.line('if (as_app_dir_buf[0] == \'\\0\') { as_app_dir_buf[0] = \'.\'; as_app_dir_buf[1] = \'\\0\'; }');
    this.indent--;
    this.line('}');
    this.line('return as_app_dir_buf;');
    this.indent--;
    this.line('}');
    this.line('static char* as_user_dir(void) { return as_home_dir(); }');
    this.line('static char* as_desktop_dir(void) { return as_path_join(as_home_dir(), "Desktop"); }');
    this.line('static char* as_documents_dir(void) { return as_path_join(as_home_dir(), "Documents"); }');
    // AIR File.separator / File.lineEnding: the host OS's path component separator
    // and line-ending sequence. Their VALUE is a property of the host, so the build
    // target answers them: Windows is the only platform AIR gives a backslash and
    // CRLF ("the carriage return character ... followed by the line-feed character"
    // -- File.lineEnding, airsdk.dev), while macOS, Linux, WASI and the browser build
    // all get '/' and LF. The browser has no AIR counterpart at all; POSIX is the
    // honest answer there rather than a silent Windows-ism. Note these are compared
    // as ordinary AS3 strings on the C side, so the backslash needs no escaping at
    // the call site -- that is what returning a literal (instead of boxing) buys.
    this.line('static char* as_file_separator(void) {');
    this.indent++;
    this.line('#ifdef _WIN32');
    this.line('return (char*)"\\\\";');
    this.line('#else');
    this.line('return (char*)"/";');
    this.line('#endif');
    this.indent--;
    this.line('}');
    this.line('static char* as_file_line_ending(void) {');
    this.indent++;
    this.line('#ifdef _WIN32');
    this.line('return (char*)"\\r\\n";');
    this.line('#else');
    this.line('return (char*)"\\n";');
    this.line('#endif');
    this.indent--;
    this.line('}');
    this.line('static int as_mkdir_one(const char* p) {');
    this.indent++;
    this.line('#ifdef _WIN32');
    this.line('// MSVC names mkdir _mkdir and drops the mode argument, and _mkdir lives in');
    this.line('// <direct.h> which this preamble does not include. CreateDirectoryA is the');
    this.line('// kernel32 single-level directory creator and needs no extra header.');
    this.line('return CreateDirectoryA(p, NULL) ? 0 : -1;');
    this.line('#else');
    this.line('return mkdir(p, 0755);');
    this.line('#endif');
    this.indent--;
    this.line('}');
    // POSIX remove() deletes an empty directory (via rmdir), but MSVC's remove()
    // is _unlink-only and cannot delete a directory. deleteDirectory therefore
    // needs its own helper: RemoveDirectoryA on Windows, remove() elsewhere.
    // remove() rather than rmdir() because rmdir is declared in <unistd.h>, which
    // WASI does not get (the preamble skips it there -- no fork/exec to hand a URL
    // to); wasi-libc declares remove() in <stdio.h> and routes an empty directory
    // to rmdir, so one call covers POSIX and WASI alike. Without this, EVERY wasm
    // build failed with "call to undeclared function 'rmdir'" (ISO C99 forbids the
    // implicit declaration the older clang accepted).
    this.line('static int as_rmdir_one(const char* p) {');
    this.indent++;
    this.line('#ifdef _WIN32');
    this.line('// kernel32 single-level empty-directory remover; mirrors as_mkdir_one.');
    this.line('return RemoveDirectoryA(p) ? 0 : -1;');
    this.line('#else');
    this.line('return remove(p);');
    this.line('#endif');
    this.indent--;
    this.line('}');
    this.line('static void as_mkdirs(const char* p) {');
    this.indent++;
    this.line('if (p == NULL || *p == \'\\0\') return;');
    this.line('char buf[1024];');
    this.line('size_t len = strlen(p);');
    this.line('if (len + 1 > sizeof(buf)) return;');
    this.line('memcpy(buf, p, len + 1);');
    this.line('// Split on both path separators; buf[0] is skipped so an absolute path\'s');
    this.line('// root is not turned into an empty component.');
    this.line('for (char* s = buf + 1; *s != \'\\0\'; s++) {');
    this.indent++;
    this.line('char c = *s;');
    this.line('if (c == \'/\' || c == \'\\\\\') { *s = \'\\0\'; as_mkdir_one(buf); *s = c; }');
    this.indent--;
    this.line('}');
    this.line('as_mkdir_one(buf);');
    this.indent--;
    this.line('}');
    this.line('');
    // Writable per-app storage (AIR applicationStorageDirectory). A bundled .app is
    // launched with a non-writable CWD (Xcode runs it with CWD="/"), so "." is not
    // a safe write target; resolve a stable directory and create it. AIR scopes
    // applicationStorageDirectory by the descriptor's <id>, so the app id has to
    // reach the generated C: without it every AOT app shared one store (D11).
    //
    // The per-OS root is adl's own, measured byte-for-byte against AIR SDK 51.4.1:
    //   macOS    ~/Library/Application Support/<id>/Local Store  -- the AIR 3.3+
    //            path (a sandboxed build would nest it under
    //            ~/Library/Containers/<bundle-id>/Data instead).
    //   Windows  %APPDATA%\<id>\Local Store                      -- i.e. Roaming.
    //   other    ~/.as3aot/<id> -- no AIR value to copy for a POSIX host, where a
    //            dot-directory under $HOME is the convention.
    // On Windows %APPDATA% is what the shell's CSIDL_APPDATA known folder resolves
    // to, and is the same env-var route as_home_dir already takes for USERPROFILE;
    // the fallback is that folder's documented default, so a host which does not
    // export APPDATA still lands in the same tree.
    this.line('#ifndef ASC_APP_ID');
    this.line('#define ASC_APP_ID "as3aot"');
    this.line('#endif');
    // The descriptor's <content>, i.e. the SWF that AIR nests local objects under:
    // "#SharedObjects/<content path>/...". Empty for a bare build (no descriptor),
    // where AIR has no SWF URL to derive the directory from.
    this.line('#ifndef ASC_SWF_PATH');
    this.line('#define ASC_SWF_PATH ""');
    this.line('#endif');
    this.line('static char* as_app_storage_dir(void) {');
    this.indent++;
    this.line('char* home = as_home_dir();');
    this.line('char* base = NULL;');
    this.line('#ifdef _WIN32');
    this.line('char* appdata = getenv("APPDATA");');
    this.line('if (appdata == NULL || *appdata == \'\\0\') appdata = as_path_join(home, "AppData/Roaming");');
    this.line('base = as_path_join(appdata, ASC_APP_ID);');
    this.line('base = as_path_join(base, "Local Store");');
    this.line('#elif defined(__APPLE__)');
    this.line('base = as_path_join(home, "Library/Application Support/" ASC_APP_ID "/Local Store");');
    this.line('#else');
    this.line('base = as_path_join(home, ".as3aot");');
    this.line('base = as_path_join(base, ASC_APP_ID);');
    this.line('#endif');
    this.line('as_mkdirs(base);');
    this.line('return base;');
    this.indent--;
    this.line('}');
    this.line('');
    // File: a filesystem path bundle. url is "file://" + nativePath.
    this.line('void File_ctor(File* o, char* path) {');
    this.indent++;
    this.line('EventDispatcher_ctor((EventDispatcher*)o, NULL);');
    this.line('o->nativePath = path; gc_write_barrier((void*)path);');
    this.indent--;
    this.line('}');
    this.line('File* File_new(char* path) { File* o = (File*)gc_alloc(GCT_CLASS, sizeof(File)); o->vtable = &File_vt; File_ctor(o, path); return o; }');
    this.line('char* File_get_url(void* _this) { File* o = (File*)_this; return (o->nativePath == NULL) ? (char*)"file://" : as_str_concat((char*)"file://", o->nativePath); }');
    this.line('bool File_get_exists(void* _this) { File* o = (File*)_this; return o->nativePath != NULL && as_path_exists(o->nativePath); }');
    this.line('bool File_get_isDirectory(void* _this) { File* o = (File*)_this; return o->nativePath != NULL && as_path_is_dir(o->nativePath); }');
    // isSymbolicLink: about the link, not its target (AIR 1.0). A path that does not
    // exist is false, a dangling link is true -- lstat() answers both without
    // resolving, so no extra existence gate is needed.
    this.line('bool File_get_isSymbolicLink(void* _this) { File* o = (File*)_this; return o->nativePath != NULL && as_path_is_symlink(o->nativePath); }');
    // size: the length in bytes, measured with stat() (AIR's File.size is a
    // Number). A path that does not exist reports 0, matching AIR; st_size is an
    // off_t, so it is widened to double rather than truncated to int (a >2 GB file
    // must not go negative).
    this.line('double File_get_size(void* _this) { File* o = (File*)_this; if (o->nativePath == NULL) return 0.0; struct stat st; if (stat(o->nativePath, &st) != 0) return 0.0; return (double)st.st_size; }');
    // spaceAvailable: the free bytes on the volume that holds this path. AIR asks
    // the OS for it, so we do too -- GetDiskFreeSpaceExA on Windows, statvfs() on
    // POSIX (bavail*frsize is the space an unprivileged process may actually use,
    // which is what AIR reports). A path the OS cannot resolve, and a platform
    // with no volume concept (wasm), report 0: the app only tests truthiness
    // ("is there room for the recording") and a fabricated number would be worse
    // than a real "none".
    this.line('static double as_file_space_available(const char* p) {');
    this.indent++;
    this.line('if (p == NULL) return 0.0;');
    // AIR resolves the path through NSFileManager's attributesOfFileSystem, which
    // answers only for a regular file or a directory: measured on 51.4.1, a
    // character device (/dev/null) reports 0 while a file and a directory both
    // report their volume's figure. statvfs()/GetDiskFreeSpaceExA alone would
    // happily answer for the device, so the type check comes first.
    this.line('#ifndef _WIN32');
    this.indent++;
    this.line('{ struct stat st; if (stat(p, &st) != 0) return 0.0; if (!S_ISDIR(st.st_mode) && !S_ISREG(st.st_mode)) return 0.0; }');
    this.indent--;
    this.line('#endif');
    this.line('#ifdef _WIN32');
    this.indent++;
    this.line('// GetDiskFreeSpaceEx asks for a DIRECTORY, so a path naming a regular file must');
    this.line('// be mapped to the volume that holds it first -- GetVolumePathName answers for');
    this.line('// either kind of path, which is what makes a file report the same figure as the');
    this.line('// directory containing it (measured: adl does exactly that on Windows). The');
    this.line('// existence gate is what keeps a path the OS cannot resolve at 0: GetVolumePath');
    this.line('// Name walks UP to the nearest mounted ancestor, so without it an unresolvable');
    this.line('// path would report its volume figure instead (measured: adl reports 0).');
    this.line('if (!as_path_exists(p)) return 0.0;');
    this.line('char root[MAX_PATH];');
    this.line('if (!GetVolumePathNameA(p, root, MAX_PATH)) return 0.0;');
    this.line('ULARGE_INTEGER freeAvail;');
    this.line('freeAvail.QuadPart = 0;');
    this.line('if (!GetDiskFreeSpaceExA(root, &freeAvail, NULL, NULL)) return 0.0;');
    this.line('return (double)freeAvail.QuadPart;');
    this.indent--;
    this.line('#elif !defined(__wasi__) && !defined(__EMSCRIPTEN__)');
    this.indent++;
    this.line('struct statvfs sv;');
    this.line('if (statvfs(p, &sv) != 0) return 0.0;');
    this.line('return (double)sv.f_bavail * (double)sv.f_frsize;');
    this.indent--;
    this.line('#else');
    this.indent++;
    this.line('return 0.0;');
    this.indent--;
    this.line('#endif');
    this.indent--;
    this.line('}');
    this.line('double File_get_spaceAvailable(void* _this) { File* o = (File*)_this; return as_file_space_available(o->nativePath); }');
    // name: the last component of the path (AIR's File.name). BOTH separators count,
    // so a Windows nativePath ("C:\\Users\\x\\a.log") names the file and not the
    // drive, and a trailing separator is ignored ("/a/b/" names "b").
    this.line('char* File_get_name(void* _this) {');
    this.indent++;
    this.line('File* o = (File*)_this;');
    this.line('if (o->nativePath == NULL) return (char*)"";');
    this.line('const char* s = o->nativePath;');
    this.line('int n = (int)strlen(s);');
    this.line('while (n > 1 && (s[n - 1] == \'/\' || s[n - 1] == \'\\\\\')) n--;');
    this.line('int start = 0;');
    this.line('for (int i = n - 1; i >= 0; i--) if (s[i] == \'/\' || s[i] == \'\\\\\') { start = i + 1; break; }');
    this.line('char* out = as_str_alloc((size_t)(n - start) + 1);');
    this.line('memcpy(out, s + start, (size_t)(n - start));');
    this.line('out[n - start] = \'\\0\';');
    this.line('return out;');
    this.indent--;
    this.line('}');
    // extension: the text after the last dot of the NAME, or "" when there is none.
    // A dot-file (".DS_Store") has no extension in AIR (not "DS_Store"), and the
    // search starts after the last separator so "a.b/c" is "" while "a/b.c" is "c".
    this.line('char* File_get_extension(void* _this) {');
    this.indent++;
    this.line('File* o = (File*)_this;');
    this.line('if (o->nativePath == NULL) return (char*)"";');
    this.line('const char* s = o->nativePath;');
    this.line('int n = (int)strlen(s);');
    this.line('while (n > 1 && (s[n - 1] == \'/\' || s[n - 1] == \'\\\\\')) n--;');
    this.line('int base = 0;');
    this.line('for (int i = n - 1; i >= 0; i--) if (s[i] == \'/\' || s[i] == \'\\\\\') { base = i + 1; break; }');
    this.line('int dot = -1;');
    this.line('for (int i = n - 1; i > base; i--) if (s[i] == \'.\') { dot = i; break; }');
    this.line('if (dot < 0) return (char*)"";');
    this.line('char* out = as_str_alloc((size_t)(n - dot - 1) + 1);');
    this.line('memcpy(out, s + dot + 1, (size_t)(n - dot - 1));');
    this.line('out[n - dot - 1] = \'\\0\';');
    this.line('return out;');
    this.indent--;
    this.line('}');
    // type: AIR's FileReference.type on Windows/Linux is the file's extension; the
    // form published AIR apps rely on is dot-prefixed and lower-case, so this is
    // "." + extension (lower-cased), or "" when the name has no dot. Built on
    // File_get_extension, so the separator/dot-file rules stay in one place.
    this.line('char* File_get_type(void* _this) {');
    this.indent++;
    this.line('char* ext = File_get_extension(_this);');
    this.line('int n = (int)strlen(ext);');
    this.line('if (n == 0) return (char*)"";');
    this.line('char* out = as_str_alloc((size_t)n + 2);');
    this.line('out[0] = \'.\';');
    this.line('for (int i = 0; i < n; i++) {');
    this.indent++;
    this.line('char c = ext[i];');
    this.line('if (c >= \'A\' && c <= \'Z\') c = (char)(c + 32);');
    this.line('out[i + 1] = c;');
    this.indent--;
    this.line('}');
    this.line('out[n + 1] = \'\\0\';');
    this.line('return out;');
    this.indent--;
    this.line('}');
    // parent: the containing directory as a File (AIR's File.parent). NULL at the
    // filesystem root, exactly like AIR -- a caller that dereferences it gets the
    // usual catchable TypeError #1009 rather than a wrong path.
    this.line('File* File_get_parent(void* _this) {');
    this.indent++;
    this.line('File* o = (File*)_this;');
    this.line('if (o->nativePath == NULL) return NULL;');
    this.line('const char* s = o->nativePath;');
    this.line('int n = (int)strlen(s);');
    this.line('while (n > 1 && (s[n - 1] == \'/\' || s[n - 1] == \'\\\\\')) n--;');
    this.line('int cut = -1;');
    this.line('for (int i = n - 1; i > 0; i--) if (s[i] == \'/\' || s[i] == \'\\\\\') { cut = i; break; }');
    this.line('if (cut <= 0) return NULL;');
    this.line('char* out = as_str_alloc((size_t)cut + 1);');
    this.line('memcpy(out, s, (size_t)cut);');
    this.line('out[cut] = \'\\0\';');
    this.line('return File_new(out);');
    this.indent--;
    this.line('}');
    // isHidden: on POSIX a file is hidden when its basename starts with a dot
    // (matches the .DS_Store filtering the demo relies on).
    this.line('bool File_get_isHidden(void* _this) {');
    this.indent++;
    this.line('File* o = (File*)_this;');
    this.line('if (o->nativePath == NULL) return false;');
    this.line('const char* base = o->nativePath;');
    this.line('for (const char* p = o->nativePath; *p; p++) if (*p == \'/\' || *p == \'\\\\\') base = p + 1;');
    this.line('return base[0] == \'.\';');
    this.indent--;
    this.line('}');
    this.line('File* File_resolvePath(void* _this, char* path) { File* o = (File*)_this; return (o->nativePath == NULL) ? File_new(path) : File_new(as_path_join(o->nativePath, path)); }');
    this.line('void File_createDirectory(void* _this) { File* o = (File*)_this; if (o->nativePath != NULL) as_mkdirs(o->nativePath); }');
    this.line('void File_deleteFile(void* _this) { File* o = (File*)_this; if (o->nativePath != NULL) remove(o->nativePath); }');
    this.line('void File_deleteDirectory(void* _this) { File* o = (File*)_this; if (o->nativePath != NULL) as_rmdir_one(o->nativePath); }');
    // ---- File.moveToTrash / moveToTrashAsync (AIR 2) ----
    this.line('// Measured against adl 51.4.1 on macOS 26 (temp/trashprobe/):');
    this.line('//   * moveToTrash() is declared VOID, not Boolean -- f.moveToTrash().toString()');
    this.line('//     is a compile error in mxmlc, and adl evaluates the call to undefined.');
    this.line('//   * a path that does not exist throws Error #3003 "File or directory does not');
    this.line('//     exist."; a filesystem refusal (EPERM on the parent directory) throws #2038');
    this.line('//     "File I/O Error."; a File with no nativePath throws #2037.');
    this.line('//   * after a successful move nativePath is UNCHANGED and exists becomes false:');
    this.line('//     the receiver keeps denoting the old location, it is not rewritten.');
    this.line('//   * trashing a path that already sits in the trash directory is a successful');
    this.line('//     no-op -- adl leaves the item where it is.');
    this.line('//   * moveToTrashAsync() never throws for those failures: a missing path');
    this.line('//     dispatches IOErrorEvent(ioError, errorID 3003), success dispatches');
    this.line('//     Event.COMPLETE, and only the empty-File case throws #2037.');
    this.line('// The directory is the one Finder uses, so the item appears in the Trash under');
    this.line('// its own name and stays restorable: ~/.Trash on the home volume,');
    this.line('// <volume root>/.Trashes/<uid> on another volume. Plain POSIX uses the');
    this.line('// freedesktop.org layout ($XDG_DATA_HOME/Trash/{files,info} plus a .trashinfo');
    this.line('// sidecar beside each payload) so a Linux desktop can put it back. Windows has');
    this.line('// no such directory to rename into -- its trash is the shell\'s Recycle Bin, a');
    this.line('// per-user store of $I<id>/$R<id> pairs reachable only through SHFileOperationW');
    this.line('// -- so that host takes the separate as_trash_move_shell path below (measured:');
    this.line('// adl 51.4.1 really does recycle the item there rather than erase it).');
    this.line('// as_path_basename: a fresh string with the last component of `path` (trailing');
    this.line('// separators ignored), or NULL when the path names no component ("/").');
    this.line('static char* as_path_basename(const char* p) {');
    this.line('  if (p == NULL) return NULL;');
    this.line('  size_t n = strlen(p);');
    this.line('  while (n > 1 && (p[n - 1] == \'/\' || p[n - 1] == \'\\\\\')) n--;');
    this.line('  size_t start = 0;');
    this.line('  for (size_t i = 0; i < n; i++) if (p[i] == \'/\' || p[i] == \'\\\\\') start = i + 1;');
    this.line('  if (start >= n) return NULL;');
    this.line('  char* out = as_str_alloc(n - start + 1);');
    this.line('  memcpy(out, p + start, n - start);');
    this.line('  out[n - start] = \'\\0\';');
    this.line('  return out;');
    this.line('}');
    this.line('');
    this.line('// as_volume_root: the mount point that owns `path`. POSIX has no portable');
    this.line('// "which mount is this" call, so walk up while st_dev stays the same; the last');
    this.line('// directory that still shares the path\'s device is the volume root.');
    this.line('static char* as_volume_root(const char* path) {');
    this.line('  struct stat st;');
    this.line('  if (path == NULL || stat(path, &st) != 0) return NULL;');
    this.line('  dev_t dev = st.st_dev;');
    this.line('  char* cur = as_str_alloc(strlen(path) + 2);');
    this.line('  strcpy(cur, path);');
    this.line('  size_t n = strlen(cur);');
    this.line('  while (n > 1 && (cur[n - 1] == \'/\' || cur[n - 1] == \'\\\\\')) cur[--n] = \'\\0\';');
    this.line('  while (n > 1) {');
    this.line('    size_t sep = n;');
    this.line('    while (sep > 0 && cur[sep - 1] != \'/\' && cur[sep - 1] != \'\\\\\') sep--;');
    this.line('    if (sep == 0) break;');
    this.line('    size_t plen = sep - 1;');
    this.line('    char saved = cur[plen];');
    this.line('    cur[plen] = \'\\0\';');
    this.line('    const char* parent = (plen == 0) ? "/" : cur;');
    this.line('    struct stat ps;');
    this.line('    bool same = (stat(parent, &ps) == 0 && ps.st_dev == dev);');
    this.line('    cur[plen] = saved;');
    this.line('    if (!same) break;');
    this.line('    if (plen == 0) { cur[0] = \'/\'; cur[1] = \'\\0\'; n = 1; break; }');
    this.line('    n = plen;');
    this.line('    cur[n] = \'\\0\';');
    this.line('  }');
    this.line('  return cur;');
    this.line('}');
    this.line('');
    this.line('// as_trash_stamp: the " HH-MM-SS-mmm" collision suffix macOS inserts (measured:');
    this.line('// "x.txt" -> "x.txt 18-34-09-271.txt"). Local time, like Finder.');
    this.line('static void as_trash_stamp(char* out, size_t cap, int attempt) {');
    this.line('  int h, m, s, ms;');
    this.line('#ifdef _WIN32');
    this.line('  SYSTEMTIME lt;');
    this.line('  GetLocalTime(&lt);');
    this.line('  h = lt.wHour; m = lt.wMinute; s = lt.wSecond; ms = (int)lt.wMilliseconds;');
    this.line('#elif defined(__wasi__) || defined(__EMSCRIPTEN__)');
    this.line('  h = 0; m = 0; s = 0; ms = 0;');
    this.line('#else');
    this.line('  struct timeval tv;');
    this.line('  struct tm lt;');
    this.line('  gettimeofday(&tv, NULL);');
    this.line('  localtime_r(&tv.tv_sec, &lt);');
    this.line('  h = lt.tm_hour; m = lt.tm_min; s = lt.tm_sec; ms = (int)(tv.tv_usec / 1000);');
    this.line('#endif');
    this.line('  if (attempt == 0) snprintf(out, cap, " %02d-%02d-%02d-%03d", h, m, s, ms);');
    this.line('  else snprintf(out, cap, " %02d-%02d-%02d-%03d-%d", h, m, s, ms, attempt);');
    this.line('}');
    this.line('');
    this.line('// as_trash_target: dir/name, or -- when that name is taken -- the name macOS');
    this.line('// gives the second copy: the item keeps its WHOLE name (extension included), then');
    this.line('// " HH-MM-SS-mmm", then the extension again. Measured on 51.4.1:');
    this.line('// "x.txt" -> "x.txt 18-34-09-271.txt", "dupsub" -> "dupsub 18-37-21-029".');
    this.line('static char* as_trash_target(const char* dir, const char* name) {');
    this.line('  char* plain = as_path_join(dir, name);');
    this.line('  if (!as_path_exists(plain)) return plain;');
    this.line('  const char* dot = NULL;');
    this.line('  for (const char* q = name; *q != \'\\0\'; q++) if (*q == \'.\') dot = q;');
    this.line('  const char* ext = (dot != NULL && dot != name) ? dot : "";');
    this.line('  size_t nl = strlen(name), el = strlen(ext);');
    this.line('  for (int attempt = 0; attempt < 64; attempt++) {');
    this.line('    char stamp[48];');
    this.line('    as_trash_stamp(stamp, sizeof stamp, attempt);');
    this.line('    size_t sl = strlen(stamp);');
    this.line('    char* stamped = as_str_alloc(nl + sl + el + 1);');
    this.line('    memcpy(stamped, name, nl);');
    this.line('    memcpy(stamped + nl, stamp, sl);');
    this.line('    memcpy(stamped + nl + sl, ext, el);');
    this.line('    stamped[nl + sl + el] = \'\\0\';');
    this.line('    char* target = as_path_join(dir, stamped);');
    this.line('    if (!as_path_exists(target)) return target;');
    this.line('  }');
    this.line('  return NULL;');
    this.line('}');
    this.line('');
    this.line('// as_trash_dir: the directory this path is trashed into, or NULL when there is');
    this.line('// no usable trash for it (which the caller turns into #2038).');
    this.line('static char* as_trash_dir(const char* path) {');
    this.line('#if defined(__wasi__) || defined(__EMSCRIPTEN__)');
    this.line('  (void)path;');
    this.line('  return NULL;');
    this.line('#elif defined(_WIN32)');
    this.line('  // Windows never reaches this: as_trash_move routes to as_trash_move_shell');
    this.line('  // first, because the Recycle Bin is not a directory to rename into. The arm');
    this.line('  // exists only so this #if chain stays exhaustive for the target.');
    this.line('  (void)path;');
    this.line('  return NULL;');
    this.line('#elif defined(__APPLE__)');
    this.line('  struct stat st;');
    this.line('  if (path == NULL || stat(path, &st) != 0) return NULL;');
    this.line('  char* home = as_home_dir();');
    this.line('  struct stat hs;');
    this.line('  if (home != NULL && stat(home, &hs) == 0 && hs.st_dev == st.st_dev) {');
    this.line('    char* t = as_path_join(home, ".Trash");');
    this.line('    if (as_path_is_dir(t)) return t;');
    this.line('    as_mkdirs(t);');
    this.line('    return as_path_is_dir(t) ? t : NULL;');
    this.line('  }');
    this.line('  char* root = as_volume_root(path);');
    this.line('  if (root == NULL) return NULL;');
    this.line('  char owner[40];');
    this.line('  snprintf(owner, sizeof owner, ".Trashes/%d", (int)getuid());');
    this.line('  char* t = as_path_join(root, owner);');
    this.line('  if (as_path_is_dir(t)) return t;');
    this.line('  as_mkdirs(t);');
    this.line('  return as_path_is_dir(t) ? t : NULL;');
    this.line('#else');
    this.line('  // freedesktop.org trash: $XDG_DATA_HOME/Trash (default ~/.local/share/Trash)');
    this.line('  // holds the payloads under files/ and a .trashinfo beside each one under');
    this.line('  // info/, so the desktop can restore it. A path on another volume uses');
    this.line('  // <volume root>/.Trash/<uid>, per the specification.');
    this.line('  struct stat st, hs;');
    this.line('  if (path == NULL || stat(path, &st) != 0) return NULL;');
    this.line('  char* home = as_home_dir();');
    this.line('  bool home_volume = (home != NULL && stat(home, &hs) == 0 && hs.st_dev == st.st_dev);');
    this.line('  char* base;');
    this.line('  if (home_volume) {');
    this.line('    const char* xdg = getenv("XDG_DATA_HOME");');
    this.line('    base = (xdg != NULL && xdg[0] == \'/\') ? as_path_join(xdg, "Trash") : as_path_join(home, ".local/share/Trash");');
    this.line('  } else {');
    this.line('    char* root = as_volume_root(path);');
    this.line('    if (root == NULL) return NULL;');
    this.line('    char owner[40];');
    this.line('    snprintf(owner, sizeof owner, ".Trash/%d", (int)getuid());');
    this.line('    base = as_path_join(root, owner);');
    this.line('  }');
    this.line('  char* files = as_path_join(base, "files");');
    this.line('  if (!as_path_is_dir(files)) as_mkdirs(files);');
    this.line('  return as_path_is_dir(files) ? files : NULL;');
    this.line('#endif');
    this.line('}');
    this.line('');
    this.line('// as_trash_note: record where the payload came from, for the desktop\'s "put');
    this.line('// back". Only the freedesktop layout has such a sidecar; Finder (macOS) does');
    this.line('// not (it stores the Put Back location in the volume\'s metadata).');
    this.line('static void as_trash_note(const char* files_dir, const char* moved_path, const char* original) {');
    this.line('#if !defined(__APPLE__) && !defined(_WIN32) && !defined(__wasi__) && !defined(__EMSCRIPTEN__)');
    this.line('  size_t fl = strlen(files_dir);');
    this.line('  if (fl <= 5 || strcmp(files_dir + fl - 5, "files") != 0) return;');
    this.line('  char* base = as_str_alloc(fl - 4);');
    this.line('  memcpy(base, files_dir, fl - 5);');
    this.line('  base[fl - 5] = \'\\0\';');
    this.line('  char* info = as_path_join(base, "info");');
    this.line('  if (!as_path_is_dir(info)) as_mkdirs(info);');
    this.line('  if (!as_path_is_dir(info)) return;');
    this.line('  char* leaf = as_path_basename(moved_path);');
    this.line('  if (leaf == NULL) return;');
    this.line('  char* leafinfo = as_str_concat(leaf, ".trashinfo");');
    this.line('  char* note = as_path_join(info, leafinfo);');
    this.line('  FILE* fp = fopen(note, "w");');
    this.line('  if (fp == NULL) return;');
    this.line('  fprintf(fp, "[Trash Info]\\nPath=");');
    this.line('  for (const char* q = original; *q != \'\\0\'; q++) {');
    this.line('    unsigned char c = (unsigned char)*q;');
    this.line('    bool keep = ((c >= \'A\' && c <= \'Z\') || (c >= \'a\' && c <= \'z\') || (c >= \'0\' && c <= \'9\') ||');
    this.line('                 c == \'/\' || c == \'.\' || c == \'_\' || c == \'-\');');
    this.line('    if (keep) fputc((int)c, fp);');
    this.line('    else fprintf(fp, "%%%02X", (unsigned)c);');
    this.line('  }');
    this.line('  time_t now = time(NULL);');
    this.line('  struct tm lt;');
    this.line('  localtime_r(&now, &lt);');
    this.line('  fprintf(fp, "\\nDeletionDate=%04d-%02d-%02dT%02d:%02d:%02d\\n", lt.tm_year + 1900, lt.tm_mon + 1, lt.tm_mday, lt.tm_hour, lt.tm_min, lt.tm_sec);');
    this.line('  fclose(fp);');
    this.line('#else');
    this.line('  (void)files_dir; (void)moved_path; (void)original;');
    this.line('#endif');
    this.line('}');
    this.line('');
    this.line('// as_trash_move_shell: the Windows arm -- hand the path to the shell-owned');
    this.line('// Recycle Bin operation. FOF_ALLOWUNDO is what makes the item RECOVERABLE instead');
    this.line('// of erased, and the absence of any confirmation UI keeps the call as silent as');
    this.line('// AIR is. A volume with no Recycle Bin at all (a removable drive, or a bin the');
    this.line('// user turned off) makes the shell delete the item, which is precisely what the');
    this.line('// AS3 reference prescribes for such a host ("on operating systems that do not');
    this.line('// support the concept of a recoverable trash folder, the files are removed');
    this.line('// immediately") -- the shell answering, not a fallback invented here.');
    this.line('//');
    this.line('// The wide conversion is CP_ACP, not CP_UTF8, because every other Windows path');
    this.line('// call in this runtime is the ANSI one (stat, GetModuleFileNameA, remove): that');
    this.line('// is the same reading of the same bytes, whereas decoding as UTF-8 would send');
    this.line('// the shell to a path the rest of the runtime cannot see.');
    this.line('//');
    this.line('// The caller has already rejected NULL/empty (2037) and a path that does not');
    this.line('// exist (3003) -- measured: adl answers those with the same two numbers on');
    this.line('// Windows as it does on macOS, so the shared prelude is not skipped here.');
    this.line('#ifdef _WIN32');
    this.line('static long as_trash_move_shell(const char* path) {');
    this.line('  // SHFileOperationW takes a DOUBLE-NUL-terminated list of paths, so `from`');
    this.line('  // carries one terminator past the end of the string.');
    this.line('  int need = MultiByteToWideChar(CP_ACP, 0, path, -1, NULL, 0);');
    this.line('  if (need <= 0) return 2038;');
    this.line('  WCHAR* from = (WCHAR*)as_alloc((size_t)(need + 1) * sizeof(WCHAR));');
    this.line('  if (MultiByteToWideChar(CP_ACP, 0, path, -1, from, need) <= 0) return 2038;');
    this.line('  from[need] = 0;');
    this.line('  SHFILEOPSTRUCTW op;');
    this.line('  memset(&op, 0, sizeof op);');
    this.line('  op.wFunc = FO_DELETE;');
    this.line('  op.pFrom = from;');
    this.line('  op.fFlags = FOF_ALLOWUNDO | FOF_NOCONFIRMATION | FOF_NOERRORUI | FOF_SILENT;');
    this.line('  if (SHFileOperationW(&op) != 0) return 2038;');
    this.line('  if (op.fAnyOperationsAborted) return 2038;');
    this.line('  return 0;');
    this.line('}');
    this.line('#endif');
    this.line('');
    this.line('// as_trash_move: 0 on success, else the AIR error number to report.');
    this.line('static long as_trash_move(const char* path) {');
    this.line('  if (path == NULL || path[0] == \'\\0\') return 2037;');
    this.line('  struct stat st;');
    this.line('  if (stat(path, &st) != 0) return 3003;');
    this.line('#ifdef _WIN32');
    this.line('  return as_trash_move_shell(path);');
    this.line('#else');
    this.line('  char* dir = as_trash_dir(path);');
    this.line('  if (dir == NULL) return 2038;');
    this.line('  char* name = as_path_basename(path);');
    this.line('  if (name == NULL) return 2038;');
    this.line('  // Already inside the trash directory: AIR treats this as a successful no-op.');
    this.line('  size_t dl = strlen(dir);');
    this.line('  if (strncmp(path, dir, dl) == 0 && path[dl] == \'/\') {');
    this.line('    bool nested = false;');
    this.line('    for (const char* q = path + dl + 1; *q != \'\\0\'; q++) if (*q == \'/\') nested = true;');
    this.line('    if (!nested) return 0;');
    this.line('  }');
    this.line('  char* target = as_trash_target(dir, name);');
    this.line('  if (target == NULL) return 2038;');
    this.line('  if (rename(path, target) != 0) return 2038;');
    this.line('  as_trash_note(dir, target, path);');
    this.line('  return 0;');
    this.line('#endif');
    this.line('}');
    this.line('');
    this.line('void File_moveToTrash(void* _this) {');
    this.line('  long err = as_trash_move(((File*)_this)->nativePath);');
    this.line('  if (err == 0) return;');
    this.line('  if (err == 2037) { as_throw(Error_new((char*)"Error #2037: Functions called in incorrect sequence, or earlier call was unsuccessful.", 2037)); return; }');
    this.line('  if (err == 3003) { as_throw(Error_new((char*)"Error #3003: File or directory does not exist.", 3003)); return; }');
    this.line('  as_throw(IOError_new((char*)"Error #2038: File I/O Error.", 2038));');
    this.line('}');
    this.line('// moveToTrashAsync dispatches its outcome instead of throwing (measured: a');
    this.line('// missing path is an ioError, not an exception). AIR delivers the event from');
    this.line('// its own IO thread; this build performs the move inline and dispatches from');
    this.line('// the same call -- the convention every other async member of File follows');
    this.line('// here (see File_getDirectoryListingAsync).');
    this.line('void File_moveToTrashAsync(void* _this) {');
    this.line('  File* o = (File*)_this;');
    this.line('  long err = as_trash_move(o->nativePath);');
    this.line('  if (err == 2037) { as_throw(Error_new((char*)"Error #2037: Functions called in incorrect sequence, or earlier call was unsuccessful.", 2037)); return; }');
    this.line('  if (err == 0) { EventDispatcher_dispatchEvent((void*)o, Event_new((char*)"complete", false, false)); return; }');
    this.line('  const char* text = (err == 3003) ? "Error #3003: File or directory does not exist." : "Error #2038: File I/O Error.";');
    this.line('  IOErrorEvent* ev = IOErrorEvent_new((char*)"ioError", false, false, (char*)text);');
    this.line('  ev->errorID = (int)err;');
    this.line('  EventDispatcher_dispatchEvent((void*)o, (Event*)ev);');
    this.line('}');
    // File.moveTo(newFile, overwrite = false, force = false): rename() the path.
    // rename() is the real operation AIR performs (atomic within one volume); the two
    // failure modes AIR raises IOError for are reported on stderr instead of thrown,
    // because an IOError thrown here would unwind through the caller's event handler.
    this.line('void File_moveTo(void* _this, File* target, bool overwrite, bool force) {');
    this.indent++;
    this.line('File* o = (File*)_this;');
    this.line('if (target == NULL || o->nativePath == NULL || target->nativePath == NULL) return;');
    this.line('if (!as_path_exists(o->nativePath)) { as_shell_unsupported("File.moveTo with a source path that does not exist (AIR throws IOError)"); return; }');
    this.line('if (as_path_exists(target->nativePath) && !(overwrite || force)) { as_shell_unsupported("File.moveTo onto an existing path with overwrite/force false (AIR throws IOError)"); return; }');
    // A cross-volume move makes rename() fail (Windows: EXDEV-style failure); it is
    // reported rather than silently copied, so a caller is never told a move happened
    // when the file is still at the old path.
    this.line('if (rename(o->nativePath, target->nativePath) != 0) { as_shell_unsupported("File.moveTo across volumes (rename failed)"); return; }');
    // AIR: the receiver now denotes the new location.
    this.line('o->nativePath = target->nativePath;');
    this.line('gc_write_barrier((void*)o->nativePath);');
    this.indent--;
    this.line('}');
    // The async half of the File API. `getDirectoryListingAsync` is the one member
    // that is genuinely asynchronous in this build: it enumerates on a worker
    // thread (AS_JOB_DIR) and dispatches at a frame boundary, because that is what
    // adl does and what the member is FOR. Measured against adl 51.4.1 --
    // `temp/dirasync/` -- the contract has five parts, and all five are reproduced
    // below: (1) the call returns immediately even for a 20,000-entry directory
    // (adl: 0 ms, with the event ~10.6 s later); (2) delivery happens AFTER the
    // call returns, so a listener registered immediately afterwards still fires;
    // (3) a path that does not exist dispatches ioError #3003 instead of
    // completing; (4) a path that exists and is NOT a directory completes with an
    // empty files array (the sync member throws #3007 for that same input, so the
    // two are deliberately not shared); (5) a second call while one is in flight
    // throws #2037, while `cancel()` actually cancels -- the pending event is
    // dropped, which is what makes cancel() mean anything here.
    //
    // The other async members (`moveToTrashAsync`/`deleteFileAsync`/
    // `deleteDirectoryAsync`) still complete inline; their deferred delivery is
    // registered in TODO.md's 遗留待开发, not silently claimed here.
    this.line('static void File__dirFinish(void* job) {');
    this.indent++;
    this.line('File* o = (File*)as_job_obj(job);');
    this.line('if (o == NULL) return;');
    this.line('int err = as_job_failed(job);');
    this.line('if (err == AS_JOB_ERR_NOT_FOUND) {');
    this.indent++;
    this.line('IOErrorEvent* ev = IOErrorEvent_new((char*)"ioError", false, false, (char*)"Error #3003: File or directory does not exist.");');
    this.line('ev->errorID = 3003;');
    this.line('EventDispatcher_dispatchEvent((void*)o, (Event*)ev);');
    this.line('return;');
    this.indent--;
    this.line('}');
    this.line('if (err != 0) {');
    this.indent++;
    // Only the worker's own allocation failure reaches here: a path that cannot be
    // OPENED (unreadable, or not a directory) completes with an empty listing
    // instead, which is what adl 51.4.1 does for both (measured in
    // temp/listingprobe/). #2038 is AIR's File I/O id, but this branch is NOT
    // measurable against adl -- there is no input that produces it there -- so it
    // is reported rather than guessed at per-errno.
    this.line('IOErrorEvent* ev = IOErrorEvent_new((char*)"ioError", false, false, (char*)"Error #2038: File I/O Error.");');
    this.line('ev->errorID = 2038;');
    this.line('EventDispatcher_dispatchEvent((void*)o, (Event*)ev);');
    this.line('return;');
    this.indent--;
    this.line('}');
    this.line('as_array* files = as_array_new();');
    this.line('int n = as_job_dir_count(job);');
    this.line('for (int i = 0; i < n; i++) {');
    this.indent++;
    this.line('char* nm = as_job_dir_name(job, i);');
    this.line('if (nm == NULL) continue;');
    this.line('as_array_push(files, as_v_obj((void*)File_new(as_path_join(o->nativePath, nm))));');
    this.indent--;
    this.line('}');
    // FileListEvent's fifth parameter is 'files'; our shell also declares a fourth
    // ('directory') that AIR's class does not have -- that over-declaration is a
    // registered divergence, so the receiver is passed there and 'files' keeps its
    // AIR position.
    this.line('EventDispatcher_dispatchEvent((void*)o, (Event*)FileListEvent_new((char*)"directoryListing", false, false, o, files));');
    this.indent--;
    this.line('}');
    this.line('void File_getDirectoryListingAsync(void* _this) {');
    this.indent++;
    this.line('File* o = (File*)_this;');
    // Both guards report the SAME #2037 text, which is what adl does: an empty
    // File and a call-while-in-flight are one error id and one message there.
    this.line('if (o->nativePath == NULL || as_async_dir_pending((void*)o)) {');
    this.indent++;
    this.line('as_throw(Error_new((char*)"Error #2037: Functions called in incorrect sequence, or earlier call was unsuccessful.", 2037));');
    this.line('return;');
    this.indent--;
    this.line('}');
    this.line('as_async_submit(AS_JOB_DIR, (void*)o, File__dirFinish, o->nativePath, NULL, 0);');
    this.indent--;
    this.line('}');
    this.line('void File_deleteFileAsync(void* _this) {');
    this.indent++;
    this.line('File_deleteFile(_this);');
    this.line('EventDispatcher_dispatchEvent((void*)_this, Event_new((char*)"complete", false, false));');
    this.indent--;
    this.line('}');
    // File.cancel(): cancels the pending directory listing (the only async member
    // here that has something in flight). AIR's cancel() drops the event, and so
    // does this: as_async_cancel marks the job dead, so its thunk never runs and
    // nothing is dispatched. The other async members have already completed by the
    // time they return, so for them -- and for a cancel() with nothing pending --
    // this stays a no-op, exactly as adl leaves it.
    this.line('void File_cancel(void* _this) { as_async_cancel((void*)_this); }');
    this.line('void File_deleteDirectoryAsync(void* _this, bool deleteDirectory) {');
    this.indent++;
    this.line('(void)deleteDirectory;');
    this.line('File_deleteDirectory(_this);');
    this.line('EventDispatcher_dispatchEvent((void*)_this, Event_new((char*)"complete", false, false));');
    this.indent--;
    this.line('}');
    // No backend here: a native file dialog / the OS shell. These report
    // themselves once (stderr) instead of silently returning, so a flow that
    // depends on one is visibly stalled rather than mysteriously empty.
    this.line('void File_browseForDirectory(void* _this, char* title) { (void)_this; (void)title; as_shell_unsupported((char*)"flash.filesystem.File.browseForDirectory"); }');
    this.line('void File_browseForOpen(void* _this, char* title, as_array* typeFilter) { (void)_this; (void)title; (void)typeFilter; as_shell_unsupported((char*)"flash.filesystem.File.browseForOpen"); }');
    this.line('void File_openWithDefaultApplication(void* _this) { (void)_this; as_shell_unsupported((char*)"flash.filesystem.File.openWithDefaultApplication"); }');
    // File.upload(request, fieldName, testUpload): POST the file's contents as
    // multipart/form-data. There is no HTTP request backend in this build, so the
    // call reports itself once (stderr) and dispatches NOTHING -- the upload cannot
    // silently "succeed", which is what an app waiting on
    // DataEvent.UPLOAD_COMPLETE_DATA would otherwise conclude.
    this.line('void File_upload(void* _this, URLRequest* request, char* uploadDataFieldName, bool testUpload) { (void)_this; (void)request; (void)uploadDataFieldName; (void)testUpload; as_shell_unsupported((char*)"flash.filesystem.File.upload (no HTTP upload backend in this build)"); }');
    // getDirectoryListing: list a directory's children as File objects (skipping
    // . and ..), used by AssetManager to recursively enqueue folder contents.
    this.line('as_array* File_getDirectoryListing(void* _this) {');
    this.indent++;
    this.line('File* o = (File*)_this;');
    // The three guards, in the order adl 51.4.1 applies them (measured on all four
    // odd shapes in temp/listingprobe/): no path at all is #2037, a path that does
    // not exist is #3003, and a path that exists but is not a directory is #3007.
    // The sync member THROWS where the async one completes with an empty listing,
    // so neither may be derived from the other. An UNREADABLE directory is the one
    // odd shape that does NOT throw: opendir() fails and adl answers an empty
    // listing, sync and async alike -- which is what the body below already does.
    this.line('if (o->nativePath == NULL) as_throw(Error_new((char*)"Error #2037: Functions called in incorrect sequence, or earlier call was unsuccessful.", 2037));');
    this.line('if (!as_path_exists(o->nativePath)) as_throw(Error_new((char*)"Error #3003: File or directory does not exist.", 3003));');
    this.line('if (!as_path_is_dir(o->nativePath)) as_throw(Error_new((char*)"Error #3007: Not a directory.", 3007));');
    this.line('as_array* result = as_array_new();');
    this.line('#ifdef _WIN32');
    this.line('// MSVC has no dirent.h; enumerate with FindFirstFile/FindNextFile, which');
    this.line('// want a backslash separator (FindFirstFile rejects the \'/\' as_path_join');
    this.line('// produces), so build a "<dir>\\*" pattern and swap separators as we copy.');
    this.line('{');
    this.indent++;
    this.line('size_t n = strlen(o->nativePath);');
    this.line('char* pat = (char*)malloc(n + 3);');
    this.line('size_t i;');
    this.line('memcpy(pat, o->nativePath, n);');
    this.line('for (i = 0; i < n; i++) if (pat[i] == \'/\') pat[i] = \'\\\\\';');
    this.line('pat[n] = \'\\\\\'; pat[n + 1] = \'*\'; pat[n + 2] = \'\\0\';');
    this.line('WIN32_FIND_DATAA fd;');
    this.line('HANDLE h = FindFirstFileA(pat, &fd);');
    this.line('free(pat);');
    this.line('if (h == INVALID_HANDLE_VALUE) return result;');
    this.line('do {');
    this.indent++;
    this.line('if (strcmp(fd.cFileName, ".") == 0 || strcmp(fd.cFileName, "..") == 0) continue;');
    this.line('as_array_push(result, as_v_obj((void*)File_new(as_path_join(o->nativePath, fd.cFileName))));');
    this.indent--;
    this.line('} while (FindNextFileA(h, &fd) != 0);');
    this.line('FindClose(h);');
    this.indent--;
    this.line('}');
    this.line('#else');
    this.line('DIR* d = opendir(o->nativePath);');
    this.line('if (d == NULL) return result;');
    this.line('struct dirent* e;');
    this.line('while ((e = readdir(d)) != NULL) {');
    this.indent++;
    this.line('if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0) continue;');
    this.line('as_array_push(result, as_v_obj((void*)File_new(as_path_join(o->nativePath, e->d_name))));');
    this.indent--;
    this.line('}');
    this.line('closedir(d);');
    this.line('#endif');
    this.line('return result;');
    this.indent--;
    this.line('}');
    this.line('');
    // FileStream: a FILE* handle + open/close/read/write. AIR FileMode strings are
    // mapped to C fopen modes.
    this.line('void FileStream_ctor(FileStream* o) { EventDispatcher_ctor((EventDispatcher*)o, NULL); o->_handle = NULL; }');
    this.line('FileStream* FileStream_new(void) { FileStream* o = (FileStream*)gc_alloc(GCT_CLASS, sizeof(FileStream)); o->vtable = &FileStream_vt; FileStream_ctor(o); return o; }');
    this.line('void FileStream_open(void* _this, File* file, char* fileMode) {');
    this.indent++;
    this.line('FileStream* o = (FileStream*)_this;');
    this.line('if (o->_handle != NULL) { fclose((FILE*)o->_handle); o->_handle = NULL; }');
    this.line('if (file == NULL || file->nativePath == NULL) return;');
    this.line('const char* mode = "rb";');
    this.line('if (fileMode != NULL) {');
    this.indent++;
    this.line('if (strcmp(fileMode, "write") == 0) mode = "wb";');
    this.line('else if (strcmp(fileMode, "append") == 0) mode = "ab";');
    this.line('else if (strcmp(fileMode, "update") == 0) mode = "r+b";');
    this.indent--;
    this.line('}');
    this.line('o->_handle = (void*)fopen(file->nativePath, mode);');
    // Unbuffered writes: AIR's FileStream makes each writeUTFBytes observable in
    // the file right away (the adl-vs-AOT probes read the log while the app is
    // still running), while stdio would hold the bytes in a 4 KB buffer until
    // fclose. Measured: an adl probe writing a log in /tmp is readable mid-run;
    // the same source under as-aot left a 0-byte file until exit.
    this.line('if (o->_handle != NULL) setvbuf((FILE*)o->_handle, NULL, _IONBF, 0);');
    this.indent--;
    this.line('}');
    // Completion thunk for openAsync, run on the AS3 thread inside a frame
    // boundary: adopt the opened handle, then report the byte count via a
    // ProgressEvent.PROGRESS followed by Event.COMPLETE (AIR reads the file into
    // an input buffer asynchronously and fires both before the data is consumed).
    // The handle is published here and not in openAsync(), so a read attempted
    // before COMPLETE sees no bytes available - which is what AIR's unbuffered
    // stream does too.
    this.line('static void FileStream__openFinish(void* job) {');
    this.indent++;
    this.line('FileStream* o = (FileStream*)as_job_obj(job);');
    this.line('if (as_job_failed(job)) { EventDispatcher_dispatchEvent((void*)o, (Event*)IOErrorEvent_new((char*)"ioError", false, false, (char*)"FileStream open failed")); return; }');
    this.line('unsigned total = as_job_total(job);');
    this.line('o->_handle = as_job_take_handle(job);');
    this.line('EventDispatcher_dispatchEvent((void*)o, (Event*)ProgressEvent_new((char*)"progress", false, false, total, total));');
    this.line('EventDispatcher_dispatchEvent((void*)o, (Event*)Event_new((char*)"complete", false, false));');
    this.indent--;
    this.line('}');
    this.line('void FileStream_openAsync(void* _this, File* file, char* fileMode) {');
    this.indent++;
    this.line('FileStream* o = (FileStream*)_this;');
    // AIR closes an already-open file before opening the new one, and delivers no
    // further events for it.
    this.line('if (o->_handle != NULL) { fclose((FILE*)o->_handle); o->_handle = NULL; }');
    this.line('as_async_submit(AS_JOB_FS_OPEN, (void*)o, FileStream__openFinish, (file != NULL) ? file->nativePath : NULL, fileMode, 0);');
    this.indent--;
    this.line('}');
    this.line('void FileStream_close(void* _this) { FileStream* o = (FileStream*)_this; if (o->_handle != NULL) { fclose((FILE*)o->_handle); o->_handle = NULL; } }');
    this.line('char* FileStream_readUTFBytes(void* _this, unsigned length) {');
    this.indent++;
    this.line('FileStream* o = (FileStream*)_this;');
    this.line('FILE* f = (FILE*)o->_handle;');
    this.line('if (f == NULL) return NULL;');
    this.line('char* buf = as_str_alloc((size_t)length + 1);');
    this.line('size_t n = fread(buf, 1, (size_t)length, f);');
    this.line('buf[n] = \'\\0\';');
    this.line('return buf;');
    this.indent--;
    this.line('}');
    this.line('void FileStream_writeUTFBytes(void* _this, char* value) {');
    this.indent++;
    this.line('FileStream* o = (FileStream*)_this;');
    this.line('FILE* f = (FILE*)o->_handle;');
    this.line('if (f != NULL && value != NULL) fwrite(value, 1, strlen(value), f);');
    this.indent--;
    this.line('}');
    this.line('unsigned FileStream_get_position(void* _this) { FileStream* o = (FileStream*)_this; FILE* f = (FILE*)o->_handle; return (f == NULL) ? 0u : (unsigned)ftell(f); }');
    this.line('unsigned FileStream_get_bytesAvailable(void* _this) {');
    this.indent++;
    this.line('FileStream* o = (FileStream*)_this;');
    this.line('FILE* f = (FILE*)o->_handle;');
    this.line('if (f == NULL) return 0u;');
    this.line('long cur = ftell(f);');
    this.line('fseek(f, 0, SEEK_END);');
    this.line('long end = ftell(f);');
    this.line('fseek(f, cur, SEEK_SET);');
    this.line('return (unsigned)(end - cur);');
    this.indent--;
    this.line('}');
    this.line('void FileStream_readBytes(void* _this, ByteArray* bytes, unsigned offset, unsigned length) {');
    this.indent++;
    this.line('FileStream* o = (FileStream*)_this;');
    this.line('FILE* f = (FILE*)o->_handle;');
    this.line('if (f == NULL || bytes == NULL) return;');
    this.line('if (length == 0) {');
    this.indent++;
    this.line('long cur = ftell(f); fseek(f, 0, SEEK_END); long end = ftell(f); fseek(f, cur, SEEK_SET);');
    this.line('length = (unsigned)(end - cur);');
    this.indent--;
    this.line('}');
    this.line('as_ba_grow(bytes, (int)(offset + length));');
    this.line('size_t n = fread((unsigned char*)bytes->data + offset, 1, (size_t)length, f);');
    this.line('if ((int)(offset + n) > bytes->length) bytes->length = (int)(offset + n);');
    this.indent--;
    this.line('}');
    this.line('void FileStream_writeBytes(void* _this, ByteArray* bytes, unsigned offset, unsigned length) {');
    this.indent++;
    this.line('FileStream* o = (FileStream*)_this;');
    this.line('FILE* f = (FILE*)o->_handle;');
    this.line('if (f == NULL || bytes == NULL) return;');
    this.line('if (length == 0) length = (unsigned)(bytes->length - (int)offset);');
    this.line('if ((int)(offset + length) > bytes->length) length = (unsigned)(bytes->length - (int)offset);');
    this.line('if (length > 0) fwrite((unsigned char*)bytes->data + offset, 1, (size_t)length, f);');
    this.indent--;
    this.line('}');
    this.line('');
    // ---- flash.net.SharedObject (stage 89·40) ----
    // Local shared objects, persisted in AIR's own container so the two runtimes
    // can read each other's stores (阶段一百五十):
    //   <storage>/#SharedObjects/[<content path>/][<localPath>/]<encoded name>.sol
    // The bytes are exactly AIR's -- see as_so_read_entries for the layout -- and
    // the AMF3 payload reuses the ByteArray codec, so a repeated string becomes a
    // reference just as adl writes it. Only the local half is implemented --
    // getRemote/connect/send need a Flash Media Server, so they throw instead of
    // silently doing nothing.
    this.line('static unsigned int ASC_so_default_encoding = 3u;');
    this.line('static bool ASC_so_prevent_backup = false;');
    // mkdir -p for the parent directory of a storage file. A shared-object name
    // may itself contain slashes (AIR example: getLocal("work/addresses")) and a
    // localPath value REPLACES the <content> layer -- both therefore contribute
    // intermediate directories, and a name's first component carries the "#"
    // prefix that as_so_file_name writes.
    this.line('static void as_so_mkparent(const char* p) {');
    this.indent++;
    this.line('if (p == NULL) return;');
    this.line('const char* slash = NULL;');
    this.line('for (const char* s = p; *s != \'\\0\'; s++) if (*s == \'/\') slash = s;');
    this.line('if (slash == NULL || slash == p) return;');
    this.line('size_t n = (size_t)(slash - p);');
    this.line('char* dir = as_alloc(n + 1);');
    this.line('memcpy(dir, p, n); dir[n] = \'\\0\';');
    this.line('as_mkdirs(dir);');
    this.indent--;
    this.line('}');
    // ---- how AIR derives the storage path (adl 51.4.1 measured; temp/sotor So5..SoD) ----
    //
    //     <storage>/#SharedObjects/[<layer>/][#]<name>.sol
    //
    // <layer> is the descriptor's <content> path, and a non-null localPath REPLACES
    // that whole layer -- it is NOT appended to it. Measured with
    // <content>=assets/So6.swf: localPath "/" writes straight into #SharedObjects/,
    // "/assets" and "/assets/" into #SharedObjects/assets/, and "/assets/So6.swf"
    // into the content directory itself. A localPath that is not a component-prefix
    // of <content> raises Error #2134, and so does the EMPTY STRING -- which is
    // therefore NOT the same as null (SoD p7 throws, p8 with "/" does not). A bare
    // build has no <content> to compare against, so any layer is taken verbatim,
    // keeping <storage>/#SharedObjects/<localPath>/<name>.sol.
    //
    // The name is a relative path in its own right: "work/addresses" (AIR's own
    // documented example) creates a subdirectory, and the FIRST component of such a
    // name is written with a "#" prefix -- measured "x/y" -> "#x/y.sol", "x/y/z" ->
    // "#x/y/z.sol", "a/b/c" -> "#a/b/c.sol" -- while a single-component name is
    // written verbatim. ONE leading "/" and one leading "./" are dropped before
    // that ("/x" -> "x.sol", "./x" -> "x.sol"), and "." / ".." components are left
    // to the filesystem ("." -> "..sol", ".." -> "...sol", "trail/" ->
    // "#trail/.sol"). A name that resolves outside the layer ("../x") or that holds
    // an empty inner component ("x//y", "//x") raises Error #2134 too.
    //
    // The characters AIR rejects raise Error #2134 from getLocal, not from flush
    // (SoA: e.name == "Error", e.message == "Error #2134: Cannot create
    // SharedObject."): every C0 control (TAB/LF/CR included) plus " # & ' , : ; <
    // > ? \ ~. This is the MEASURED set, not the documented one -- "%" and 0x7F are
    // accepted. "*" and "|" pass getLocal and only fail at flush with Error #2130
    // (they are illegal in a Windows file name; macOS takes them), so they are
    // deliberately not rejected here.
    //
    // NOT reproduced: AIR hex-escapes a non-ASCII name ("has中wen" is stored as
    // "hasE#4B#8A#Dwen.sol"), and once the absolute path reaches the OS limit it
    // rewrites the file as "##<16 hex>/<8 digits>.sol" (verbatim at 255 characters,
    // rewritten at 263). An earlier revision folded the name into 31-byte
    // components; that rule is not reproducible on adl either, and with it in place
    // the AOT build and AIR kept *different* files for one shared object -- the D11
    // symptom this layer exists to remove. All three residuals are reported in
    // docs/zh-cn/flash-net.md.
    this.line('static void as_so_reject(void) { as_throw(Error_new((char*)"Error #2134: Cannot create SharedObject.", 2134)); }');
    this.line('static bool as_so_name_bad(int c) {');
    this.indent++;
    this.line('if (c <= 0x20) return true;  // space plus every C0 control, TAB/LF/CR included');
    this.line('return c != 0 && strchr("\\"#&\',:;<>?\\\\~", c) != NULL;');
    this.indent--;
    this.line('}');
    // A name has to survive as a file name; the shape checks below are the part
    // that also keeps a name-derived path inside the layer.
    this.line('static void as_so_check_name(const char* name) {');
    this.indent++;
    this.line('if (name[0] == \'\\0\') as_so_reject();  // an empty name is #2134, not #2007');
    this.line('for (const char* s = name; *s != \'\\0\'; s++) if (as_so_name_bad((unsigned char)*s)) as_so_reject();');
    this.line('const char* n = name;');
    this.line('if (n[0] == \'/\') n++;');
    this.line('if (n[0] == \'.\' && n[1] == \'/\') n += 2;');
    this.line('for (const char* c = n; ; ) {');
    this.indent++;
    this.line('const char* e = strchr(c, \'/\');');
    this.line('if (e == NULL) break;  // the last component may be empty ("trail/")');
    this.line('if (e == c) as_so_reject();  // empty component');
    this.line('if (c == n && e == c + 2 && c[0] == \'.\' && c[1] == \'.\') as_so_reject();  // escapes the layer');
    this.line('c = e + 1;');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('static char* as_so_layer(const char* localPath) {');
    this.indent++;
    this.line('if (localPath == NULL) return (char*)ASC_SWF_PATH;');
    this.line('if (localPath[0] == \'\\0\') as_so_reject();  // "" is not null (SoD p7)');
    this.line('const char* s = localPath;');
    this.line('if (s[0] == \'/\') s++;');
    this.line('size_t len = strlen(s);');
    this.line('if (len > 0 && s[len - 1] == \'/\') len--;');
    this.line('const char* c = ASC_SWF_PATH;');
    this.line('for (size_t i = 0; i < len; ) {');
    this.indent++;
    this.line('size_t j = i;');
    this.line('while (j < len && s[j] != \'/\') j++;');
    this.line('if (j == i) as_so_reject();  // empty component ("//x", "x//y")');
    this.line('if (ASC_SWF_PATH[0] != \'\\0\') {');
    this.indent++;
    this.line('size_t k = 0;');
    this.line('while (k < j - i && c[k] != \'\\0\' && c[k] != \'/\') k++;');
    this.line('if (k != j - i || memcmp(s + i, c, k) != 0) as_so_reject();  // not a prefix of <content>');
    this.line('c += (c[k] == \'/\') ? k + 1 : k;');
    this.indent--;
    this.line('}');
    this.line('i = j + 1;');
    this.indent--;
    this.line('}');
    this.line('char* out = as_alloc(len + 1);');
    this.line('memcpy(out, s, len);');
    this.line('out[len] = \'\\0\';');
    this.line('return out;');
    this.indent--;
    this.line('}');
    this.line('static char* as_so_file_name(const char* name) {');
    this.indent++;
    this.line('const char* n = name;');
    this.line('if (n[0] == \'/\') n++;');
    this.line('if (n[0] == \'.\' && n[1] == \'/\') n += 2;');
    this.line('if (strchr(n, \'/\') != NULL) return as_str_concat(as_str_concat((char*)"#", (char*)n), (char*)".sol");');
    this.line('return as_str_concat((char*)n, (char*)".sol");');
    this.indent--;
    this.line('}');
    this.line('static char* as_so_path(const char* name, const char* localPath) {');
    this.indent++;
    this.line('char* base = as_app_storage_dir();');
    this.line('base = as_path_join(base, "#SharedObjects");');
    this.line('char* layer = as_so_layer(localPath);');
    this.line('if (layer[0] != \'\\0\') base = as_path_join(base, layer);');
    this.line('return as_path_join(base, as_so_file_name(name == NULL ? (char*)"" : name));');
    this.indent--;
    this.line('}');
    // Whole-file read into arena memory (NULL when the file does not exist). The
    // ".sol" payload carries NUL bytes, so the byte count matters and a
    // NUL-terminated string is not enough.
    this.line('static unsigned char* as_so_load_bytes(const char* p, size_t* out_len) {');
    this.indent++;
    this.line('*out_len = 0;');
    this.line('FILE* f = fopen(p, "rb");');
    this.line('if (f == NULL) return NULL;');
    this.line('size_t cap = 4096, len = 0, n = 0;');
    this.line('unsigned char* buf = (unsigned char*)as_alloc(cap);');
    this.line('while ((n = fread(buf + len, 1, cap - len, f)) > 0) {');
    this.indent++;
    this.line('len += n;');
    this.line('if (len == cap) { unsigned char* nb = (unsigned char*)as_alloc(cap * 2); memcpy(nb, buf, len); buf = nb; cap *= 2; }');
    this.indent--;
    this.line('}');
    this.line('fclose(f);');
    this.line('*out_len = len;');
    this.line('return buf;');
    this.indent--;
    this.line('}');
    // Read the entries of an AIR ".sol":
    //   00 BF | u32BE(fileSize - 6) | "TCSO" | u16 4 | u32 0 | u16 nameLen | name
    //   | 00 00 00 03 | ( U29S key | AMF3 value | 00 )*
    // The key field is a plain U29S (the type marker is omitted), so a key whose
    // text already entered the table comes back as a reference -- w6.sol's last
    // entry is key "zz" written as the reference 0x02 after "zz" appeared as a
    // value. ONE string/object table spans the whole file and it starts EMPTY (no
    // implicit "" slot: w2.sol's repeated value references index 1, not 2), which
    // is what as_amf3_rvalue already implements, so the helpers are reused as-is.
    this.line('static void as_so_read_entries(SharedObject* o, const unsigned char* buf, size_t len) {');
    this.indent++;
    this.line('if (len < 24 || buf[0] != 0x00 || buf[1] != 0xBF || memcmp(buf + 6, "TCSO", 4) != 0) return;');
    this.line('unsigned nameLen = (unsigned)((buf[16] << 8) | buf[17]);');
    this.line('size_t pos = 18 + (size_t)nameLen + 4;');
    this.line('if (pos >= len) return;');
    this.line('as_amf3r r;');
    this.line('memset(&r, 0, sizeof(r));');
    this.line('r.p = buf;');
    this.line('r.len = len;');
    this.line('r.pos = pos;');
    this.line('while (r.pos < r.len && r.code == 0) {');
    this.indent++;
    this.line('char* key = as_amfr_str_body(&r);');
    this.line('if (r.code != 0) break;');
    this.line('as_value v = as_amf3_rvalue(&r);');
    this.line('as_dyn_set((void*)o->_data, key, v);');
    this.line('if (!as_amfr_have(&r, 1)) break;');
    this.line('r.pos += 1;  // per-entry 0x00 terminator');
    this.indent--;
    this.line('}');
    this.line('for (int i = 0; i < r.ntr; i++) free(r.traits[i].members);');
    this.line('free(r.traits); free(r.strs); free(r.objs);');
    this.indent--;
    this.line('}');
    this.line('void SharedObject_ctor(SharedObject* o) {');
    this.indent++;
    this.line('EventDispatcher_ctor((EventDispatcher*)o, NULL);');
    this.line('o->name = NULL;');
    this.line('o->path = NULL;');
    this.line('o->_data = as_object_new();');
    // AIR invokes callback methods on `client`; the default is the shared object
    // itself (adl-verified: so.client == so).
    this.line('o->_client = (void*)o;');
    this.line('o->_objectEncoding = ASC_so_default_encoding;');
    this.line('o->_fps = 0.0;');
    this.indent--;
    this.line('}');
    this.line('SharedObject* SharedObject_new(void) { SharedObject* o = (SharedObject*)gc_alloc(GCT_CLASS, sizeof(SharedObject)); o->vtable = &SharedObject_vt; SharedObject_ctor(o); return o; }');
    // Build an instance for a storage path, loading the persisted table when the
    // file exists. A file whose header is not AIR's is ignored, leaving the table
    // empty, the way a corrupt store reads as blank rather than crashing.
    this.line('static SharedObject* as_so_make(char* name, char* path) {');
    this.indent++;
    this.line('SharedObject* o = (SharedObject*)gc_alloc(GCT_CLASS, sizeof(SharedObject));');
    this.line('o->vtable = &SharedObject_vt;');
    this.line('SharedObject_ctor(o);');
    this.line('o->name = name; gc_write_barrier((void*)name);');
    this.line('o->path = path; gc_write_barrier((void*)path);');
    this.line('size_t len = 0;');
    this.line('unsigned char* buf = as_so_load_bytes(path, &len);');
    this.line('if (buf != NULL) as_so_read_entries(o, buf, len);');
    this.line('return o;');
    this.indent--;
    this.line('}');
    // Serialise the table in AIR's ".sol" shape (byte layout in as_so_read_entries).
    // ONE AMF3 writer spans every entry, so a repeated string becomes a reference
    // exactly like adl's writer. Returns a malloc'd buffer the caller frees;
    // *out_len receives the byte count. AIR's format is fixed up front except for
    // the payload length, so the header is written with a placeholder and patched.
    this.line('static unsigned char* as_so_serialize(SharedObject* o, size_t* out_len) {');
    this.indent++;
    this.line('as_amf3w w;');
    this.line('memset(&w, 0, sizeof(w));');
    this.line('size_t nameLen = o->name == NULL ? 0 : strlen(o->name);');
    this.line('as_amfb_byte(&w.out, 0x00);');
    this.line('as_amfb_byte(&w.out, 0xBF);');
    this.line('as_amfb_bytes_be32(&w.out, 0);  // patched below: fileSize - 6');
    this.line('as_amfb_bytes(&w.out, (const unsigned char*)"TCSO", 4);');
    this.line('as_amfb_byte(&w.out, 0x00);');
    this.line('as_amfb_byte(&w.out, 0x04);');
    this.line('as_amfb_bytes_be32(&w.out, 0);');
    this.line('as_amfb_byte(&w.out, (unsigned)((nameLen >> 8) & 0xFFu));');
    this.line('as_amfb_byte(&w.out, (unsigned)(nameLen & 0xFFu));');
    this.line('if (nameLen > 0) as_amfb_bytes(&w.out, (const unsigned char*)o->name, nameLen);');
    this.line('as_amfb_byte(&w.out, 0x00);');
    this.line('as_amfb_byte(&w.out, 0x00);');
    this.line('as_amfb_byte(&w.out, 0x00);');
    this.line('as_amfb_byte(&w.out, 0x03);');
    this.line('for (int i = 0; i < o->_data->length; i++) {');
    this.indent++;
    this.line('char* key = o->_data->keys[i];');
    this.line('as_amf3_wstr_body(&w, key);  // U29S; a repeated key text becomes a reference');
    this.line('as_amf3_wvalue(&w, o->_data->vals[i]);');
    this.line('as_amfb_byte(&w.out, 0x00);');
    this.indent--;
    this.line('}');
    this.line('unsigned payload = (unsigned)(w.out.len - 6);');
    this.line('w.out.b[2] = (unsigned char)((payload >> 24) & 0xFFu);');
    this.line('w.out.b[3] = (unsigned char)((payload >> 16) & 0xFFu);');
    this.line('w.out.b[4] = (unsigned char)((payload >> 8) & 0xFFu);');
    this.line('w.out.b[5] = (unsigned char)(payload & 0xFFu);');
    this.line('free(w.strs); free(w.objs); free(w.traits);');
    this.line('*out_len = w.out.len;');
    this.line('return w.out.b;');
    this.indent--;
    this.line('}');
    // flush-all for the exit hook: AIR writes every local shared object when the
    // application closes, so data set without an explicit flush() still persists
    // (adl-verified: a .sol appears after the app exits even when flush() was
    // never called). An object with an empty table is skipped, so clear() keeps
    // its observable effect of removing the backing file.
    this.line('static int as_so_flush(SharedObject* o);');
    this.line('static void as_so_flush_all(void) {');
    this.indent++;
    this.line('if (SharedObject__cache == NULL) return;');
    this.line('for (int i = 0; i < SharedObject__cache->length; i++) {');
    this.indent++;
    this.line('SharedObject* c = (SharedObject*)as_v_obj_val(SharedObject__cache->data[i]);');
    this.line('if (c == NULL || c->path == NULL || c->_data == NULL || c->_data->length == 0) continue;');
    this.line('as_so_flush(c);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    // getLocal: one instance per resolved path per process (AIR returns the same
    // reference for the same name — adl-verified), so two handles to one name
    // cannot diverge. The cache is a declared static field, hence a GC root.
    this.line('SharedObject* SharedObject_getLocal_static(char* name, char* localPath, bool secure) {');
    this.indent++;
    this.line('(void)secure;  // this subset has no encrypted local store');
    this.line('if (name == NULL) { as_throw(Error_new((char*)"Error #2007: Parameter name must be non-null.", 2007)); return NULL; }');
    // The name/localPath checks run BEFORE the cache lookup, so a rejected call throws
    // exactly where adl throws it (adl throws from getLocal, not from flush -- SoA).
    this.line('as_so_check_name(name);  // #2134: empty name, a rejected character, an escaping shape');
    this.line('char* path = as_so_path(name, localPath);');
    this.line('if (SharedObject__cache == NULL) { SharedObject__cache = as_array_new(); atexit(as_so_flush_all); }');
    this.line('for (int i = 0; i < SharedObject__cache->length; i++) {');
    this.indent++;
    this.line('SharedObject* c = (SharedObject*)as_v_obj_val(SharedObject__cache->data[i]);');
    this.line('if (c != NULL && c->path != NULL && strcmp(c->path, path) == 0) return c;');
    this.indent--;
    this.line('}');
    this.line('SharedObject* so = as_so_make(name, path);');
    this.line('as_array_push(SharedObject__cache, as_v_obj((void*)so));');
    this.line('return so;');
    this.indent--;
    this.line('}');
    this.line('Object* SharedObject_get_data(void* _this) { SharedObject* o = (SharedObject*)_this; return (Object*)o->_data; }');
    // size: the byte count of the persisted representation, i.e. the size of the
    // ".sol" file flush() writes. Measured against adl 51.4.1 on temp/sotest: 266
    // for that store's eight properties, byte-for-byte the file this writes, and 0
    // while the table is still empty (adl reports the projected size even before
    // the first flush, so this measures the current table instead of stat()ing the
    // file).
    this.line('unsigned int SharedObject_get_size(void* _this) {');
    this.indent++;
    this.line('SharedObject* o = (SharedObject*)_this;');
    this.line('if (o->_data->length == 0) return 0;');
    this.line('size_t len = 0;');
    this.line('unsigned char* buf = as_so_serialize(o, &len);');
    this.line('free(buf);');
    this.line('return (unsigned int)len;');
    this.indent--;
    this.line('}');
    this.line('Object* SharedObject_get_client(void* _this) { return (Object*)((SharedObject*)_this)->_client; }');
    this.line('void SharedObject_set_client(void* _this, Object* value) { SharedObject* o = (SharedObject*)_this; o->_client = (void*)value; gc_write_barrier((void*)value); }');
    this.line('unsigned int SharedObject_get_objectEncoding(void* _this) { return ((SharedObject*)_this)->_objectEncoding; }');
    this.line('void SharedObject_set_objectEncoding(void* _this, unsigned int value) { ((SharedObject*)_this)->_objectEncoding = value; }');
    // fps only throttles how often changes are uploaded to a server; a local
    // object has no server, so the value is stored and otherwise unused.
    this.line('void SharedObject_set_fps(void* _this, double value) { ((SharedObject*)_this)->_fps = value; }');
    this.line('unsigned int SharedObject_get_defaultObjectEncoding_static(void* _this) { (void)_this; return ASC_so_default_encoding; }');
    this.line('void SharedObject_set_defaultObjectEncoding_static(void* _this, unsigned int value) { (void)_this; ASC_so_default_encoding = value; }');
    this.line('bool SharedObject_get_preventBackup_static(void* _this) { (void)_this; return ASC_so_prevent_backup; }');
    this.line('void SharedObject_set_preventBackup_static(void* _this, bool value) { (void)_this; ASC_so_prevent_backup = value; }');
    // flush: synchronously write the table and report the AIR status string.
    // AIR can return "pending" when the request is queued; a local write either
    // succeeds or fails, and a failed write is reported as a thrown Error rather
    // than a silent "pending".
    this.line('static int as_so_flush(SharedObject* o) {');
    this.indent++;
    this.line('if (o->path == NULL) return 1;');
    this.line('as_so_mkparent(o->path);');
    this.line('size_t len = 0;');
    this.line('unsigned char* buf = as_so_serialize(o, &len);');
    this.line('FILE* f = fopen(o->path, "wb");');
    this.line('if (f == NULL) { free(buf); return 0; }');
    this.line('if (len > 0) fwrite(buf, 1, len, f);');
    this.line('fclose(f);');
    this.line('free(buf);');
    this.line('return 1;');
    this.indent--;
    this.line('}');
    this.line('char* SharedObject_flush(void* _this, int minDiskSpace) {');
    this.indent++;
    this.line('(void)minDiskSpace;');
    this.line('if (!as_so_flush((SharedObject*)_this)) { as_throw(Error_new((char*)"SharedObject.flush: cannot write the storage file", 0)); return (char*)"pending"; }');
    this.line('return (char*)"flushed";');
    this.indent--;
    this.line('}');
    // clear: purge the table and delete the backing file (AIR does both), while
    // leaving the object usable — a later flush recreates the file.
    this.line('void SharedObject_clear(void* _this) {');
    this.indent++;
    this.line('SharedObject* o = (SharedObject*)_this;');
    this.line('o->_data = as_object_new();');
    this.line('gc_write_barrier((void*)o->_data);');
    this.line('if (o->path != NULL) remove(o->path);');
    this.indent--;
    this.line('}');
    // close: AIR documents it as affecting remote objects only (adl-verified: a
    // local object keeps its data, its file and stays usable), so this is a no-op.
    this.line('void SharedObject_close(void* _this) { (void)_this; }');
    // setDirty exists so the server can be told which property changed; a local
    // object tracks dirtiness itself and flush() writes the whole table.
    this.line('void SharedObject_setDirty(void* _this, char* propertyName) { (void)_this; (void)propertyName; }');
    this.line('void SharedObject_setProperty(void* _this, char* propertyName, as_value value) {');
    this.indent++;
    this.line('SharedObject* o = (SharedObject*)_this;');
    this.line('if (propertyName == NULL) return;');
    this.line('as_object_set(o->_data, propertyName, value);');
    this.indent--;
    this.line('}');
    // Remote half: no Flash Media Server exists in this runtime, so these fail
    // loudly (a message the caller can act on) instead of pretending to work.
    this.line('SharedObject* SharedObject_getRemote_static(char* name, char* remotePath, as_value persistence, bool secure) {');
    this.indent++;
    this.line('(void)name; (void)remotePath; (void)persistence; (void)secure;');
    this.line('as_throw(Error_new((char*)"SharedObject.getRemote requires a Flash Media Server connection, which this AOT runtime does not provide (only local shared objects are supported)", 0));');
    this.line('return NULL;');
    this.indent--;
    this.line('}');
    this.line('void SharedObject_connect(void* _this, as_value myConnection, as_value params) { (void)_this; (void)myConnection; (void)params; as_throw(Error_new((char*)"SharedObject.connect requires a Flash Media Server connection, which this AOT runtime does not provide", 0)); }');
    this.line('void SharedObject_send(void* _this, as_array* arguments) { (void)_this; (void)arguments; as_throw(Error_new((char*)"SharedObject.send requires a Flash Media Server connection, which this AOT runtime does not provide", 0)); }');
    this.line('');
    // ---- display-object geometry: content bounds, local matrices, hit test ----
    //
    // Everything here derives from ONE notion of "content bounds in local space"
    // (as_bounds_walk): AIR's width/height, getRect-style geometry and the mouse
    // hit test are all built on it. Measured on adl 51.4.1 (temp/c1probe/):
    //   * a 10px stroke widens the shape by the full thickness (100-long line ->
    //     110 wide, 10 tall) while getRect keeps the bare path (0,0,100,0);
    //   * children count toward a container's bounds, transformed by each child's
    //     own matrix, INVISIBLE ones included, and so does a Sprite's own graphics;
    //   * an object with no content has empty bounds (width/height 0).
    this.line('static int as_graphics_bound(DisplayObject* o, double* l, double* t, double* r, double* b);');
    this.line('static Graphics* as_graphics_of(DisplayObject* o);');
    this.line('static int as_graphics_empty(Graphics* g);');
    this.line('static void as_graphics_paint(void* canvas, Graphics* g);');
    // SWC baked display trees: the exported classes' ctors call this, and it is
    // defined at the end of the translation unit (swc.md §9 E-3).
    this.line('void as_swc_bind(DisplayObject* o, int charId);');
    // Baked SWC timelines (item ③): the exported classes' ctors call this to adopt
    // their symbol's frame count + FrameLabels, so the prototype must exist before
    // the class bodies (the definition follows with the other bake helpers).
    this.line('static void as_swc_tl_start(MovieClip* o, int charId);');
    // `decl`: report a BAKED shape's own box as its SWF ShapeBounds — which is what AIR
    // reports AND what AIR clips the rasterisation to — instead of the decoded paths'
    // extent. Measured (temp/childfx): shape #212 declares 396.45x22.75 and adl reports
    // exactly that while our path extent is 374.7x1; #214 declares 361.6x17.6 and #210
    // 360x16, both matching adl too. Hit testing passes 0: AIR picks by the painted
    // region, not by the declared box.
    this.line('static int as_bounds_walk(DisplayObject* o, int with_stroke, int decl, double* l, double* t, double* r, double* b);');
    this.line('static void as_do_point(DisplayObject* o, double* x, double* y);');
    this.line('static void as_do_matrix(DisplayObject* o, double* a, double* b, double* c, double* d, double* tx, double* ty);');
    this.line('static void as_mat_mul(double a1, double b1, double c1, double d1, double tx1, double ty1, double a2, double b2, double c2, double d2, double tx2, double ty2, double* a, double* b, double* c, double* d, double* tx, double* ty);');
    this.line('static int as_mat_invert(double a, double b, double c, double d, double tx, double ty, double* ra, double* rb, double* rc, double* rd, double* rtx, double* rty);');
    this.line('static int as_local_point(DisplayObject* o, double gx, double gy, double* lx, double* ly);');
    this.line('static void as_to_stage_matrix(DisplayObject* o, double* a, double* b, double* c, double* d, double* tx, double* ty);');
    this.line('static void as_rect_xform(double* l, double* t, double* r, double* b, double ma, double mb, double mc, double md, double mtx, double mty);');
    this.line('static void as_rect_to_stage(DisplayObject* o, double* l, double* t, double* r, double* b);');
    this.line('static void as_rect_from_stage(DisplayObject* o, double* l, double* t, double* r, double* b);');
    this.line('static bool as_obj_hit_local(DisplayObject* o, double lx, double ly);');
    // A SimpleButton's hit region comes from its hit STATE, so the region test must
    // delegate to the button helper. That helper lives next to the state machine
    // (below, with the paint path), hence this forward declaration.
    this.line('static int as_sbtn_contains_local(SimpleButton* b, double lx, double ly);');
    this.line('static bool as_obj_region_hit_local(DisplayObject* o, double lx, double ly, int pick);');
    this.line('static bool as_pick_hit_local(DisplayObject* o, double lx, double ly);');
    this.line('static void* as_pick_hit_m(void* obj, double x, double y, double a, double b, double c, double d, double tx, double ty);');
    // The object's own local transform (translate * rotate * scale * userMatrix),
    // spelled exactly like as_render_object and as_bounds_xform compose it, so the
    // hit test can never disagree with what is on screen.
    this.line('static void as_do_point(DisplayObject* o, double* x, double* y) {');
    this.indent++;
    this.line('Matrix* m = (o->transform != NULL) ? o->transform->matrix : NULL;');
    this.line('double a = 1.0, b = 0.0, c = 0.0, d = 1.0, tx = 0.0, ty = 0.0;');
    this.line('if (m != NULL) { a = m->a; b = m->b; c = m->c; d = m->d; tx = m->tx; ty = m->ty; }');
    this.line('double mx = a * (*x) + c * (*y) + tx;');
    this.line('double my = b * (*x) + d * (*y) + ty;');
    this.line('mx *= o->scaleX; my *= o->scaleY;');
    this.line('double rad = o->rotation * 3.14159265358979323846 / 180.0;');
    this.line('double cs = cos(rad), sn = sin(rad);');
    this.line('double rx = mx * cs - my * sn, ry = mx * sn + my * cs;');
    this.line('*x = rx + o->x; *y = ry + o->y;');
    this.indent--;
    this.line('}');
    // Recover the affine matrix from the transform itself (three basis points)
    // instead of re-deriving the algebra: whatever as_do_point does IS the matrix.
    this.line('static void as_do_matrix(DisplayObject* o, double* a, double* b, double* c, double* d, double* tx, double* ty) {');
    this.indent++;
    this.line('double x0 = 0.0, y0 = 0.0, x1 = 1.0, y1 = 0.0, x2 = 0.0, y2 = 1.0;');
    this.line('as_do_point(o, &x0, &y0); as_do_point(o, &x1, &y1); as_do_point(o, &x2, &y2);');
    this.line('*a = x1 - x0; *b = y1 - y0; *c = x2 - x0; *d = y2 - y0; *tx = x0; *ty = y0;');
    this.indent--;
    this.line('}');
    // parent-then-local composition (x' = a*x + c*y + tx convention).
    this.line('static void as_mat_mul(double a1, double b1, double c1, double d1, double tx1, double ty1, double a2, double b2, double c2, double d2, double tx2, double ty2, double* a, double* b, double* c, double* d, double* tx, double* ty) {');
    this.indent++;
    this.line('*a = a1 * a2 + c1 * b2; *b = b1 * a2 + d1 * b2;');
    this.line('*c = a1 * c2 + c1 * d2; *d = b1 * c2 + d1 * d2;');
    this.line('*tx = a1 * tx2 + c1 * ty2 + tx1; *ty = b1 * tx2 + d1 * ty2 + ty1;');
    this.indent--;
    this.line('}');
    this.line('static int as_mat_invert(double a, double b, double c, double d, double tx, double ty, double* ra, double* rb, double* rc, double* rd, double* rtx, double* rty) {');
    this.indent++;
    this.line('double det = a * d - b * c;');
    this.line('if (det > -1e-12 && det < 1e-12) return 0;');
    this.line('double ia = d / det, ib = -b / det, ic = -c / det, id = a / det;');
    this.line('*ra = ia; *rb = ib; *rc = ic; *rd = id;');
    this.line('*rtx = -(ia * tx + ic * ty); *rty = -(ib * tx + id * ty);');
    this.line('return 1;');
    this.indent--;
    this.line('}');
    // The object's LOCAL->STAGE matrix (its own transform composed with every
    // ancestor). Factored out of as_local_point so the FORWARD direction is also
    // available to localToGlobal / getBounds / getRect. The temporaries matter:
    // as_mat_mul writes its outputs in order, so passing the same variables as
    // inputs and outputs (`as_mat_mul(..., a,b,c,d,tx,ty, &a,&b,...)`) makes `b`
    // read the already-overwritten `a` whenever an ancestor has a rotation/skew
    // (b1/c1 non-zero). That bug was invisible only because a top-level object's
    // parent is the identity Stage, which leaves testb..testc at 0.
    this.line('static void as_to_stage_matrix(DisplayObject* o, double* a, double* b, double* c, double* d, double* tx, double* ty) {');
    this.indent++;
    this.line('as_do_matrix(o, a, b, c, d, tx, ty);');
    this.line('DisplayObject* p = (DisplayObject*)o->parent;');
    this.line('while (p != NULL) {');
    this.indent++;
    this.line('double pa, pb, pc, pd, ptx, pty;');
    this.line('as_do_matrix(p, &pa, &pb, &pc, &pd, &ptx, &pty);');
    this.line('double na, nb, nc, nd, ntx, nty;');
    this.line('as_mat_mul(pa, pb, pc, pd, ptx, pty, *a, *b, *c, *d, *tx, *ty, &na, &nb, &nc, &nd, &ntx, &nty);');
    this.line('*a = na; *b = nb; *c = nc; *d = nd; *tx = ntx; *ty = nty;');
    this.line('p = (DisplayObject*)p->parent;');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    // Walk up the parent chain (AIR's globalToLocal applied to a stage point).
    this.line('static int as_local_point(DisplayObject* o, double gx, double gy, double* lx, double* ly) {');
    this.indent++;
    this.line('double a, b, c, d, tx, ty;');
    this.line('as_to_stage_matrix(o, &a, &b, &c, &d, &tx, &ty);');
    this.line('double ia, ib, ic, id, itx, ity;');
    this.line('if (!as_mat_invert(a, b, c, d, tx, ty, &ia, &ib, &ic, &id, &itx, &ity)) return 0;');
    this.line('*lx = ia * gx + ic * gy + itx; *ly = ib * gx + id * gy + ity;');
    this.line('return 1;');
    this.indent--;
    this.line('}');
    // Bounds-only hit test in the object's own space: the content extent of the
    // object and its descendants. The box INCLUDES the stroke: adl answers
    // hitTestPoint(x,y,false) at a point 4px outside a 20x20 fill that carries an
    // 8px stroke, i.e. the bounds are the painted extent, not getRect's geometry
    // (measured, temp/editprobe/Ed24 §1: hits from x=5.75 for a fill spanning
    // 10..30 with a stroke reaching 6). A stroke-free box also made stroke-only
    // Shapes unpickable, which AIR never does.
    this.line('static bool as_obj_hit_local(DisplayObject* o, double lx, double ly) {');
    this.indent++;
    this.line('double l, t, r, b;');
    this.line('if (!as_bounds_walk(o, 1, 0, &l, &t, &r, &b)) return false;');
    this.line('return lx >= l && lx <= r && ly >= t && ly <= b;');
    this.indent--;
    this.line('}');
    // The MOUSE PICK region: what the pointer may TARGET on this object.
    //
    // For a button it is the HIT state (see below). For everything else it is the
    // object's PAINTED CONTENT -- the region hitTestPoint(x, y, true) reports -- and
    // NOT the bounding box that its descendants span.
    //
    // Why the box is wrong here: as_obj_hit_local unions every descendant, so a
    // container that paints nothing of its own answers "hit" for EVERY point inside
    // its children's union, gaps between them included. AIR does not: a Sprite with
    // no graphics is not a mouse target anywhere (that is why every Flash "catch the
    // clicks over this panel" idiom draws a transparent fill first) and the gap
    // between two shapes of one Sprite is a miss. This is not merely a wrong target
    // REPORT: the box-hitting container is usually an empty layer added for later
    // popups, i.e. it sits ON TOP of the app's real widgets and swallows their
    // clicks. Measured on the TalkMED meeting client (ASC_MOUSE_TRACE=2,
    // temp/applog): every point of the document/video pane's box -- the bottom
    // toolbar and the header buttons included -- picked
    // com.vsdevelop.proxy::ViewControl, an empty popup layer, while the buttons
    // beneath it were never reached.
    //
    // Why a button differs: AIR hit-tests a button through its HIT state, which is
    // the very same predicate that decides hover (as_sbtn_contains_local). A
    // "down-only" SWC button (a down record + a hit record, no up) is an INVISIBLE
    // click target -- upState is NULL, so as_bounds_walk finds no box at all and the
    // button could never be clicked. That is exactly the shape of 29 characters /
    // 73 placements in the real app's skin.swc: the TalkMED personal-centre rows and
    // the 选择企业 back arrow -- all dead to the mouse, while the Sprite-shaped
    // buttons beside them (submitbtn/agreebtn) worked, which is what pointed here.
    // NOTE hitTestPoint(x, y, false) keeps the bounding-box path (as_obj_hit_local):
    // a bounding box is what that flag asks for, so the two paths must not be merged.
    this.line('static bool as_pick_hit_local(DisplayObject* o, double lx, double ly) {');
    this.indent++;
    this.line('if (as_is((void*)o, &SimpleButton_vt)) return as_sbtn_contains_local((SimpleButton*)o, lx, ly) != 0;');
    this.line('return as_obj_region_hit_local(o, lx, ly, 1);');
    this.indent--;
    this.line('}');
    // ---- shape-flag hit test (stage 94·22) ----
    // AIR's hitTestPoint(x, y, true) asks for the CONTENT REGION, not the box:
    // a point in the empty gap between two children of a Sprite is a miss while
    // both children hit, and a stroke-only line hits along its painted band.
    // Measured on adl 51.4.1 (temp/editprobe/Ed24): the region is
    //   * a Graphics fill (even-odd, homogeneous with what is painted) UNION the
    //     stroked band of the same path (round caps/joints, width/2 each side);
    //   * a Bitmap's rect -- NOT its pixel alpha. A fully transparent BitmapData
    //     still hits inside its quad, and a transparent pixel inside a quad hits
    //     too (Ed21 §A/§B, Ed22 §A, Ed23 §A). shapeFlag is not a pixel test here.
    //   * a TextField's rect: shapeFlag is ignored for text fields (Ed18 §7/§8).
    //   * for containers, the union over children, each in its own local space.
    // Both flags ignore `visible`, `mouseEnabled`, `mouseChildren` and the object
    // alpha (Ed24 §2/§3/§4), so nothing here gates on them.
    this.line('static bool as_shape_region_hit(DisplayObject* o, double lx, double ly) {');
    this.indent++;
    this.line('Graphics* g = as_graphics_of(o);');
    this.line('if (g == NULL || !g->_has_b) return false;');
    this.line('if (g->path == NULL) {');
    this.indent++;
    this.line('// Pure-C build: the geometry is not retained, so answer with the');
    this.line('// stroke-inclusive drawn extent (see as_obj_hit_local).');
    this.line('double half = g->_max_sw * 0.5;');
    this.line('return lx >= g->_bl - half && lx <= g->_br + half && ly >= g->_bt - half && ly <= g->_bb + half;');
    this.indent--;
    this.line('}');
    // Every group is its own filled/stroked path, so containment must be tested
    // per group: after a flush the current group no longer holds earlier geometry.
    this.line('for (as_gdraw* d = (as_gdraw*)g->draws; d != NULL; d = d->next) {');
    this.indent++;
    this.line('if (d->fill != NULL && as_skia_path_contains(d->path, lx, ly)) return true;');
    this.line('if (d->stroke != NULL && d->stroke_width > 0.0 && as_skia_path_stroke_contains(d->path, d->stroke_width, lx, ly)) return true;');
    this.indent--;
    this.line('}');
    this.line('if (g->fill != NULL && as_skia_path_contains(g->path, lx, ly)) return true;');
    this.line('if (g->stroke != NULL && g->strokeWidth > 0.0 && as_skia_path_stroke_contains(g->path, g->strokeWidth, lx, ly)) return true;');
    this.line('return false;');
    this.indent--;
    this.line('}');
    this.line('static bool as_obj_region_hit_local(DisplayObject* o, double lx, double ly, int pick) {');
    this.indent++;
    // `pick` selects the mouse-pick flavour of the same region: an invisible subtree
    // is not a target (AIR never dispatches into one), and a SimpleButton contributes
    // its HIT state instead of nothing. hitTestPoint(shapeFlag=true) passes 0 and keeps
    // the measured behaviour -- it ignores `visible` and, for a button, answers false
    // (Ed24 §2..§4).
    this.line('if (pick && !o->visible) return false;');
    // A SimpleButton draws its STATES but owns no shape of its own (the four states
    // are separate DisplayObjects, per the SimpleButton docs). So its shapeFlag=true
    // region is EMPTY: adl answers false for hitTestPoint(x, y, true) on a button
    // even when its hitTestState is a filled 60x60 square AND the button is on the
    // display list (temp/sbtnstate2, seven probes). The hitTestState is the *input*
    // hit area only -- that is what as_sbtn_contains uses for hover; it is not a
    // shape region, so it must NOT leak into hitTestPoint here.
    this.line('if (as_is((void*)o, &SimpleButton_vt)) return pick ? as_sbtn_contains_local((SimpleButton*)o, lx, ly) != 0 : false;');
    this.line('if (as_shape_region_hit(o, lx, ly)) return true;');
    this.line('if (as_is((void*)o, &Bitmap_vt) || as_is((void*)o, &TextField_vt)) {');
    this.indent++;
    this.line('// Their own extent IS the region (no pixel sampling, no child loop).');
    this.line('double l, t, r, b;');
    this.line('if (!as_bounds_walk(o, 0, 0, &l, &t, &r, &b)) return false;');
    this.line('return lx >= l && lx <= r && ly >= t && ly <= b;');
    this.indent--;
    this.line('}');
    this.line('if (as_is((void*)o, &DisplayObjectContainer_vt)) {');
    this.indent++;
    this.line('DisplayObjectContainer* cc = (DisplayObjectContainer*)o;');
    this.line('if (cc->children != NULL) {');
    this.indent++;
    this.line('for (int i = 0; i < cc->children->length; i++) {');
    this.indent++;
    this.line('DisplayObject* ch = (DisplayObject*)as_v_obj_val(cc->children->data[i]);');
    this.line('if (ch == NULL) continue;');
    this.line('double ca, cb, ccn, cd, ctx, cty;');
    this.line('as_do_matrix(ch, &ca, &cb, &ccn, &cd, &ctx, &cty);');
    this.line('double ia, ib, ic, id, itx, ity;');
    this.line('if (!as_mat_invert(ca, cb, ccn, cd, ctx, cty, &ia, &ib, &ic, &id, &itx, &ity)) continue;');
    this.line('double clx = ia * lx + ic * ly + itx, cly = ib * lx + id * ly + ity;');
    this.line('if (as_obj_region_hit_local(ch, clx, cly, pick)) return true;');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('return false;');
    this.indent--;
    this.line('}');
    // Inside-out hit test (Ruffle interactive.rs Avm2MousePick). mouseChildren=true
    // means children are tested first (reverse depth = topmost first) and a hit
    // propagates to the deepest child; mouseChildren=false makes this parent
    // absorb the hit (its own content bounds decide). mouseEnabled=false means the
    // object itself never reports a hit.
    //
    // Stage 94·5: the point is CARRIED IN STAGE SPACE and each step converts it
    // into the local space of the node it tests. Before this, the same absolute
    // x/y was handed to every descendant, so only objects whose x/y happened to be
    // stage-absolute could ever be hit (a child of an offset container was dead).
    this.line('static void* as_pick_hit_m(void* obj, double x, double y, double a, double b, double c, double d, double tx, double ty) {');
    this.indent++;
    this.line('DisplayObject* o = (DisplayObject*)obj;');
    this.line('if (o == NULL || !o->visible) return NULL;');
    this.line('if (o->_mask_object) return NULL; // a mask object is not a hit target either');
    this.line('double ia, ib, ic, id, itx, ity;');
    this.line('if (!as_mat_invert(a, b, c, d, tx, ty, &ia, &ib, &ic, &id, &itx, &ity)) return NULL;');
    this.line('double lx = ia * x + ic * y + itx, ly = ib * x + id * y + ity;');
    // DisplayObject.scrollRect splits the test in two, exactly as the renderer does:
    // a point outside the WINDOW is outside the clipped subtree (nothing there is on
    // screen, so nothing there can be hit), while the children are tested in the
    // content space the -x/-y shift produces -- folded into the matrix handed to
    // each child, so the whole subtree stays consistent. The window is the object's
    // own box (local 0,0,w,h), not the rectangle's own x/y slot: adl keeps the
    // window anchored to the box and only slides the content (see the renderer note
    // and temp/scrollrect-probe), so testing the read-back rect instead left the
    // top `scrollY` points of a scrolled list unclickable.
    this.line('double oa = a, ob = b, oc = c, od = d, otx = tx, oty = ty;');
    this.line('if (o->_scroll_rect != NULL) {');
    this.indent++;
    this.line('Rectangle* sr = o->_scroll_rect;');
    this.line('if (lx < 0 || ly < 0 || lx > sr->width || ly > sr->height) return NULL;');
    this.line('otx -= oa * sr->x + oc * sr->y;');
    this.line('oty -= ob * sr->x + od * sr->y;');
    this.indent--;
    this.line('}');
    this.line('if (as_is(obj, &DisplayObjectContainer_vt)) {');
    this.indent++;
    this.line('DisplayObjectContainer* cc = (DisplayObjectContainer*)obj;');
    this.line('if (((InteractiveObject*)obj)->mouseChildren && cc->children != NULL) {');
    this.indent++;
    this.line('for (int i = cc->children->length - 1; i >= 0; i--) {');
    this.indent++;
    this.line('DisplayObject* ch = (DisplayObject*)as_v_obj_val(cc->children->data[i]);');
    this.line('if (ch == NULL) continue;');
    this.line('double ca, cb, ccn, cd, ctx, cty;');
    this.line('as_do_matrix(ch, &ca, &cb, &ccn, &cd, &ctx, &cty);');
    this.line('double ga, gb, gc, gd, gtx, gty;');
    this.line('as_mat_mul(oa, ob, oc, od, otx, oty, ca, cb, ccn, cd, ctx, cty, &ga, &gb, &gc, &gd, &gtx, &gty);');
    this.line('void* res = as_pick_hit_m(ch, x, y, ga, gb, gc, gd, gtx, gty);');
    this.line('if (res != NULL) return res;');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('if (as_is(obj, &InteractiveObject_vt)) {');
    this.indent++;
    this.line('if (as_pick_hit_local(o, lx, ly) && ((InteractiveObject*)obj)->mouseEnabled) return obj;');
    this.indent--;
    this.line('}');
    this.line('return NULL;');
    this.indent--;
    this.line('}');
    this.line('static void* as_pick_hit(void* obj, double x, double y) {');
    this.indent++;
    this.line('DisplayObject* o = (DisplayObject*)obj;');
    this.line('if (o == NULL) return NULL;');
    this.line('double a, b, c, d, tx, ty;');
    this.line('as_do_matrix(o, &a, &b, &c, &d, &tx, &ty);');
    this.line('return as_pick_hit_m(obj, x, y, a, b, c, d, tx, ty);');
    this.indent--;
    this.line('}');
    // Stage-space bounds test (Sprite.hitTestPoint): the argument is in stage
    // coordinates in AIR, so map it back through the ancestor chain first.
    this.line('static bool as_obj_region_hit(void* obj, double x, double y) {');
    this.indent++;
    this.line('DisplayObject* o = (DisplayObject*)obj;');
    this.line('if (o == NULL) return false;');
    this.line('double lx = 0.0, ly = 0.0;');
    this.line('if (!as_local_point(o, x, y, &lx, &ly)) return false;');
    this.line('return as_obj_region_hit_local(o, lx, ly, 0);');
    this.indent--;
    this.line('}');
    this.line('static bool as_obj_hit(void* obj, double x, double y) {');
    this.indent++;
    this.line('DisplayObject* o = (DisplayObject*)obj;');
    this.line('double lx, ly;');
    this.line('if (!as_local_point(o, x, y, &lx, &ly)) return false;');
    this.line('return as_obj_hit_local(o, lx, ly);');
    this.indent--;
    this.line('}');
    // ---- stage 94·9: getBounds/getRect/localToGlobal/globalToLocal/hitTestObject ----
    // Map a rect through a raw affine matrix, then re-take the AABB: AIR reports
    // axis-aligned boxes in the target space, so a rotated object's box grows.
    this.line('static void as_rect_xform(double* l, double* t, double* r, double* b, double ma, double mb, double mc, double md, double mtx, double mty) {');
    this.indent++;
    this.line('double x0 = *l, y0 = *t, x1 = *r, y1 = *b;');
    this.line('double px0 = ma * x0 + mc * y0 + mtx, py0 = mb * x0 + md * y0 + mty;');
    this.line('double px1 = ma * x1 + mc * y0 + mtx, py1 = mb * x1 + md * y0 + mty;');
    this.line('double px2 = ma * x0 + mc * y1 + mtx, py2 = mb * x0 + md * y1 + mty;');
    this.line('double px3 = ma * x1 + mc * y1 + mtx, py3 = mb * x1 + md * y1 + mty;');
    this.line('double lo_x = px0 < px1 ? px0 : px1; if (px2 < lo_x) lo_x = px2; if (px3 < lo_x) lo_x = px3;');
    this.line('double hi_x = px0 > px1 ? px0 : px1; if (px2 > hi_x) hi_x = px2; if (px3 > hi_x) hi_x = px3;');
    this.line('double lo_y = py0 < py1 ? py0 : py1; if (py2 < lo_y) lo_y = py2; if (py3 < lo_y) lo_y = py3;');
    this.line('double hi_y = py0 > py1 ? py0 : py1; if (py2 > hi_y) hi_y = py2; if (py3 > hi_y) hi_y = py3;');
    this.line('*l = lo_x; *t = lo_y; *r = hi_x; *b = hi_y;');
    this.indent--;
    this.line('}');
    this.line('static void as_rect_to_stage(DisplayObject* o, double* l, double* t, double* r, double* b) {');
    this.indent++;
    this.line('double a, bb, c, d, tx, ty;');
    this.line('as_to_stage_matrix(o, &a, &bb, &c, &d, &tx, &ty);');
    this.line('as_rect_xform(l, t, r, b, a, bb, c, d, tx, ty);');
    this.indent--;
    this.line('}');
    this.line('static void as_rect_from_stage(DisplayObject* o, double* l, double* t, double* r, double* b) {');
    this.indent++;
    this.line('double a, bb, c, d, tx, ty;');
    this.line('as_to_stage_matrix(o, &a, &bb, &c, &d, &tx, &ty);');
    this.line('double ia, ib, ic, id, itx, ity;');
    this.line('if (!as_mat_invert(a, bb, c, d, tx, ty, &ia, &ib, &ic, &id, &itx, &ity)) return;');
    this.line('as_rect_xform(l, t, r, b, ia, ib, ic, id, itx, ity);');
    this.indent--;
    this.line('}');
    // getBounds/getRect(targetCoordinateSpace): content bounds (with / without the
    // stroke) reported in TARGET's coordinate space; a null target means the
    // object's own local space (measured on adl: getRect(null) == getRect(self)),
    // and target == self is short-circuited so a rotated object's local box is
    // exact (adl: rot.getRect(rot) == 0,0,100,20 — a matrix round-trip would
    // leave ~1e-15 of cos(90°) noise).
    this.line('Rectangle* DisplayObject_getBounds(void* _this, DisplayObject* target) {');
    this.indent++;
    this.line('DisplayObject* o = (DisplayObject*)_this;');
    this.line('double l, t, r, b;');
    this.line('if (!as_bounds_walk(o, 1, 1, &l, &t, &r, &b)) return Rectangle_new(0.0, 0.0, 0.0, 0.0);');
    this.line('if (target != NULL && target != o) { as_rect_to_stage(o, &l, &t, &r, &b); as_rect_from_stage(target, &l, &t, &r, &b); }');
    this.line('return Rectangle_new(l, t, r - l, b - t);');
    this.indent--;
    this.line('}');
    this.line('Rectangle* DisplayObject_getRect(void* _this, DisplayObject* target) {');
    this.indent++;
    this.line('DisplayObject* o = (DisplayObject*)_this;');
    this.line('double l, t, r, b;');
    // `getRect` keeps the stroke-EXCLUSIVE box (with_stroke 0 ⇒ decl 0): AIR's
    // declared ShapeBounds folds the stroke in, and only the display-oriented
    // getters (width/height/getBounds) report that stroke-inclusive box.
    this.line('if (!as_bounds_walk(o, 0, 0, &l, &t, &r, &b)) return Rectangle_new(0.0, 0.0, 0.0, 0.0);');
    this.line('if (target != NULL && target != o) { as_rect_to_stage(o, &l, &t, &r, &b); as_rect_from_stage(target, &l, &t, &r, &b); }');
    this.line('return Rectangle_new(l, t, r - l, b - t);');
    this.indent--;
    this.line('}');
    // localToGlobal/globalToLocal: a fresh Point each call (never mutates the
    // argument); a null point throws TypeError #2007 (measured on adl). On a
    // singular matrix globalToLocal is not invertible: adl still returns a Point,
    // so fall back to the input unchanged rather than a null dereference.
    this.line('Point* DisplayObject_localToGlobal(void* _this, Point* point) {');
    this.indent++;
    this.line('if (point == NULL) { as_throw(TypeError_new((char*)"Error #2007: Parameter point must be non-null.", 2007)); return NULL; }');
    this.line('DisplayObject* o = (DisplayObject*)_this;');
    this.line('double a, b, c, d, tx, ty;');
    this.line('as_to_stage_matrix(o, &a, &b, &c, &d, &tx, &ty);');
    this.line('return Point_new(a * point->x + c * point->y + tx, b * point->x + d * point->y + ty);');
    this.indent--;
    this.line('}');
    this.line('Point* DisplayObject_globalToLocal(void* _this, Point* point) {');
    this.indent++;
    this.line('if (point == NULL) { as_throw(TypeError_new((char*)"Error #2007: Parameter point must be non-null.", 2007)); return NULL; }');
    this.line('DisplayObject* o = (DisplayObject*)_this;');
    this.line('double lx, ly;');
    this.line('if (!as_local_point(o, point->x, point->y, &lx, &ly)) return Point_new(point->x, point->y);');
    this.line('return Point_new(lx, ly);');
    this.indent--;
    this.line('}');
    // hitTestObject: intersection of the two STAGE-space bounding boxes, stroke
    // INCLUSIVE (getBounds-like). Measured on adl: two shapes whose bare paths are
    // disjoint but whose 20px strokes touch still report true; an empty object
    // never intersects (not even itself).
    this.line('bool DisplayObject_hitTestObject(void* _this, DisplayObject* obj) {');
    this.indent++;
    this.line('DisplayObject* o = (DisplayObject*)_this;');
    this.line('if (o == NULL || obj == NULL) return false;');
    this.line('double l1, t1, r1, b1, l2, t2, r2, b2;');
    this.line('if (!as_bounds_walk(o, 1, 1, &l1, &t1, &r1, &b1)) return false;');
    this.line('if (!as_bounds_walk(obj, 1, 1, &l2, &t2, &r2, &b2)) return false;');
    this.line('as_rect_to_stage(o, &l1, &t1, &r1, &b1);');
    this.line('as_rect_to_stage(obj, &l2, &t2, &r2, &b2);');
    this.line('return l1 <= r2 && l2 <= r1 && t1 <= b2 && t2 <= b1;');
    this.indent--;
    this.line('}');
    // hitTestPoint(x, y, shapeFlag): the point is in STAGE space. AIR's owner is
    // DisplayObject (so Shape gets it too, which is why this moved off Sprite).
    // shapeFlag=false asks "is the point inside the drawn extent" (stroke-inclusive
    // bounds); shapeFlag=true asks "is the point inside the drawn region" — fill,
    // stroked band, bitmap/text-field rect and any child region (stage 94·22).
    this.line('bool DisplayObject_hitTestPoint(void* _this, double x, double y, bool shapeFlag) {');
    this.indent++;
    this.line('if (shapeFlag) return as_obj_region_hit(_this, x, y);');
    this.line('return as_obj_hit(_this, x, y);');
    this.indent--;
    this.line('}');
    // Stage.dispatchMouse(x, y, type): non-standard test hook that hit-tests the
    // tree and dispatches a bubbling MouseEvent from the deepest target, so
    // capture/target/bubble runs against the ancestor chain.
    // It also drives TextField text selection: mouseDown on a selectable field
    // starts a drag (caret placed at the hit index), mouseMove extends the
    // selection, mouseUp ends it. The drag state is declared just below.
    this.line('static int as_tf_index_at(TextField* tf, double x, double y);');
    // Drag bookkeeping lives at FILE scope so the "wordSelect" bridge in
    // ASC_window_on_mouse can clear it: a double click that lands inside an
    // existing selection first takes the inside-selection path below (anchor -2),
    // which would otherwise collapse the freshly selected word at mouseUp.
    // Neither variable is a GC root — they only live between mouseDown and
    // mouseUp, where no GC safe point runs.
    // Live pointer state in STAGE coordinates, fed by Stage_dispatchMouse. It has
    // to live outside the event dispatch because a SimpleButton decides which of
    // its four states to show at PAINT time (as_sbtn_state), not while an event is
    // being handled.
    //
    // The coordinates live on the Stage OBJECT (`_mouse_x/_mouse_y/_mouse_has`), not
    // in process-wide statics: AIR keeps one pointer per Stage (each NativeWindow
    // owns its own Stage), and process-wide statics made every window's paint pass
    // read whichever window received the last mouse event -- window A hovered and
    // reported mouseX/mouseY for a pointer that was only ever over window B. Measured
    // before the fix (temp/mouse2w, two windows, one process): driving a mouseMove
    // into window B turned window A's SimpleButton to its over state and made
    // A.mouseX/mouseY equal B's client coordinates. `_mouse_has` is per stage and
    // false until that stage's first mouse event, so a stage nobody pointed at (and
    // any object off the display list) keeps the up state.
    //
    // ASC_mouse_down stays a process-wide static on purpose: there is ONE OS pointer
    // and one button state, and a press that began in one window must be cleared by a
    // release in another -- that is AIR's latched-press behaviour.
    //
    // MEASURED AIR CONTRACT for leaving a window (adl 51.4.1, two windows, real
    // pointer, temp/mouse2w sched.cjs adl arm): the moment the pointer crosses into
    // the OTHER window the left window's button ROLLS BACK TO ITS UP STATE while its
    // mouseX/mouseY KEEP the last in-window coordinates (measured: state up -> over ->
    // up, coordinates frozen at 179.9,203.6 instead of zeroing, never following the
    // other window's pointer), and the events adl dispatches at that instant are, in
    // order, mouseOut -> rollOut (on the button) -> "mouseLeave" (on the STAGE).
    // That is why the hover gate is a separate `_mouse_in` slot: clearing it rolls the
    // hover back without touching the coordinates. The per-object mouseOut/rollOut
    // pair is still missing (it needs the hovered object OF THIS STAGE, which the
    // emitter does not track -- TODO.md's rollOver/rollOut residual); the Stage's
    // "mouseLeave" is dispatched (see Stage_dispatchMouse).
    //
    // The pointer position is recorded before dispatching, and a leave clears only the
    // "is inside" flag.
    this.line('static int ASC_mouse_down = 0;');
    // The Stage an object belongs to, WITHOUT DisplayObject_get_stage's root fallback.
    // That fallback exists so the document class sees its own `stage` inside its
    // constructor; borrowing ANOTHER window's stage here is exactly the defect the
    // per-stage pointer state removes. NULL = the object is not on any stage.
    this.line('static Stage* as_mouse_owner_stage(DisplayObject* o) {');
    this.indent++;
    this.line('while (o != NULL && o->parent != NULL) o = (DisplayObject*)o->parent;');
    this.line('if (o != NULL && o->vtable != NULL && strcmp(o->vtable->cls_name, "Stage") == 0) return (Stage*)o;');
    this.line('return NULL;');
    this.indent--;
    this.line('}');
    // The InteractiveObject under the pointer (AIR's roll-over target), and the
    // press generation latched by the mouseDown that is still held. Both feed the
    // MovieClip button states (as_mc_button_state). ASC_mouse_target is only read
    // inside one paint pass -- it is refreshed there from THAT stage's own pointer
    // (as_mouse_refresh_target), so it never has to be a GC root, and reading it
    // during a pass can only ever see the coordinates the pass just refreshed. The
    // press is a generation NUMBER rather than a target pointer for the same reason:
    // 0 means "nothing pressed" and no object ever stores 0.
    this.line('static void* ASC_mouse_target = NULL;');
    this.line('static int ASC_press_gen = 0;');
    this.line('static TextField* drag_tf = NULL;');
    this.line('static int drag_anchor = -1;');
    // ---- Sprite.startDrag/stopDrag ----
    // AIR's drag follows the pointer until stopDrag() is called -- a mouseUp does NOT
    // end it (that is why the documented recipe calls stopDrag from a mouseUp
    // listener) -- so this state outlives the event and is a GC root (see
    // gc_mark_user_roots). The pointer is mapped into the dragged object's PARENT
    // space, since that is the space its x/y live in; `ASC_drag_off_*` is the
    // object-to-pointer offset captured at startDrag (AIR's lockCenter:false), and
    // lockCenter:true pins the object's registration point to the pointer instead.
    this.line('static void* ASC_drag_obj = NULL;');
    this.line('static int ASC_drag_lock = 0;');
    this.line('static Rectangle* ASC_drag_bounds = NULL;');
    this.line('static double ASC_drag_off_x = 0.0, ASC_drag_off_y = 0.0;');
    this.line('void Stage_dispatchMouse(void* _this, double x, double y, char* type) {');
    this.indent++;
    // Record the live pointer before dispatching: a SimpleButton picks which of its
    // four states to show at PAINT time (as_sbtn_state), so the state has to be
    // readable outside the event. Living on THIS stage means each window's pointer is
    // its own, and the AS3 test hook Stage.dispatchMouse(x, y, type) drives the states
    // of the stage it was called on (temp/btnstate).
    this.line('Stage* mst = (Stage*)_this;');
