    this.line('void Graphics_drawCircle(void* _this, double x, double y, double r) { Graphics* g = (Graphics*)_this; as_skia_path_add_circle(g->path, x, y, r); as_gpath_rect(g, x - r, y - r, 2.0 * r, 2.0 * r); as_gclosed(g, x - r, y); }');
