    this.line('return;');
    this.indent--;
    this.line('}');
    this.line('double ax = vertices->data[ia * 2], ay = vertices->data[ia * 2 + 1];');
    this.line('double bx = vertices->data[ib * 2], by = vertices->data[ib * 2 + 1];');
    this.line('double cx = vertices->data[ic * 2], cy = vertices->data[ic * 2 + 1];');
