    this.line('as_gclosed(g, cx, cy);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('void Graphics_clear(void* _this) {');
    this.indent++;
    this.line('Graphics* g = (Graphics*)_this;');
