    this.indent++;
    this.line('if (bd == NULL) return NULL;');
    this.line('if (bd->image != NULL && bd->_px_ver == 0) return bd->image;');
    this.line('return as_bmd_live_image(bd);');
    this.indent--;
    this.line('}');
    this.line('unsigned BitmapData_getPixel(void* _this, int x, int y) {');
    this.indent++;
