    this.line('if (bd->pixels == NULL || x < 0 || y < 0 || x >= bd->width || y >= bd->height) return 0u;');
    this.line('return ((unsigned*)bd->pixels)[y * bd->width + x] & 0xFFFFFFu;');
    this.indent--;
    this.line('}');
    this.line('void BitmapData_setPixel(void* _this, int x, int y, unsigned color) {');
    this.indent++;
