    this.line('{ static int n = 0; if (n++ % 120 == 0 && getenv("ASC_S3D_TRACE") != NULL) fprintf(stderr, "s3d_trace present: w=%d h=%d tex=%p lw=%d lh=%d\\n", w, h, ASC_stage3d_tex, ASC_stage3d_lw, ASC_stage3d_lh); }');
    this.indent--;
    this.line('}');
