    // Upload the index buffer (Vector.<uint> is uint32).
    this.line('if (indexBuffer != NULL && indexBuffer->data != NULL) as_s3d_upload_index(o->gpu, indexBuffer->data->data + indexBuffer->startIndex, indexBuffer->numIndices);');
