    this.line('return (char*)"Direct3D12 (Stage3D)";');
    this.line('#elif defined(ASC_RENDER_STAGE3D)');
    this.line('return (char*)"Metal (Stage3D)";');
    this.line('#else');
    this.line('return (char*)"Software (state machine)";');
    this.line('#endif');
    this.indent--;
    this.line('}');
