    // cacheAsBitmap container bakes at sx=1.0 while its canvas runs at 0.784, i.e. a
    // 0.784x nearest minification of a photograph -- and because the bake scale also
    // comes out as 1.089 in other states, the aliasing pattern flipped with every
    // rebuild, which is the "clear, then mushy, then clear again" the user sees.
    // When bx == sx the two samplers are identical, so the pixel-identity invariant
    // (uncached == cached, pinned by autobake-origin.as) is untouched.
    this.line('double bl_bx = 1.0, bl_by = 1.0; as_skia_canvas_total_scale(canvas, &bl_bx, &bl_by);');
    this.line('int bl_smooth = (fabs(bl_bx - sx) > 0.001 || fabs(bl_by - sy) > 0.001) ? 1 : 0;');
    this.line('as_skia_canvas_draw_image_rect(canvas, o->_cache_image, bxo, byo, (double)pw / sx, (double)ph / sy, bl_smooth);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('');
    this.emitNineSlice();
    this.line('static int as_ct_active(ColorTransform* ct) {');
    this.indent++;
    this.line('if (ct == NULL) return 0;');
    this.line('return !(ct->redMultiplier == 1.0 && ct->greenMultiplier == 1.0 && ct->blueMultiplier == 1.0 && ct->alphaMultiplier == 1.0 &&');
    this.line('         ct->redOffset == 0.0 && ct->greenOffset == 0.0 && ct->blueOffset == 0.0 && ct->alphaOffset == 0.0);');
    this.indent--;
    this.line('}');
    // A 4x5 SkColorMatrix in row-major order. AS3's ColorTransform is
    // `out = in*multiplier + offset` per channel with the offset in 0..255, while
    // Skia's translation column is in 0..1, so only the offsets are rescaled.
    this.line('static void as_ct_matrix(ColorTransform* ct, float* m) {');
    this.indent++;
    this.line('for (int i = 0; i < 20; i++) m[i] = 0.0f;');
    this.line('m[0] = (float)ct->redMultiplier; m[6] = (float)ct->greenMultiplier; m[12] = (float)ct->blueMultiplier; m[18] = (float)ct->alphaMultiplier;');
    this.line('m[4] = (float)(ct->redOffset / 255.0); m[9] = (float)(ct->greenOffset / 255.0);');
    this.line('m[14] = (float)(ct->blueOffset / 255.0); m[19] = (float)(ct->alphaOffset / 255.0);');
    this.indent--;
    this.line('}');
    this.line('static void as_render_object(void* canvas, DisplayObject* o) {');
    this.indent++;
    this.line('if (o == NULL || !o->visible) return;');
    // MovieClip button states settle BEFORE anything is measured or painted, so the
    // bounds, the nine-slice slice and the pixels all see the state the pointer
    // implies (as_mc_button_state is a no-op unless the clip is a buttonMode).
    this.line('if (as_is((void*)o, &MovieClip_vt)) as_mc_button_state(o);');
    // A clipDepth mask object is a child (AIR reports it) but is never painted: its
    // outline became the clip path of the siblings in its depth range. Skipping the
    // whole subtree is right for a sprite mask too — AIR renders it into the mask
    // buffer, never into the visible output.
    this.line('if (o->_mask_object) return;');
    // clipDepth mask (swc.md §9 E-4): the mask is a SIBLING, so its region lives in
    // the PARENT's pixel space and must NOT follow this object as it moves. The clip
    // therefore goes on BEFORE the object's own translate/rotate/scale, and the baked
    // path is the mask's placement in that same parent space (阶段一百四十六).
    // Composing it into the object's local pixels instead made the mask travel with
    // the object -- the TalkMED login ticker (banner x = -(index-1)*354 under a fixed
    // mask) showed only the first slide and blank afterwards.
    this.line('as_skia_canvas_save(canvas);');
    this.line('int clip_on = (o->_clip_path != NULL);');
    this.line('if (clip_on) as_skia_canvas_clip_path(canvas, o->_clip_path, 1);');
    this.line('if (o->alpha < 1.0) as_skia_canvas_save_layer_alpha(canvas, o->alpha);');
    this.line('int alpha_on = (o->alpha < 1.0);');
    this.line('as_skia_canvas_translate(canvas, o->x, o->y);');
    this.line('as_skia_canvas_rotate(canvas, o->rotation);');
    this.line('as_skia_canvas_scale(canvas, o->scaleX, o->scaleY);');
    // DisplayObject.transform.matrix: concat the user Matrix after the built-in
    // x/y/rotation/scale so both views of the same transform compose (AS3 applies
    // the concat matrix as an additional local transform).
    this.line('if (o->transform != NULL && o->transform->matrix != NULL) {');
    this.indent++;
    this.line('Matrix* m = o->transform->matrix;');
    this.line('as_skia_canvas_concat(canvas, m->a, m->b, m->c, m->d, m->tx, m->ty);');
    this.indent--;
    this.line('}');
    // transform.colorTransform (and every SWC placement CXFORM) tints the object
    // AND its children once, so it becomes an extra saveLayer carrying the colour
    // matrix. Applying it per paint instead would multiply alpha twice wherever a
    // sprite paints its own geometry as well as its children's (swc.md §9 E-3).
    // DisplayObject.blendMode (swc.md §9.2 F4): AIR composites the object into its
    // parent with the named operator, so the WHOLE object -- children, filters and
    // its own colour transform -- goes into one layer carrying that paint. The layer
    // is therefore the outermost wrapper here; the colour transform and clipDepth
    // mask below are part of what the object looks like, i.e. inside it.
    // "layer" is not an operator but pure group isolation, and the helper reports it
    // the same way (returns 1, plain SrcOver). normal/unknown => no layer at all.
    this.line('int blend_on = 0;');
    this.line('if (o->blendMode != NULL) { void* bp = as_skia_paint_fill(0x000000, 1.0); blend_on = as_skia_paint_set_blend(bp, o->blendMode); if (blend_on) as_skia_canvas_save_layer_paint(canvas, bp); as_skia_paint_delete(bp); }');
    this.line('ColorTransform* oct = (o->transform != NULL) ? o->transform->colorTransform : NULL;');
    this.line('int ct_on = as_ct_active(oct);');
    this.line('if (ct_on) {');
    this.indent++;
    this.line('float cm[20];');
    this.line('as_ct_matrix(oct, cm);');
    this.line('void* cp = as_skia_paint_new();');
    this.line('as_skia_paint_set_color_matrix(cp, cm);');
    this.line('as_skia_canvas_save_layer_paint(canvas, cp);');
    this.line('as_skia_paint_delete(cp);');
    this.indent--;
    this.line('}');
    // DisplayObject.scrollRect: the object is shown through a window of the
    // rectangle's SIZE that stays anchored on the object's own box (local
    // 0,0,w,h); only the CONTENT slides, by -x/-y -- that shift is what makes the
    // classic `mc.scrollRect = new Rectangle(0, y, w, h)` a scroll and what makes
    // the app's List (VScrollBar.scrollY) work.
    //
    // Clip FIRST, then shift. Skia maps a clipRect through the CTM in force at the
    // call, so clipping after the translate would put the window itself at
    // (r.x, r.y, w, h) -- i.e. drag it along with the content. Measured on adl
    // 51.4.1 (temp/scrollrect-probe: a stripe-painted box at (100,50) with
    // `scrollRect = (20,30,100,80)` reports its painted pixels at (100,50)-(199,129)
    // -- the box -- and the pixel at the window's top-left is object x=20, so the
    // window is the box and only the content moved; our old order reported
    // (80,20)-(179,99) and object x=0). The consequences in the app were bug D29:
    // scrolled list content painted over the fixed header, a blank band at the
    // bottom of the list, and a dead click zone at the top of the scrolled list
    // (the pick window in as_pick_hit_m mirrored the same wrong rect).
    this.line('int scroll_on = (o->_scroll_rect != NULL);');
    this.line('if (scroll_on) {');
    this.indent++;
    this.line('as_skia_canvas_save(canvas);');
    this.line('as_skia_canvas_clip_rect(canvas, 0.0, 0.0, o->_scroll_rect->width, o->_scroll_rect->height);');
    this.line('as_skia_canvas_translate(canvas, -o->_scroll_rect->x, -o->_scroll_rect->y);');
    this.indent--;
    this.line('}');

    // DisplayObject.opaqueBackground: AIR backs the object with an OPAQUE bitmap
    // (no alpha channel) whose background is this colour, so the colour shows
    // through wherever the content is transparent -- the app uses it for
    // alternating item/row backgrounds and for solid scrollbar surfaces. We paint
    // the colour as a filled rect over the object's tight local bounds BEFORE any
    // content, which is the same picture (and, like AIR's region, it is invisible
    // to hit testing and to mouse events -- as_pick_hit_m never consults it).
    // Only a Number is meaningful (AIR: "If set to a number value, the surface is
    // opaque"); null, and any non-numeric value, leaves the object transparent.
    this.line('if (as_v_is_number(o->opaqueBackground)) {');
    this.indent++;
    this.line('double opa_l = 0.0, opa_t = 0.0, opa_r = 0.0, opa_b = 0.0;');
    this.line('if (as_render_bounds(o, &opa_l, &opa_t, &opa_r, &opa_b) && opa_r > opa_l && opa_b > opa_t) {');
    this.indent++;
    this.line('void* opa_p = as_skia_paint_fill((unsigned)(long long)as_v_num_val(o->opaqueBackground), 1.0);');
    this.line('as_skia_canvas_draw_rect(canvas, opa_l, opa_t, opa_r - opa_l, opa_b - opa_t, opa_p);');
    this.line('as_skia_paint_delete(opa_p);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');

    // DefineScalingGrid (swc.md §9 F) comes FIRST: when a 9-sliced instance is
    // stretched, Flash reassembles it from a natural-size picture instead of
    // scaling the whole thing, so the border bands keep their own size. At scale 1
    // (or with no grid) it is a plain content paint, i.e. exactly the old path.
    this.line('if (o->_s9_apply && (o->scaleX != 1.0 || o->scaleY != 1.0)) {');
    this.indent++;
    this.line('as_render_nine_slice(canvas, o);');
    this.indent--;
    // A focused TextField must never render from the bake: its caret blinks (and a
    // composition preview moves) every frame, and the explicit cacheAsBitmap path
    // only re-bakes on size/flag change -- so it would freeze the caret. Render it
    // live instead (阶段一百三十五).
    this.line('} else if ((o->_cache_flag || o->_auto_baked) && !(as_is(o, &TextField_vt) && as_focus_obj == (void*)o)) {');
    this.indent++;
    this.line('as_render_cached(canvas, o);');
    this.indent--;
    this.line('} else if (o->filters != NULL && o->filters->length > 0) {');
    this.indent++;
    this.line('double bl, bt, br, bb;');
    this.line('if (as_render_bounds(o, &bl, &bt, &br, &bb)) {');
    this.indent++;
    this.line('as_filters_expand(o->filters, &bl, &bt, &br, &bb);');
    this.line('void* clip = as_skia_paint_fill(0x000000, 1.0);');
    this.line('as_skia_canvas_save_layer_paint_bounds(canvas, clip, bl, bt, br, bb);');
    this.line('as_skia_paint_delete(clip);');
    this.line('as_render_filtered(canvas, o, o->filters, o->filters->length - 1);');
    this.line('as_skia_canvas_restore(canvas);');
    this.indent--;
    this.line('} else {');
    this.indent++;
    this.line('as_render_filtered(canvas, o, o->filters, o->filters->length - 1);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('} else {');
    this.indent++;
    this.line('as_render_object_content(canvas, o);');
    this.indent--;
    this.line('}');
    this.line('if (scroll_on) as_skia_canvas_restore(canvas);');
    this.line('if (ct_on) as_skia_canvas_restore(canvas);');
    this.line('if (blend_on) as_skia_canvas_restore(canvas);');
    // saveLayerAlpha is a save like any other: without this restore the layer (and
    // the translate/rotate/scale applied after it) stayed in force for the REST of
    // the frame, so every sibling painted after a半透明 object inherited its
    // transform and its 50% alpha. In the real app a list row sets itself to
    // alpha 0.5 on MOUSE_DOWN and never gets the matching MOUSE_UP once a drag
    // starts (the scrollbar flips mouseChildren off), and every card below the
    // list was then painted shifted down by that row's position until the list
    // was rebuilt -- "拖动列表后点刷新，上面的按钮跳下来再恢复".
    this.line('if (alpha_on) as_skia_canvas_restore(canvas);');
    this.line('as_skia_canvas_restore(canvas);');
    this.indent--;
    this.line('}');
    this.line('');
    // AS3 applies filters in array order (filters[0] first = innermost), so the
    // outermost wrap is the LAST filter. We recurse from the last index down to 0
    // and draw the plain content once idx < 0. BlurFilter and DropShadowFilter
    // wrap the content in a single saveLayer; an outer GlowFilter draws a blurred
    // recolored silhouette layer first, then the unfiltered body on top so only
    // the fringe shows.
    //
    // AIR's filter blur is a BOX blur of diameter `blurX`, applied `quality` times
    // (not a Gaussian). Measured on adl with a black rect on white
    // (temp/filterprobe, values are the darkness left of the edge, sample pixel
    // spanning d..d+1 outside it):
    //   blur6  q1: d2 0.0824, d4 0.0000   (support ends at blurX/2 == 3)
    //   blur12 q1: d2 0.2917, d4 0.1216   (support ends at 6)
    //   blur6  q3: d2 0.2118, d4 0.0706, d6 0.0118 (3 stacked boxes, support 9)
    // A box of diameter b has variance b^2/12, so `quality` stacked boxes equal a
    // Gaussian of sigma = blurX*sqrt(quality)/sqrt(12) — matching AIR's own
    // pixel-averaged falloff to within a few percent (blur6 q1 at d2 gives 0.083
    // vs the measured 0.0824, and blur12's 0.29 vs 0.2917). The earlier blanket
    // sigma = blurX/3 (== blurX/3.0, i.e. blurX/5.2 in box-diameter terms) was
    // ~1.8x too wide at the fringe: it left a visible tail where AIR has none.
    this.line('static double as_filter_sigma(double blur, int quality) { double q = (quality < 1) ? 1.0 : (double)quality; return blur * sqrt(q) / 3.4641016151377544; }');
    this.line('static void as_render_filtered(void* canvas, DisplayObject* o, as_array* filters, int idx) {');
    this.indent++;
    this.line('if (idx < 0) { as_render_object_content(canvas, o); return; }');
    this.line('void* f = as_v_obj_val(filters->data[idx]);');
    this.line('if (as_is(f, &BlurFilter_vt)) {');
    this.indent++;
    this.line('BlurFilter* bf = (BlurFilter*)f;');
    this.line('void* p = as_skia_paint_fill(0x000000, 1.0);');
    this.line('as_skia_paint_set_blur(p, as_filter_sigma(bf->blurX, bf->quality), as_filter_sigma(bf->blurY, bf->quality));');
    this.line('as_skia_canvas_save_layer_paint(canvas, p);');
    this.line('as_skia_paint_delete(p);');
    this.line('as_render_filtered(canvas, o, filters, idx - 1);');
    this.line('as_skia_canvas_restore(canvas);');
    this.indent--;
    this.line('} else if (as_is(f, &DropShadowFilter_vt)) {');
    this.indent++;
    this.line('DropShadowFilter* ds = (DropShadowFilter*)f;');
    this.line('double rad = ds->angle * 3.14159265358979323846 / 180.0;');
    this.line('double ddx = ds->distance * cos(rad);');
    this.line('double ddy = ds->distance * sin(rad);');
    this.line('void* p = as_skia_paint_fill(0x000000, 1.0);');
    // `strength` decides how hard the imprint stamps (AS3 default 2, a baked SWC
    // glow 0.199). It was ignored entirely, which painted every baked halo at full
    // opacity. Skia's DropShadow already composites the source, so `drawSource`
    // tells the glue which regime it is in, and the source is only painted here
    // when the glue did NOT include it (see the glue's measured note).
    this.line('int drawSource = !ds->_shadow_only;');
    this.line('as_skia_paint_set_drop_shadow(p, ddx, ddy, as_filter_sigma(ds->blurX, ds->quality), as_filter_sigma(ds->blurY, ds->quality), ds->color, ds->alpha, ds->strength, drawSource);');
    this.line('as_skia_canvas_save_layer_paint(canvas, p);');
    this.line('as_skia_paint_delete(p);');
    this.line('as_render_filtered(canvas, o, filters, idx - 1);');
    this.line('as_skia_canvas_restore(canvas);');
    this.line('if (drawSource && ds->alpha * ds->strength > 1.0) as_render_filtered(canvas, o, filters, idx - 1);');
    this.indent--;
    this.line('} else if (as_is(f, &GlowFilter_vt)) {');
    this.indent++;
    this.line('GlowFilter* gf = (GlowFilter*)f;');
    this.line('void* p = as_skia_paint_fill(0x000000, 1.0);');
    // Same strength rule as the drop shadow above (see the note there).
    this.line('as_skia_paint_set_glow(p, as_filter_sigma(gf->blurX, gf->quality), as_filter_sigma(gf->blurY, gf->quality), gf->color, gf->alpha, gf->strength);');
    this.line('as_skia_canvas_save_layer_paint(canvas, p);');
    this.line('as_skia_paint_delete(p);');
    this.line('as_render_filtered(canvas, o, filters, idx - 1);');
    this.line('as_skia_canvas_restore(canvas);');
    // The halo layer carries only the recoloured silhouette, so the body is painted
    // here — unless `_shadow_only` says AIR's CompositeSource cleared it (swc.md
    // §9.2 F4), which is what a glow with the SWC CompositeSource bit = 0 means.
    this.line('if (!gf->_shadow_only) as_render_filtered(canvas, o, filters, idx - 1);');
    this.indent--;
    this.line('} else {');
    this.indent++;
    this.line('as_render_filtered(canvas, o, filters, idx - 1);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('');
    this.line('static void as_render_object_content(void* canvas, DisplayObject* o) {');
    this.indent++;
    this.line('if (as_is(o, &Shape_vt)) {');
    this.indent++;
    this.line('Graphics* g = ((Shape*)o)->graphics;');
    // A baked shape may carry a ShapeBounds clip (see the Graphics `_clip` field).
    this.line('if (g->_clip) { as_skia_canvas_save(canvas); as_skia_canvas_clip_rect(canvas, g->_clx, g->_cly, g->_clw, g->_clh); }');
    this.line('as_graphics_paint(canvas, g);');
    this.line('if (g->_clip) as_skia_canvas_restore(canvas);');
    this.indent--;
    this.line('} else if (as_is(o, &SimpleButton_vt)) {');
    this.indent++;
    // A baked SWC button holds four state DisplayObjects and no graphics of its own.
    // Without this branch a button character painted NOTHING (measured: `upvpage`,
    // `downvpage` and `img_control` rendered 0 non-transparent pixels while adl
    // filled 2400/2400/874).
    this.line('DisplayObject* st = as_sbtn_state(o);');
    this.line('if (st != NULL) as_render_object(canvas, st);');
    this.indent--;
    this.line('} else if (as_is(o, &Bitmap_vt)) {');
    this.indent++;
    this.line('BitmapData* bd = ((Bitmap*)o)->bitmapData;');
    // as_bmd_visible_image picks the decoded SkImage view or, for a bitmap built
    // from raw pixels, a cached view of `pixels` -- a `new BitmapData(...)` has no
    // decoded view at all, and requiring one here painted NOTHING: the real app's
    // ANEVideo camera preview (new BitmapData + setPixels per frame) stayed a
    // black rectangle while its FPS text kept counting.
    // Bitmap.smoothing decides the sampler: AIR defaults it to false (nearest,
    // hard pixel edges on an upscaled bitmap) and true is bilinear. The meeting
    // client's slide preview sets it true; ignoring it made a half-pixel scale
    // wobble flicker between a sharp and a mushy image every frame.
    this.line('void* bd_img = as_bmd_visible_image(bd);');
    this.line('if (bd_img != NULL) as_skia_canvas_draw_image_rect(canvas, bd_img, 0.0, 0.0, (double)bd->width, (double)bd->height, ((Bitmap*)o)->smoothing ? 1 : 0);');
    this.indent--;
    this.line('} else if (as_is(o, &TextField_vt)) {');
    this.indent++;
    this.line('TextField* tf = (TextField*)o;');
    this.line('if (tf->background) {');
    this.indent++;
    this.line('void* bg = as_skia_paint_fill(tf->backgroundColor, 1.0);');
    this.line('as_skia_canvas_draw_rect(canvas, 0.0, 0.0, tf->_fieldWidth, tf->_fieldHeight, bg);');
    this.line('as_skia_paint_delete(bg);');
    this.indent--;
    this.line('}');
    // Border: FOUR crisp 1px lines on the OUTER edge of the field box. Measured on
    // adl 51.4.1 by pixel-scanning a BitmapData.draw of a 100x30 field
    // (temp/editprobe/src/Ed6.as): the outline lands on x in {0,100} and y in
    // {0,30} -- one pixel OUTSIDE the 100x30 background fill -- at FULL opacity
    // with no antialiased bleed into x=1/y=1, and the colour's alpha byte is
    // ignored (borderColor 0x8000FF00 paints opaque green over white). So this is
    // four pixel-aligned FILLED rects rather than a 1px stroke on the path: a
    // centred stroke would only half-cover the outer pixels. Drawn before the
    // text clip below, which would otherwise cut the right/bottom lines away.
    this.line('if (tf->border) {');
    this.indent++;
    this.line('void* bd = as_skia_paint_fill(tf->borderColor, 1.0);');
    this.line('double bw = tf->_fieldWidth, bh = tf->_fieldHeight;');
    // Screen-space 1px lines: the thickness must NOT scale with the object. The
    // canvas transform already carries the object's scale (and the device pixel
    // ratio of this render pass), so the local thickness is one *device pixel*
    // divided by it. Measured on adl 51.4.1 (Ed7.as, window pixel scan): a
    // bordered 60x20 field keeps a 1px outline at scaleX=scaleY=2, at
    // scaleX=2/scaleY=1 (so each axis keeps its own pixel, not one shared
    // factor) and at scale 0.5. At scale 1 with dpr 1 this is exactly the
    // previous hard-coded 1.0 local unit.
    //
    // Inside a cacheAsBitmap/auto-bake pass the canvas is the OFFSCREEN surface
    // (scaled by the bake resolution), while the blit later magnifies the image by
    // the object's own scale -- so measuring the bake canvas would make a scaled
    // object's border come out scale times too thick (measured: a 60x20 field at
    // scale 2, auto-baked, scanned 4 device px per line instead of 2). The bake
    // pass therefore publishes the DESTINATION canvas scale in ASC_bake_ctm_*.
    this.line('double bsx = ASC_bake_ctm_x, bsy = ASC_bake_ctm_y;');
    this.line('if (bsx <= 0.0 || bsy <= 0.0) as_skia_canvas_total_scale(canvas, &bsx, &bsy);');
    this.line('if (bsx <= 0.0) bsx = 1.0;');
    this.line('if (bsy <= 0.0) bsy = 1.0;');
    this.line('double btx = ASC_render_scale / bsx, bty = ASC_render_scale / bsy;');
    this.line('as_skia_canvas_draw_rect(canvas, 0.0, 0.0, bw + btx, bty, bd);');
    this.line('as_skia_canvas_draw_rect(canvas, 0.0, bh, bw + btx, bty, bd);');
    this.line('as_skia_canvas_draw_rect(canvas, 0.0, 0.0, btx, bh + bty, bd);');
    this.line('as_skia_canvas_draw_rect(canvas, bw, 0.0, btx, bh + bty, bd);');
    this.line('as_skia_paint_delete(bd);');
    this.indent--;
    this.line('}');
    this.line('if (tf->text != NULL && tf->defaultTextFormat != NULL) {');
    this.indent++;
    this.line('as_tf_apply_autosize(tf);');
    this.line('void* para = as_tf_paragraph(tf);');
    this.line('if (para != NULL) {');
    this.indent++;
    this.line('double lh = as_tf_line_height(tf);');
    this.line('int vis = as_tf_visible_lines(tf);');
    this.line('int lc = as_tf_line_count(tf);');
    this.line('int maxs = lc - vis + 1; if (maxs < 1) maxs = 1;');
    this.line('int top = tf->scrollV; if (top < 1) top = 1; if (top > maxs) top = maxs;');
    this.line('double scrollY = (double)(top - 1) * lh;');
    // Horizontal pan: a wordWrap=false field clips its text and scrollH pans it
    // within [0, maxScrollH]; a wrapping field never pans (maxScrollH == 0). AIR has
    // no `hscroll` switch -- scrollH/maxScrollH always work, which is why the old
    // gate on an invented `hscroll` property made maxScrollH read 0 for ordinary
    // AIR-compatible code.
    this.line('int maxsh = TextField_get_maxScrollH((void*)tf);');
    this.line('int leftpx = tf->_scroll_h;');
    this.line('if (leftpx < 0) leftpx = 0; if (leftpx > maxsh) leftpx = maxsh;');
    this.line('double scrollX = (double)leftpx;');
    // Block shift for horizontalAlign when the paragraph carries none itself
    // (non-wrapping field): AIR centers/right-aligns inside the field box anyway.
    this.line('double alignDx = as_tf_align_dx(tf);');
    this.line('as_skia_canvas_save(canvas);');
    this.line('as_skia_canvas_clip_rect(canvas, 0.0, 0.0, tf->_fieldWidth, tf->_fieldHeight);');
    // AIR stretches a field's glyphs by the ACCUMULATED scaleY only: scaleX does
    // NOT widen the text. Measured on adl 51.4.1 with the same Main.as on both
    // sides (temp/tfswc case ⑯, window screenshot + ARGB dump): a 12pt run whose
    // nominal ink is 165pt renders 165pt at (scaleX,scaleY) = (1,1), (2,1),
    // (0.5,1) and at a parent scaleX=2 -- while (1,2)/(2,2) render 329.5pt and
    // (1,0.5) renders 82.5pt. i.e. the rendered glyph size = nominal * scaleY and
    // the on-screen box = local * scaleX. Our canvas already carries the field's
    // full (non-uniform) transform, so post-concatenating scale(sy/sx, 1) turns
    // the glyph transform into a uniform one at the vertical scale. The clip above
    // is issued BEFORE this on purpose: the visible box does follow scaleX (Skia
    // maps a clip through the CTM in force at clip time), and only the glyphs are
    // normalised. Without this the TalkMED subtitle skin's `ctime` (placement
    // scaleX 1.2246) painted its runs 22% wider than adl (阶段一百六十九).
    //
    // The factor comes from the CTM the content will FINALLY land on, using the
    // same ASC_bake_ctm_* idiom as the border above: inside a cacheAsBitmap/filter
    // bake the canvas carries the bake resolution rather than the object, so the
    // destination scale is the only honest measure. A TextField's own
    // BitmapData.draw rebuilds it in LOCAL space (measured on adl 51.4.1 via
    // temp/tfswc case ⑯c: `bmd.draw(tf)` dumps the identical raster for a plain
    // field and for scaleY=2, i.e. AIR ignores the object's own transform there),
    // and there ASC_bake_ctm_* is 0 so the canvas' uniform bake scale yields
    // ratio 1 -- exactly what that path needs.
    this.line('double tsx = ASC_bake_ctm_x, tsy = ASC_bake_ctm_y;');
    this.line('if (tsx <= 0.0 || tsy <= 0.0) as_skia_canvas_total_scale(canvas, &tsx, &tsy);');
    this.line('if (tsx > 0.0 && fabs(tsy / tsx - 1.0) > 1e-9) as_skia_canvas_scale(canvas, tsy / tsx, 1.0);');
    // Selection highlight (drawn behind the glyphs, paragraph-relative).
    // Selection highlight. Two measured rules (SelFocus probe, adl 51.4.1):
    //   1. it is drawn ONLY on the FOCUSED field — setSelection on an unfocused
    //      field paints no band at all, and losing focus makes the band disappear
    //      while the selection itself stays;
    //   2. the band is a fixed OPAQUE light blue (181,213,255) whichever colours
    //      the field uses, and the selected glyphs are drawn pure black on top of
    //      it (also on every field colour) — so a dark field does NOT get a dark
    //      band, and the text must be re-coloured rather than left as it is.
    this.line('int selVis = (as_focus_obj == (void*)tf) && tf->_sel_begin >= 0 && tf->_sel_end > tf->_sel_begin;');
    this.line('double rl[16], rt[16], rr[16], rb[16];');
    this.line('int nrects = 0;');
    // Selection edges translated from BYTE offsets to the paragraph's UTF-16
    // indices (see as_tf_utf16_index); shared by the highlight and the black-glyph
    // pass below, so it is computed once and stays in scope for both.
    this.line('int selB = as_tf_utf16_index(tf, tf->_sel_begin), selE = as_tf_utf16_index(tf, tf->_sel_end);');
    // One rect per (wrapped) line, so a long selection can span hundreds of them:
    // walk the range in pages of 16 instead of taking only the first page. AIR
    // paints every VISIBLE selected line (measured: the demo's scrolled trace
    // field highlights nothing when Cmd+A selects ~90 lines and only the first
    // 16 rects are used — they lie above the scroll window and get clipped).
    this.line('if (selVis) {');
    this.indent++;
    this.line('void* hp = as_skia_paint_fill(0xB5D5FFu, 1.0);');
    this.line('int skip = 0, nr = 0;');
    this.line('for (;;) {');
    this.indent++;
    this.line('nr = as_skia_textlayout_rects_for_range(para, selB, selE, skip, rl, rt, rr, rb, 16);');
    this.line('if (nr <= 0) break;');
    this.line('for (int i = 0; i < nr; i++) { as_skia_canvas_draw_rect(canvas, 2.0 + alignDx - scrollX + rl[i], 2.0 - scrollY + rt[i], rr[i] - rl[i], rb[i] - rt[i], hp); }');
    this.line('nrects += nr; skip += nr;');
    this.line('if (nr < 16) break;');
    this.indent--;
    this.line('}');
    this.line('as_skia_paint_delete(hp);');
    this.indent--;
    this.line('}');
    this.line('as_skia_textlayout_paint(para, canvas, 2.0 + alignDx - scrollX, 2.0 - scrollY);');
    // The black glyphs of the selected range: the SAME layout is painted again
    // inside a layer whose paint forces every pixel to black while keeping its
    // coverage, clipped to the selection rectangles. Re-using one layout (instead
    // of laying the text out a second time in black) is what keeps this exact —
    // identical metrics, identical antialiased edges.
    this.line('if (nrects > 0) {');
    this.indent++;
    this.line('void* bp = as_skia_paint_black();');
    this.line('int skip2 = 0, nr2 = 0;');
    this.line('for (;;) {');
    this.indent++;
    this.line('nr2 = as_skia_textlayout_rects_for_range(para, selB, selE, skip2, rl, rt, rr, rb, 16);');
    this.line('if (nr2 <= 0) break;');
    this.line('as_skia_canvas_save_layer_paint(canvas, bp);');
    this.line('for (int i = 0; i < nr2; i++) {');
    this.indent++;
    this.line('as_skia_canvas_save(canvas);');
    this.line('as_skia_canvas_clip_rect(canvas, 2.0 + alignDx - scrollX + rl[i], 2.0 - scrollY + rt[i], rr[i] - rl[i], rb[i] - rt[i]);');
    this.line('as_skia_textlayout_paint(para, canvas, 2.0 + alignDx - scrollX, 2.0 - scrollY);');
    this.line('as_skia_canvas_restore(canvas);');
    this.indent--;
    this.line('}');
    this.line('as_skia_canvas_restore(canvas);');
    this.line('skip2 += nr2;');
    this.line('if (nr2 < 16) break;');
    this.indent--;
    this.line('}');
    this.line('as_skia_paint_delete(bp);');
    this.indent--;
    this.line('}');
    // Insertion caret (阶段一百三十五). Drawn ONLY on the FOCUSED, SELECTABLE, INPUT
    // field -- the same gate the selection highlight uses, plus the type check AIR
    // applies: measured on adl 51.4.1, a focused selectable DYNAMIC field shows no
    // caret at all (it still shows the selection band when dragged), so the caret is
    // an input affordance rather than a selection one. And ONLY in a window/compose
    // pass (ASC_caret_pass), because AIR's caret is a player overlay rather than
    // part of the field's rasterization (measured: BitmapData.draw excludes it).
    // A 1 DEVICE-pixel vertical bar at the caret's paragraph box, in the field's
    // text colour, blinking on a ~500 ms half period whose clock restarts on focus /
    // caret move / keystroke (as_tf_blink_reset) so it is solid right after the user
    // acts. A focused field is never served from a bake (see the cache guard in
    // as_render_object), so the caret is repainted live each frame.
    this.line('if (ASC_caret_pass && as_focus_obj == (void*)tf && tf->selectable && as_tf_is_input(tf)) {');
    this.indent++;
    this.line('double kcx = 0.0, kcy = 0.0, kch = 0.0;');
    this.line('if (as_tf_caret_on() && as_skia_textlayout_caret_rect(para, as_tf_utf16_index(tf, as_tf_caret(tf)), &kcx, &kcy, &kch)) {');
    this.indent++;
    this.line('unsigned kcol = (tf->textColor != 0u) ? tf->textColor : (unsigned)as_v_num_val(tf->defaultTextFormat->color);');
    // 1 device pixel wide, like the border rule: the canvas already carries the
    // device ratio * ancestor scale * own scale, so divide the caller's total scale
    // out (the bake pass publishes the DESTINATION scale in ASC_bake_ctm_*).
    this.line('double ksx = ASC_bake_ctm_x, ksy = ASC_bake_ctm_y;');
    this.line('if (ksx <= 0.0 || ksy <= 0.0) as_skia_canvas_total_scale(canvas, &ksx, &ksy);');
    this.line('if (ksx <= 0.0) ksx = 1.0;');
    this.line('double kw = ASC_render_scale / ksx;');
    this.line('if (kw <= 0.0) kw = 1.0;');
    this.line('void* kp = as_skia_paint_fill(kcol, 1.0);');
    this.line('as_skia_canvas_draw_rect(canvas, 2.0 + alignDx - scrollX + kcx, 2.0 - scrollY + kcy, kw, kch, kp);');
    this.line('as_skia_paint_delete(kp);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    // IME composition preview: the marked text is NOT in .text (it is not committed
    // yet), so it is not part of the paragraph above -- it is painted here, at the
    // caret it will be inserted at, with a 1px underline, the way a platform IME
    // shows composing text. Its own paragraph is built with the field's format so
    // the glyphs and their size match the committed text that follows; `collapse`
    // is on because a composition string is a single line (SDL_TEXTEDITING carries
    // no newlines), and there is no wrap width. Transient by nature (one field
    // composes at a time, and only while a key is in flight), so it is built and
    // released here rather than cached on the field.
    this.line('if (tf->_comp != NULL && tf->_comp[0] != 0) {');
    this.indent++;
    this.line('double ccx = 0.0, ccy = 0.0, cch = 0.0;');
    this.line('if (as_skia_textlayout_caret_rect(para, as_tf_utf16_index(tf, as_tf_caret(tf)), &ccx, &ccy, &cch)) {');
    this.indent++;
    this.line('TextFormat* cf = tf->defaultTextFormat;');
    this.line('unsigned ccol = (tf->textColor != 0u) ? tf->textColor : (unsigned)as_v_num_val(cf->color);');
    this.line('void* cpara = as_skia_textlayout_new_leading(tf->_comp, cf->font, as_v_num_val(cf->size), as_v_bool_val(cf->bold) ? 1 : 0, as_v_bool_val(cf->italic) ? 1 : 0, ccol, as_v_num_val(cf->leading), 0.0, 0, 1);');
    this.line('if (cpara != NULL) {');
    this.indent++;
    this.line('double px = 2.0 + alignDx - scrollX + ccx;');
    this.line('double py = 2.0 - scrollY + ccy;');
    this.line('as_skia_textlayout_paint(cpara, canvas, px, py);');
    this.line('void* up = as_skia_paint_fill(ccol, 1.0);');
    this.line('as_skia_canvas_draw_rect(canvas, px, py + as_skia_textlayout_height(cpara), as_tf_longest_line(cpara), 1.0, up);');
    this.line('as_skia_paint_delete(up);');
    this.line('as_skia_textlayout_delete(cpara);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.line('as_skia_canvas_restore(canvas);');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('} else if (as_is(o, &DisplayObjectContainer_vt)) {');
    this.indent++;
    this.line('DisplayObjectContainer* c = (DisplayObjectContainer*)o;');
    // A Sprite/MovieClip may paint its own graphics; AIR draws them UNDER the
    // children (stage 94·5), so they go before the child loop.
    this.line('Graphics* sg = as_graphics_of(o);');
    this.line('if (!as_graphics_empty(sg)) as_graphics_paint(canvas, sg);');
    this.line('if (c->children != NULL) {');
    this.indent++;
    this.line('for (int i = 0; i < c->children->length; i++) as_render_object(canvas, (DisplayObject*)as_v_obj_val(c->children->data[i]));');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    this.indent--;
    this.line('}');
    // Stage.render(width, height, path): non-standard test hook (like dispatchMouse)
    // that rasterizes the whole tree offscreen and encodes it to PNG. The surface is
    // created at *physical* pixel size and the canvas is scaled by the device ratio,
    // so AIR's <requestedDisplayResolution>high gives a crisp PNG while AS3 code keeps
    // working in logical stage coordinates.
    this.line('void Stage_render(void* _this, double width, double height, char* path) {');
    this.indent++;
    this.line('Stage* st = (Stage*)_this;');
    this.line('int pw = (int)width, ph = (int)height;');
    this.line('double scale = as_window_device_scale((int)width, (int)height, &pw, &ph);');
    this.line('void* surface = as_skia_surface_new(pw, ph);');
    this.line('if (surface == NULL) return;');
    this.line('void* canvas = as_skia_surface_canvas(surface);');
    this.line('st->stage_w = (int)width; st->stage_h = (int)height; st->stage_scale = scale;');
    this.line('as_skia_canvas_scale(canvas, scale, scale);');
    this.line('as_skia_canvas_clear(canvas, st->stage_color);');
    this.line('ASC_render_scale = scale;');
    // Refresh the roll-over target before the pass so the MovieClip button states
    // this render settles reflect the live pointer (Stage.render is the headless
    // twin of the window paint; a test that only calls dispatchMouse keeps the
    // target that event stored).
    this.line('as_mouse_refresh_target((DisplayObject*)_this);');
    this.line('as_render_fp((DisplayObject*)_this);');
    // Stage.render is this runtime's SCREENSHOT hook (AIR has no such API): include
    // the caret overlay so the PNG shows what the window shows. BitmapData.draw and
    // cacheAsBitmap bakes deliberately do NOT (they match adl, see ASC_caret_pass).
    this.line('ASC_caret_pass = 1;');
    this.line('as_render_object(canvas, (DisplayObject*)_this);');
    this.line('ASC_caret_pass = 0;');
    this.line('as_skia_surface_save_png(surface, path);');
    this.line('as_skia_surface_delete(surface);');
    this.indent--;
    this.line('}');
    // Stage.showWindow(width, height, title): rasterizes the tree offscreen, then
    // presents the pixels in an SDL2 window and blocks on the event loop (stage
    // 39). Mouse input is forwarded back into the AS3 event system through the
    // callbacks below: on_mouse routes to Stage_dispatchMouse (hit test + bubble),
    // and the render helper re-rasterizes the (possibly mutated) tree after each
    // event so the window reflects listener-driven changes. Offscreen-only builds (no
    // ASC_USE_WINDOW) still compile: the helper is a no-op and the function
    // simply renders and returns.
// ------------------------------------------------------------------
    // Per-window state (阶段八十九·七十一: AIR multi-window).
    //
    // Before this stage there was exactly one window and its state lived in a
    // handful of ASC_win_* globals. AIR's NativeWindow makes the window count a
    // runtime value, so the state moves into a table indexed by the glue layer's
    // window id. The id is passed to every callback, and index 0 is ALWAYS the
    // app's initial window: the boot code opens it before any AS3 can run, and
    // the glue's own first allocation is 0 as well, so both sides agree on it
    // without a round trip.
    //
    // ASC_MAX_WINDOWS must match SK_MAX_WINDOWS in window_glue.cc / web_glue.cc.
    // ------------------------------------------------------------------
    this.line('#define ASC_MAX_WINDOWS 16');
    this.line('typedef struct {');
    this.indent++;
    // There is deliberately no `used` flag here: the glue layer owns window
    // liveness and, because a glue id is only ever handed out once per live
    // window, a valid id indexes a valid slot. An AS3-side flag would have to be
    // maintained in lockstep with the glue and any drift would silently make a
    // live window look dead (which is exactly what happened while developing
    // this: Event.CLOSE was dropped because the mirror flag was never set).
    // This window composes on the GPU: a CAMetalLayer on macOS, a D3D12 swapchain
    // on Windows, either way rendered through the shared GrDirectContext. Every
    // window may — the backend state is per window (keyed by this same id) — and
    // under ASC_RENDER_WINGPU that is the default for a NativeWindow too, because
    // AIR's NativeWindowRenderMode.AUTO picks the GPU. Only an explicit
    // renderMode="cpu" asks for the CPU raster surface this file creates below.
    this.line('int is_gpu;');
    this.line('void* window;');   // the NativeWindow object, or NULL for the initial window
    this.line('Stage* stage;');
    this.line('void* canvas;');
    this.line('void* surface;');
    this.line('double scale;');   // device pixel ratio (2.0 on a Retina window)
    this.line('int design_w, design_h;');  // size the window was asked for
    this.line('int lw, lh;');              // current logical (client) size
    this.line('int pw, ph;');              // current physical drawable size
    this.line('double cx, cy, ox, oy;');   // content scale (scaleMode) + offset (align)
    this.line('int closed;');     // NativeWindow.closed
    this.line('int resizable, maximizable, minimizable, always_in_front, transparent;');
    // NativeWindow.minSize/maxSize as the AS3 side last wrote them. The glue keeps
    // the same pair (it is what the window manager enforces during a drag); these
    // are what the getters report, because AIR answers with the value that was
    // written rather than re-querying the OS.
    this.line('double min_w, min_h, max_w, max_h;');
    // Per-frame change detector for the events the window manager produces on its
    // own: moving, resizing and the focus change that ACTIVATE/DEACTIVATE report.
    // The glue reports geometry, not events, so the transition is found by
    // comparing these snapshots at each frame boundary (see ASC_window_poll_geom).
    // A programmatic setter refreshes the same four values, which is what keeps it
    // from being reported twice.
    this.line('int snap_x, snap_y, snap_w, snap_h, snap_active;');
    // The focus flag as the LAST poll saw it, kept apart from snap_active (which is
    // what AS3's activate/deactivate pair is derived from): a window whose
    // displayState turned minimized is deactivated even while the backend still
    // reports focus, so the raw transition is what gates ACTIVATE.
    this.line('int snap_raw_active;');
    // Display state as a code (0 normal, 1 minimized, 2 maximized, 3 fullScreen),
    // so the poll can compare it with a plain int; see ASC_win_ds_code.
    this.line('int snap_ds;');
    this.line('char* title;');
    this.line('char* system_chrome;');
    this.line('char* type;');
    this.line('char* render_mode;');
    this.line('void* owner;');
    this.line('char* display_state;');
    this.indent--;
    this.line('} ASCWin;');
    this.line('static ASCWin ASC_wins[ASC_MAX_WINDOWS];');
    this.line('static ASCWin* ASC_w(int id) { return (id >= 0 && id < ASC_MAX_WINDOWS) ? &ASC_wins[id] : NULL; }');
    this.line('');
    // ---- NativeWindow events ----
    // AIR's window events come from the platform, not from the call that caused
    // them: an app that drags, resizes, focuses or closes a window hears about it
    // through MOVE/RESIZE/ACTIVATE/DEACTIVATE/CLOSING, and even a PROGRAMMATIC
    // change is reported only after the call has returned (measured on adl 51.4.1:
    // `bounds = ...` / `visible = true` report their MOVE/ACTIVATE on a later
    // event-loop turn -- temp/nwmac/events-out.txt). Our glue layer reports
    // geometry, not events, so the transitions are found by comparing a per-window
    // snapshot at the frame boundary (ASC_win_poll) instead of being forwarded from
    // a callback. That reproduces AIR's asynchrony for free, and it is also the
    // only way to see a change the OS made (a window being dragged by the user
    // dispatches no callback of its own).
    //
    // Fire `type` on the window's NativeWindow object. Returns false when a
    // listener called preventDefault() on a cancelable event -- that is what makes
    // CLOSING able to refuse a user-initiated close, exactly as AIR specifies.
    this.line('static bool ASC_win_fire(int id, const char* type, bool cancelable) {');
    this.indent++;
    this.line('ASCWin* w = ASC_w(id);');
    this.line('if (w == NULL || w->closed) return true;');
    this.line('NativeWindow* nw = as_win_wrapper(id);');
    this.line('if (nw == NULL) return true;');
    this.line('return EventDispatcher_dispatchEvent((void*)nw, Event_new((char*)type, false, cancelable));');
    this.indent--;
    this.line('}');
    // The display state as a small code, so the poll can compare it with a plain
    // int. w->display_state is the AS3 side's own record (NativeWindow.minimize/
    // maximize/restore and Stage.displayState write it), which is also what the
    // displayState getter answers -- so the poll and the getter can never disagree.
    this.line('static int ASC_win_ds_code(ASCWin* w) {');
    this.indent++;
    this.line('char* ds = (w != NULL) ? w->display_state : NULL;');
    this.line('if (ds == NULL) return 0;');
    this.line('if (strcmp(ds, "minimized") == 0) return 1;');
    this.line('if (strcmp(ds, "maximized") == 0) return 2;');
    this.line('if (strcmp(ds, "fullScreen") == 0) return 3;');
    this.line('return 0;');
    this.indent--;
    this.line('}');
    // Record the state the poll compares against. Called at window creation (so the
    // window's own initial placement is not reported as a move) and after a change
    // the AS3 side already reported itself.
    this.line('static void ASC_win_snap(int id) {');
    this.indent++;
    this.line('ASCWin* w = ASC_w(id);');
    this.line('if (w == NULL) return;');
    this.line('int x = 0, y = 0, cw = 0, ch = 0;');
    this.line('as_window_get_bounds(id, &x, &y, &cw, &ch);');
    this.line('w->snap_x = x; w->snap_y = y; w->snap_w = cw; w->snap_h = ch;');
    this.line('w->snap_active = as_window_is_active(id);');
    this.line('w->snap_raw_active = w->snap_active;');
    this.line('w->snap_ds = ASC_win_ds_code(w);');
    this.indent--;
    this.line('}');
    // NativeWindow.minSize/maxSize as the window starts out, and the floor a later
    // minSize assignment is clamped to. The tables live in the platform layer
    // (window_glue.cc sk_window_size_defaults/sk_window_size_floor): macOS starts at
    // (78,32) with max (107374182,107374182) and a floor of (2,32), Windows at
    // (136,39). A window takes them at creation — including the app's initial window,
    // which is created inside the blocking show call and therefore cannot be
    // initialised from here. This only copies what the window now has.
    this.line('static void ASC_win_limits_init(int id) {');
    this.indent++;
    this.line('ASCWin* w = ASC_w(id);');
    this.line('if (w == NULL) return;');
    this.line('int mnw = 0, mnh = 0, mxw = 0, mxh = 0;');
    this.line('as_window_get_limits(id, &mnw, &mnh, &mxw, &mxh);');
    // A `new NativeWindow()` has no OS window yet (AIR creates it when the window is
    // first shown), so the backend answers with zeros. The platform defaults are the
    // same numbers it installs on the real window, so taking them here keeps
    // minSize/maxSize correct from the constructor onward -- which is exactly when
    // AIR reports them (measured: `w.minSize` is (78,32) on macOS for a window that
    // was never shown, temp/nwmac/limits-out.txt).
    this.line('if (mxw <= 0) as_window_limits_default(&mnw, &mnh, &mxw, &mxh);');
    this.line('w->min_w = (double)mnw; w->min_h = (double)mnh;');
    this.line('w->max_w = (double)mxw; w->max_h = (double)mxh;');
    this.indent--;
    this.line('}');
    // The frame-boundary transition detector. The ORDER is AIR's own, measured for
    // every programmatic transition (temp/nwmac/events-out.txt): deactivate first
    // (a window that is going away reports the loss of focus before the state
    // change), then RESIZE before MOVE, with DISPLAY_STATE_CHANGE between them
    // (`maximize()` -> RESIZE,DISPLAY_STATE_CHANGE,MOVE; `bounds = ...` ->
    // RESIZE,MOVE), and ACTIVATE last (coming back -> DISPLAY_STATE_CHANGE,
    // ACTIVATE). The two `before` values the events carry are the snapshot's, which
    // is exactly what AIR fills in.
